local srcPath = 'TAC/lua/triune.lua'
local src = readFile(srcPath)
-- Auto AA engine source (migrated to the auto_aa plugin); global to stay under the 200-local cap
AA_CONTENT = readFile('TAC/lua/tac/auto_aa.lua')

