        ['furious discipline'] = 9,
        ['stonewall discipline'] = 180,
        ['duelist discipline'] = 72,
        ['kinetics discipline'] = 72,
        ['trueshot discipline'] = 120,
        ['weapon shield discipline'] = 18,
