    assert_eq(boxSet, 'Box Control (all)', 'Suite 96: Add All names a fixed-scope set after its scope')
    assert_eq(T.lastAssignedIndex('Box Control (all)'), #T.BOX_PRESETS, 'Suite 96: the set holds every preset')
    assert_eq(hbBox.sets[#hbBox.sets], 'Box Control (all)', 'Suite 96: the set is added to the hotbar as a tab')
    assert_eq(T.addBoxControlSet('zone', nil), 'Box Control (zone)', 'Suite 96: scoped set names stay unique')

    -- 'One box' scope: presets and sets addressed to a named character
    assert_eq(T.BOX_SCOPES[#T.BOX_SCOPES].id, 'name', 'Suite 96: the scope picker offers a single named box')
    assert_eq(T.boxScopeWord('bar'), '{scope}', 'Suite 96: boxScopeWord: hotbar switch -> token')
    assert_eq(T.boxScopeWord('group'), 'group', 'Suite 96: boxScopeWord: fixed scope -> itself')
    assert_eq(T.boxScopeWord('name', ' Bob '), 'Bob', 'Suite 96: boxScopeWord: name scope -> trimmed name')
    assert_eq(T.boxScopeWord('name', ''), nil, 'Suite 96: boxScopeWord: name scope needs a name')
    assert_eq(T.boxScopeWord('name', 'Bob Smith'), nil, 'Suite 96: boxScopeWord: a name is one word')
    local named = T.boxPresetButton(T.BOX_PRESETS[1], 'name', 'Bob')
    assert_true(named.cmd == '/ac net Bob run' and named.label == 'Run (Bob)', 'Suite 96: named preset -> /ac net Bob run')
    T.browser.boxScope, T.browser.boxName = 'name', 'Bob'
    assert_eq(T.scanBoxControl()[#T.BOX_PRESETS].button.cmd, '/ac net camp Bob', 'Suite 96: named Camp Here -> /ac net camp Bob')
    assert_eq(T.addBoxControlSet('name', nil, 'Bob'), 'Box Control (Bob)', 'Suite 96: a named set is named after the box')
    assert_eq(T.addBoxControlSet('name', nil, ''), nil, 'Suite 96: a named set without a name is refused')
    T.browser.boxScope, T.browser.boxName = 'all', ''

    -- Custom command builder: any /ac command through /ac net <scope>
    local lines, why = T.boxCommandLines('/ac burn on\n\n  manual  \n/camp')
    assert_eq(table.concat(lines, '|'), '/ac burn on|/ac manual|/camp', 'Suite 96: boxCommandLines keeps full slash lines, puts /ac back on bare ones, skips blanks')
    lines, why = T.boxCommandLines('net all pause')
    assert_true(lines == nil and why:find('nested', 1, true), 'Suite 96: nested net lines are refused')
    lines, why = T.boxCommandLines('/ac net all pause')
    assert_true(lines == nil and why:find('nested', 1, true), 'Suite 96: "/ac net" lines are refused too')
    lines, why = T.boxCommandLines('   ')
    assert_true(lines == nil and why:find('first', 1, true), 'Suite 96: an empty command is refused')
    assert_eq(T.defaultBoxLabel({ '/ac burn on' }), 'Burn on', 'Suite 96: default label drops /ac and capitalises')
    assert_eq(T.defaultBoxLabel({ '/camp' }), 'Camp', 'Suite 96: default label for a game command drops the slash')
    assert_eq(T.defaultBoxLabel({ '/ac pullhp <0-95>' }), 'Pullhp', 'Suite 96: default label drops a placeholder argument')
    local custom = T.customBoxButton('burn on', '', 'bar')
    assert_true(custom.cmd == '/ac net {scope} /ac burn on' and custom.label == 'Burn on' and custom.timerType == 'None' and custom.buttonColor[1] == 60, 'Suite 96: custom hotbar-switch button carries the token and a bare label')
    custom = T.customBoxButton('/ac manual\n/camp', 'Camp All', 'group')
    assert_eq(custom.cmd, '/ac net group /ac manual\n/ac net group /camp', 'Suite 96: every custom line is prefixed with /ac net <scope> and kept as a full slash command')
    assert_eq(custom.label, 'Camp All', 'Suite 96: a typed label is kept as is')
    custom = T.customBoxButton('pause', nil, 'name', 'Bob')
    assert_true(custom.cmd == '/ac net Bob /ac pause' and custom.label == 'Pause (Bob)', 'Suite 96: custom named button -> /ac net Bob /ac pause')
    local none, whyNone = T.customBoxButton('pause', '', 'name', '')
    assert_true(none == nil and whyNone:find('name', 1, true), 'Suite 96: custom named button needs a box name')
    cmds = {}
    T.runButton(T.customBoxButton('/dzquit', '', 'bar'), nil, hbBox)
    assert_eq(cmds[#cmds], '/ac net all /dzquit', 'Suite 96: a custom {scope} button resolves through the hotbar switch')

    -- Live scope: `{scope}` buttons follow the hotbar's Group / Zone / All switch at press time
    assert_eq(T.hotbarUsesBoxScope(hbBox), false, 'Suite 96: fixed-scope sets do not bring up the switch')
    local liveSet = T.addBoxControlSet('bar', hbBox)
    assert_eq(liveSet, 'Box Control', 'Suite 96: the hotbar-switch set is plain "Box Control"')
    assert_eq(T.hotbarUsesBoxScope(hbBox), true, 'Suite 96: a bar holding {scope} buttons shows the switch')
    assert_eq(T.hotbarBoxScope(hbBox), 'all', 'Suite 96: a new hotbar sends to all boxes')
    cmds = {}
    T.fireButton('Box Control', 1, hbBox)
    assert_eq(cmds[#cmds], '/ac net all run', 'Suite 96: {scope} resolves to the hotbar scope when clicked (all)')
    assert_eq(T.setHotbarBoxScope(hbBox, 'group', 1), true, 'Suite 96: setHotbarBoxScope switches the bar')
    assert_eq(T.setHotbarBoxScope(hbBox, 'group', 1), false, 'Suite 96: ...and reports no change when already set')
    assert_eq(T.setHotbarBoxScope(hbBox, 'bogus', 1), false, 'Suite 96: ...and refuses unknown scopes')
    assert_eq(T.hotbarBoxScope(hbBox), 'group', 'Suite 96: the switch persists on the hotbar')
    cmds = {}
    T.fireButton('Box Control', 1, hbBox)
    assert_eq(cmds[#cmds], '/ac net group run', 'Suite 96: the same button now goes to the group')
    local liveFollow = nil
    for i, key in pairs(T.getDb().sets['Box Control']) do if T.getDb().buttons[key].label == 'Follow Me' then liveFollow = i end end
    cmds = {}
    T.fireButton('Box Control', liveFollow, hbBox)
    assert_eq(table.concat(cmds, ','), '/ac net group ma ${Me.CleanName},/ac net group assist chase', 'Suite 96: every line of a multi-line {scope} button is resolved')
    cmds = {}
    T.execBySetIndex('Box Control', 1)
    assert_eq(cmds[#cmds], '/ac net group run', 'Suite 96: /ac btn exec resolves through the hotbar showing the set')
    assert_eq(T.resolveBoxScope('/ac net {scope} camp', nil), '/ac net all camp', 'Suite 96: no hotbar -> all')
    assert_eq(T.resolveBoxScope('/ac pause', hbBox), '/ac pause', 'Suite 96: commands without the token pass through')
    T.handleCommand({ 'scope', 'zone' })
    assert_eq(T.hotbarBoxScope(hbBox), 'zone', 'Suite 96: /ac btn scope zone targets the bar holding {scope} buttons')
    T.handleCommand({ 'scope', 'next' })
    assert_eq(T.hotbarBoxScope(hbBox), 'all', 'Suite 96: /ac btn scope next cycles group -> zone -> all')
    T.handleCommand({ 'scope', 'next' })
    assert_eq(T.hotbarBoxScope(hbBox), 'group', 'Suite 96: ...and wraps around')
    T.handleCommand({ 'scope', 'grp', '1' })
    assert_eq(T.hotbarBoxScope(hbBox), 'group', 'Suite 96: grp alias + explicit hotbar number')
    T.handleCommand({ 'scope', 'all', '99' })
    assert_eq(T.hotbarBoxScope(hbBox), 'group', 'Suite 96: an unknown hotbar number changes nothing')
    T.removeSetFromHotbar(hbBox, 'Box Control')
    assert_eq(T.hotbarUsesBoxScope(hbBox), false, 'Suite 96: removing the set hides the switch again')
    local reloaded = T.normalizeDb({ version = T.getDb().version, buttons = {}, sets = {}, characters = { [T.charKey()] = { hotbars = { { title = 'x', boxScope = 'nope' }, { title = 'y', boxScope = 'zone' } } } } })
    local rh = reloaded.characters[T.charKey()].hotbars
    assert_true(rh[1].boxScope == 'all' and rh[2].boxScope == 'zone' and rh[1].showScopeBar == true, 'Suite 96: load clamps boxScope and defaults showScopeBar')
    T.browser.boxScope = 'bar'

    -- Triune slash commands pick list (curated core list + live plugin help lines)
    core.runtime.pluginManager = { helpLines = function()
        return {
            '  \ag/ac cursorui | cursorwin | cursormgr\ax - Toggle the Cursor Item Manager window',
            '  \ag/ac btn <n>\ax - Show / hide hotbar n     \ag/ac btn new\ax - Create a hotbar',
            '  \ag/ac run\ax - duplicate of a core command (must be skipped)',
            'not a help line',
        }
    end }
    local parsed = T.parseHelpLine('  \ag/ac btn <n>\ax - Show / hide hotbar n     \ag/ac btn new\ax - Create a hotbar')
    assert_eq(#parsed, 2, 'Suite 96: a help line with two cmd - desc pairs yields two entries')
    assert_true(parsed[1].button.cmd == '/ac btn <n>' and parsed[1].needsEdit == true and parsed[1].sub:find('Show / hide hotbar n', 1, true) ~= nil, 'Suite 96: placeholder commands are flagged for the editor')
    assert_true(parsed[2].button.cmd == '/ac btn new' and parsed[2].needsEdit == false, 'Suite 96: plain commands become buttons as-is')
    assert_eq(T.parseHelpLine('  \ag/ac cursorui | cursorwin | cursormgr\ax - Toggle the Cursor Item Manager window')[1].button.cmd, '/ac cursorui', 'Suite 96: alternatives keep the first form')
    local cmdList = T.scanCommands()
    assert_eq(#cmdList, #T.CORE_COMMANDS + 2, 'Suite 96: scanCommands lists the core commands plus the new plugin help commands (cursorui and run already in the core list)')
    local seenCmd = {}
    local dupes = 0
    for _, e in ipairs(cmdList) do
        if seenCmd[e.button.cmd] then dupes = dupes + 1 end
        seenCmd[e.button.cmd] = true
    end
    assert_eq(dupes, 0, 'Suite 96: command list has no duplicate commands (plugin lines de-duplicated against the core list)')
    assert_true(seenCmd['/ac burn on'] and seenCmd['/ac puller camp'] and seenCmd['/ac assist backline'] and seenCmd['/ac ma target'], 'Suite 96: fixed variants (burn on, modes, MA target) are present')
    assert_true(seenCmd['/ac cursorui'] and seenCmd['/ac btn new'], 'Suite 96: plugin help commands are present')
    assert_true(T.commandNeedsEdit('/ac range <dist>') and not T.commandNeedsEdit('/ac run'), 'Suite 96: commandNeedsEdit spots placeholders')
    local grpCount = 0
    for _, c in ipairs(T.CORE_COMMANDS) do if c.cmd:sub(1, 1) ~= '/' then grpCount = grpCount + 1 end end
    assert_eq(grpCount, 0, 'Suite 96: every curated command is a slash command')
    -- A placeholder entry opens the editor instead of placing a button
    T.getDb().sets.Primary = { [1] = 'Ok' }
    T.openBrowser('Cmd', 'assign', { hbId = 1, setName = 'Primary', index = 8 })
    local rangeEntry = nil
    for _, e in ipairs(cmdList) do if e.button.cmd == '/ac range <dist>' then rangeEntry = e end end
    assert_eq(T.pickBrowserEntry(rangeEntry), true, 'Suite 96: picking a placeholder command succeeds')
    assert_true(T.edit.open and T.edit.index == 8 and T.edit.tmp.cmd == '/ac range <dist>' and T.edit.tmp.label == 'Range', 'Suite 96: ...by opening the editor pre-filled at the target slot')
    assert_nil(T.buttonAt('Primary', 8), 'Suite 96: nothing is placed until the editor saves')
    T.closeEditor()
    local runEntry = nil
    for _, e in ipairs(cmdList) do if e.button.cmd == '/ac burn on' then runEntry = e end end
    T.openBrowser('Cmd', 'assign', { hbId = 1, setName = 'Primary', index = 8 })
    T.pickBrowserEntry(runEntry)
    assert_true(T.buttonAt('Primary', 8) ~= nil and T.buttonAt('Primary', 8).cmd == '/ac burn on' and T.buttonAt('Primary', 8).label == 'Burn On', 'Suite 96: a plain command is placed directly')
    core.runtime.pluginManager = nil

    -- Picking: into a chosen slot (one-shot) and into the first free slot (stays open)
    T.getDb().sets.Primary = { [1] = 'Ok' }
    T.openBrowser('AA', 'assign', { hbId = 1, setName = 'Primary', index = 4 })
    assert_true(T.browser.open and T.browser.tab == 'AA', 'Suite 96: openBrowser opens on the requested tab')
    assert_eq(#T.browserList('AA'), 2, 'Suite 96: browserList scans and caches the tab')
    assert_eq(T.pickBrowserEntry(aas[1]), true, 'Suite 96: picking an entry into a slot succeeds')
    local placed = T.buttonAt('Primary', 4)
    assert_true(placed ~= nil and placed.cmd == '/alt act 1100' and placed.showLabel == false, 'Suite 96: picked AA button placed in the chosen slot (icon buttons hide the label)')
    assert_eq(T.browser.open, false, 'Suite 96: slot-targeted pick closes the browser')
    T.openBrowser('Gem', 'assign', { hbId = 1, setName = 'Primary' })
    assert_eq(T.firstFreeSlot('Primary'), 2, 'Suite 96: firstFreeSlot finds the first gap')
    T.pickBrowserEntry(gemList[1])
    assert_eq(T.buttonAt('Primary', 2).cmd, '/cast 1', 'Suite 96: gear-menu pick lands in the first free slot')
    assert_true(T.browser.open and T.browser.target.index == nil, 'Suite 96: gear-menu flow keeps the browser open for more picks')
    T.pickBrowserEntry(discs[1])
    assert_eq(T.buttonAt('Primary', 3).cmd, '/disc Evasive Discipline', 'Suite 96: next pick fills the next free slot')
    T.openBrowser('Item', 'assign', nil)
    assert_eq(T.pickBrowserEntry(items[1]), false, 'Suite 96: picking with no target set is refused')

    -- Picking into the editor
    T.openEditor(1, 'Primary', 9, nil)
    T.openBrowser('Ability', 'editor', nil)
    assert_eq(T.pickBrowserEntry(abil[1]), true, 'Suite 96: editor mode fills the open editor')
    assert_true(T.edit.tmp.cmd == '/doability "Kick"' and T.edit.tmp.timerType == 'Ability' and T.edit.dirty == true, 'Suite 96: editor fields filled and marked dirty')
    assert_nil(T.buttonAt('Primary', 9), 'Suite 96: editor mode does not create a button until saved')
    T.closeEditor()
    T.browser.open = false

    -- /ac btn add <what> (hotbar 1's only set is the Box Control set added above)
    T.state.activeSet = {}
    inst.onCommand('btn', { 'btn', 'add', 'discs' })
    assert_true(T.browser.open and T.browser.tab == 'Disc' and T.browser.target and T.browser.target.hbId == 1 and T.browser.target.setName == 'Box Control (all)', 'Suite 96: /ac btn add discs opens the browser on the Discs tab targeting the first hotbar with a set')
    inst.onCommand('btn', { 'btn', 'add', 'box' })
    assert_eq(T.browser.tab, 'Box', 'Suite 96: /ac btn add box opens the Box Control tab')
    T.browser.open = false
    ctrl.show_buttons = true
    local okDraw2, errDraw2 = pcall(inst.onDrawUI)
    assert_true(okDraw2, 'Suite 96: onDrawUI still renders with browser state (' .. tostring(errDraw2) .. ')')
    T.browser.open = true
    okDraw2, errDraw2 = pcall(inst.onDrawUI)
    assert_true(okDraw2, 'Suite 96: browser window renders under the mock (' .. tostring(errDraw2) .. ')')
    T.browser.open = false
    -- A bar holding hotbar-switch buttons draws the Group / Zone / All row (both layouts).
    local hbLive = T.hotbars()[1]
    T.addBoxControlSet('bar', hbLive)
    assert_true(T.hotbarUsesBoxScope(hbLive), 'Suite 96: the live-scope set is back on hotbar 1 for the draw pass')
    okDraw2, errDraw2 = pcall(inst.onDrawUI)
    assert_true(okDraw2, 'Suite 96: hotbar with the box scope switch renders under the mock (' .. tostring(errDraw2) .. ')')
    hbLive.compact = true
    okDraw2, errDraw2 = pcall(inst.onDrawUI)
    assert_true(okDraw2, 'Suite 96: compact hotbar with the box scope switch renders under the mock (' .. tostring(errDraw2) .. ')')
    hbLive.compact = false

    -- 20. Destroy releases the binds and the Box Network subscription
    inst.onDestroy()
    assert_nil(binds['/btn'], 'Suite 96: onDestroy unbinds /btn')
    assert_nil(boxnetSubs.buttons_saved, 'Suite 96: onDestroy unsubscribes from Box Network')

    -- 21. Core wiring
    assert_true(src:find("'buttons.lua',", 1, true) ~= nil, 'Suite 96: core discover() probes buttons.lua')
    assert_true(src:find("cmd = '/ac btn [n|new|exec <set> <index>|import bm]'", 1, true) ~= nil, 'Suite 96: help table documents /ac btn')
    local btnSrc = readFile('TAC/lua/tac/buttons.lua')
    assert_true(btnSrc:find('mq.delay(', 1, true) == nil, 'Suite 96: the plugin never calls mq.delay directly')
    assert_true(btnSrc:find('core.pushTheme()', 1, true) ~= nil, 'Suite 96: hotbars use the core theme')

    os.remove(tmpPath)
    os.remove(tmpPath .. '.bak')
    os.remove(bmPath)
    print = realPrint ---@diagnostic disable-line: lowercase-global
end)()

-- ============================================================================
-- Suite 96: Box Network feed in the core (MA target, engagement, cures)
-- ============================================================================
;(function()
    print('--- Suite 96: Box Network feed in the core ---')
    local function callable(ret, fields)
        return setmetatable(fields or {}, { __call = function() return ret end })
    end
    local S = { cmds = {}, feed = nil, counters = nil, targetId = 0 }
    local spawns = {
        [50]  = { name = 'Tank', type = 'PC' },
        [777] = { name = 'a_rat', type = 'NPC' },
        [778] = { name = 'a_dead_rat', type = 'Corpse' },
        [900] = { name = 'Boxer', type = 'PC' },
    }
    local mockMq = {
        cmd = function(c) S.cmds[#S.cmds + 1] = c end,
        cmdf = function(f, ...) S.cmds[#S.cmds + 1] = string.format(f, ...) end,
        delay = function() end,
        TLO = {
            Me = { ID = function() return 1 end },
            Target = setmetatable({ ID = function() return S.targetId end, Type = function() return 'NPC' end, Dead = function() return false end },
                { __call = function() if S.targetId > 0 then return 'target' end return nil end }),
            Spawn = function(id)
                local sp = spawns[id]
                if not sp then return callable(nil, { ID = function() return 0 end, CleanName = function() return nil end }) end
                return callable('spawn', {
                    ID = function() return id end, CleanName = function() return sp.name end,
                    Type = function() return sp.type end, Dead = function() return sp.type == 'Corpse' end,
                    PctHPs = function() return sp.hp or 100 end,
                    Combat = function() return false end,
                    Target = callable(nil, { ID = function() return 0 end }),
                })
            end,
        },
    }
    local fakeApi = {
        available = function() return true end,
        peerTarget = function(name, maxAge) S.lastPeerName, S.lastMaxAge = name, maxAge return S.feed end,
        peerCounters = function(name) S.lastCounterName = name return S.counters end,
    }
    local ctrl96 = { mode = 'Assist', xtar_nav_dist = 150, ma_id = 50, ma_name = 'Tank' }
    local env = {
        ctrl = ctrl96, mq = mockMq, print = function() end,
        pluginManager = { coreApi = setmetatable({ boxnet = fakeApi }, { __index = function() return nil end }) },
        maPcId = function() return 50 end,
        isSpawnPetOrPlayer = function(id) return spawns[id] and spawns[id].type == 'PC' end,
        isHostileTarget = function(id) return spawns[id] and spawns[id].type == 'NPC' end,
        distToId = function() return 40 end,
        anyNearbyEngagedNpc = function() S.peeked = true return true end,
        lastAssistCmdAt = -100,
    }
    local boxnetApi = loadFunc(src, 'boxnetApi', env)
    env.boxnetApi = boxnetApi
    local boxnetMaTarget = loadFunc(src, 'boxnetMaTarget', env)
    env.boxnetMaTarget = boxnetMaTarget
    local boxnetCounters = loadFunc(src, 'boxnetCounters', env)
    env.boxnetCounters = boxnetCounters
    local boxnetHasCounter = loadFunc(src, 'boxnetHasCounter', env)
    env.boxnetHasCounter = boxnetHasCounter

    -- 1. API discovery through the plugin manager's core API table
    assert_eq(boxnetApi(), fakeApi, 'Suite 96: boxnetApi finds the plugin API on the core API table')
    fakeApi.available = function() return false end
    assert_nil(boxnetApi(), 'Suite 96: boxnetApi is nil while the plugin is not connected')
    fakeApi.available = function() return true end
    local savedPm = env.pluginManager
    env.pluginManager = nil
    assert_nil(loadFunc(src, 'boxnetApi', env)(), 'Suite 96: boxnetApi is nil without a plugin manager')
    env.pluginManager = savedPm

    -- 2. boxnetMaTarget resolves the MA name and asks the feed with the freshness window
    S.feed = { id = 777, name = 'a_rat', hp = 100, engaged = true }
    local fed = boxnetMaTarget(50)
    assert_eq(fed and fed.id, 777, 'Suite 96: boxnetMaTarget returns the feed target')
    assert_eq(S.lastPeerName, 'Tank', 'Suite 96: MA name resolved from the spawn')
    assert_eq(S.lastMaxAge, 3.0, 'Suite 96: 3s freshness window')
    assert_eq(boxnetMaTarget(12345) and boxnetMaTarget(12345).id, 777, 'Suite 96: falls back to ctrl.ma_name when the spawn is unknown')
    ctrl96.ma_name = ''
    assert_nil(boxnetMaTarget(12345), 'Suite 96: no name -> nil')
    ctrl96.ma_name = 'Tank'

    -- 3. targetIsEngaged trusts the MA's own engaged flag
    env.isGroupOrRaidMember = function() return false end
    env.isXTargetId = function() return false end
    local targetIsEngaged = loadFunc(src, 'targetIsEngaged', env)
    env.targetIsEngaged = targetIsEngaged
    assert_eq(targetIsEngaged(777), true, 'Suite 96: MA feed engaged -> target is engaged')
    S.feed = { id = 777, engaged = false }
    assert_eq(targetIsEngaged(777), false, 'Suite 96: MA feed not engaged and no other evidence -> not engaged')
    S.feed = { id = 555, engaged = true }
    assert_eq(targetIsEngaged(777), false, 'Suite 96: a different MA target does not engage this one')

    -- 4. maTargetId: feed answers -> no /assist, no peek; MA without target -> nil
    local maTargetId = loadFunc(src, 'maTargetId', env)
    S.feed = { id = 777, name = 'a_rat', engaged = true }
    S.cmds, S.peeked = {}, false
    assert_eq(maTargetId(), 777, 'Suite 96: maTargetId returns the fed target')
    assert_eq(#S.cmds, 0, 'Suite 96: no /assist issued when the feed answers')
    assert_eq(S.peeked, false, 'Suite 96: no XTarget peek when the feed answers')
    S.feed = false
    assert_nil(maTargetId(), 'Suite 96: MA reports no target -> nil, still no /assist')
    assert_eq(#S.cmds, 0, 'Suite 96: no /assist for an idle MA')
    S.feed = { id = 778, engaged = true }
    assert_nil(maTargetId(), 'Suite 96: a corpse from the feed is rejected')
    S.feed = { id = 900, engaged = true }
    assert_nil(maTargetId(), 'Suite 96: a PC from the feed is rejected')
    S.feed = { id = 777, engaged = false }
    assert_nil(maTargetId(), 'Suite 96: Assist mode gates on engagement even with a fed target')
    ctrl96.mode = 'Manual'
    assert_eq(maTargetId(), 777, 'Suite 96: outside Assist mode the fed target is not gated')
    ctrl96.mode = 'Assist'
    S.feed = { id = 777, engaged = true }
    env.distToId = function() return 500 end
    assert_nil(loadFunc(src, 'maTargetId', env)(), 'Suite 96: fed target beyond xtar_nav_dist is rejected')
    env.distToId = function() return 40 end
    -- no fresh feed -> legacy /assist path (the rat is on our XTarget, so it counts as engaged;
    -- "hurt" alone no longer does, since that let Assist pick up other groups' mobs)
    S.feed = nil
    S.targetId = 777
    spawns[777].hp = 60
    env.isXTargetId = function(id) return id == 777 end
    env.targetIsEngaged = loadFunc(src, 'targetIsEngaged', env)
    S.cmds = {}
    env.lastAssistCmdAt = -100
    maTargetId = loadFunc(src, 'maTargetId', env)
    assert_eq(maTargetId(), 777, 'Suite 96: without a feed the /assist path still works')
    assert_eq(S.cmds[1], '/assist Tank', 'Suite 96: legacy path issues /assist')

    -- 5. Cures: heartbeat counters replace NetBots
    S.counters = { poison = 2, disease = 0, curse = 0, corruption = 1 }
    assert_eq(boxnetCounters('Boxer').poison, 2, 'Suite 96: boxnetCounters reads the feed')
    assert_eq(boxnetHasCounter('Boxer', 'poison'), true, 'Suite 96: poison counter > 0')
    assert_eq(boxnetHasCounter('Boxer', 'disease'), false, 'Suite 96: disease counter 0')
    assert_eq(boxnetHasCounter('Boxer', 'corruption'), true, 'Suite 96: corruption counter > 0')
    assert_eq(boxnetHasCounter('', 'poison'), false, 'Suite 96: empty name -> false')
    S.counters = nil
    assert_eq(boxnetHasCounter('Boxer', 'poison'), false, 'Suite 96: no feed -> false')
    local hasAffliction = loadFunc(src, 'hasAffliction', {
        mq = mockMq, AFFLICTION_MEMBERS = { Poison = { flag = 'Poisoned', counter = 'CountersPoison', boxnet = 'poison' } },
        boxnetHasCounter = boxnetHasCounter, boxnetCounters = boxnetCounters,
    })
    S.counters = { poison = 1 }
    assert_eq(hasAffliction(900, 'Poison'), true, 'Suite 96: hasAffliction is true from Box Network counters alone (no NetBots)')
    S.counters = { poison = 0 }
    assert_eq(hasAffliction(900, 'Poison'), false, 'Suite 96: hasAffliction false when the box reports no counters')
    local isCursed = loadFunc(src, 'isCursed', { mq = mockMq, boxnetHasCounter = boxnetHasCounter })
    S.counters = { curse = 4 }
    assert_eq(isCursed(900), true, 'Suite 96: isCursed from Box Network counters')
    local isCorrupted = loadFunc(src, 'isCorrupted', { mq = mockMq, boxnetHasCounter = boxnetHasCounter })
    S.counters = { corruption = 1 }
