    assert_eq(env.isBoxPeerId(10), false, 'Suite 97: isBoxPeerId false for a non-box')

    -- 2. lowestHpAlly: boxes only when asked; group-wide callers leave them out
    local lowestHpAlly = loadFunc(src, 'lowestHpAlly', env)
