    assert_true(out:find('MQ2Nav not loaded', 1, true) ~= nil and out:find('MQ2MoveUtils not loaded', 1, true) ~= nil, 'Suite 100: plugin warnings')
    S.clickLabel = 'Load##miniLoadNav'
