    S.clickLabel = 'Full Window'
    draw()
    S.clickLabel = nil
    assert_eq(ctrl.compact, false, 'Suite 100: menu - Full Window item')
    ctrl.compact = true
    S.popupOpen = false

    -- 11. Closing the window drops compact mode (as before)
