    local selfEcho = plugin.classify("Genro tells you, 'did it work?'", ctx)
    assert_true(selfEcho.channel == 'tell_out' and selfEcho.outgoing and selfEcho.sender == nil and selfEcho.selfEcho, 'Suite 102: my own name as the tells-you sender is an echoed outgoing tell')
    assert_eq(plugin.classify(P('Genro') .. " tells you, 'linked'", ctx).channel, 'tell_out', 'Suite 102: echoed self tell with a player link')
    local linked = plugin.classify(P('Playerone') .. " tells you, 'hi'", ctx)
    assert_true(linked.isPlayer == true, 'Suite 102: link-wrapped sender flagged as a player')
    assert_true(plugin.classify("Spinevenom tells you, 'Attacking X Master.'", ctx).isPlayer == false, 'Suite 102: bare pet sender is not a player')
    -- a tell to someone offline: the game's notice is filed as that tell
    local offline = plugin.classify('bobby is not online at this time.', ctx)
    assert_true(offline.channel == 'tell_out' and offline.sender == 'Bobby' and offline.outgoing and offline.tellFail == true,
        'Suite 102: "X is not online" is an outgoing tell to X (name capitalised) flagged as undelivered')
    assert_true(plugin.classify('Bobby is not currently online.', ctx).tellFail == true, 'Suite 102: the other wording too')
    local ctx2 = { me = 'Genro', pets = {}, lastTellTo = 'Carol' }
    local nameless = plugin.classify('That player is not online.', ctx2)
    assert_true(nameless.channel == 'tell_out' and nameless.sender == 'Carol' and nameless.tellFail, 'Suite 102: the name-less notice is about the last tell sent from here')
    assert_eq(plugin.classify('That player is not online.', ctx).channel, 'system', 'Suite 102: with no tell sent from here it stays a system line')
    for _, c in ipairs(plugin.CHANNELS) do
        assert_true(type(c.id) == 'string' and c.color:match('^%x%x%x%x%x%x$') ~= nil, 'Suite 102: channel ' .. tostring(c.id) .. ' has a hex color')
    end
    for name, list in pairs(plugin.PRESETS) do
        for _, id in ipairs(list or {}) do
            local found = false
            for _, c in ipairs(plugin.CHANNELS) do if c.id == id then found = true end end
            assert_true(found, 'Suite 102: preset ' .. name .. ' references known channel ' .. id)
        end
    end

    -- 2. Links & colors
    local text, players = plugin.resolveLinks('Your [' .. IT .. '] and ' .. P('Bob') .. " says, 'hi'")
    assert_eq(text, "Your [Earthen Bracer of Fortitude (Enchanted)] and Bob says, 'hi'", 'Suite 102: item link -> name, player link -> name')
    assert_eq(players.Bob, true, 'Suite 102: player links recorded')
    assert_eq(plugin.stripColors(ESC .. '300000[X]' .. ESC .. '777777 y'), '[X] y', 'Suite 102: \\x7F color codes stripped')
    assert_eq(plugin.convertColors(ESC .. '300000[X]'), '\a#300000[X]', 'Suite 102: \\x7F color codes converted to \\a#')
    assert_eq(plugin.escapeLine('a' .. L .. 'b' .. string.char(7)), 'a<LINK>b\\x07', 'Suite 102: capture escaping')

    -- 3. Ring buffer
    local ring = plugin.newRing(3)
    for i = 1, 5 do plugin.ringPush(ring, { n = i }) end
    assert_true(ring.first == 3 and ring.last == 5 and plugin.ringCount(ring) == 3 and ring.items[2] == nil and ring.items[5].id == 5, 'Suite 102: ring evicts oldest and stamps ids')

    -- 4. Config sanitize
    local c = plugin.sanitizeConfig(nil)
    assert_true(#c.windows == 1 and #c.windows[1].tabs == 7 and c.windows[1].tabs[1].channels == nil, 'Suite 102: default layout: one window, seven tabs, All tab unfiltered')
    assert_eq(c.windows[1].tabs[5].send, 'tell', 'Suite 102: Tells tab sends tells')
    assert_true(c.windows[1].tabs[6].notifyOnly == true and c.windows[1].tabs[6].name == 'Notifications' and c.windows[1].tabs[6].channels == nil and c.windows[1].tabs[7].id == 'triune', 'Suite 102: default Notifications tab sits before Triune: every channel, flagged lines only')
    local mig = plugin.sanitizeConfig({ version = 2, windows = { { id = 'main', activeTab = 2, tabs = { { id = 'all' }, { id = 'triune' } } }, { id = 'w2', tabs = { { id = 'all' } } } } })
    assert_true(#mig.windows[1].tabs == 3 and mig.windows[1].tabs[2].notifyOnly == true and mig.windows[1].tabs[3].id == 'triune' and mig.windows[1].activeTab == 3 and #mig.windows[2].tabs == 1, 'Suite 102: a v2 config gains a Notifications tab in the main window only, before Triune, active tab kept')
    local mig3 = plugin.sanitizeConfig({ version = 3, windows = { { id = 'main', tabs = { { id = 'all' } } } } })
    assert_true(#mig3.windows[1].tabs == 1, 'Suite 102: a v3 config that dropped the tab is left alone')
    local mig2b = plugin.sanitizeConfig({ version = 2, windows = { { id = 'main', tabs = { { id = 'mine', notifyOnly = true } } } } })
    assert_true(#mig2b.windows[1].tabs == 1 and mig2b.windows[1].tabs[1].notifyOnly == true, 'Suite 102: a user-made Notifications tab is not duplicated by the migration')
    local mcfg = plugin.sanitizeConfig({ mention = { on = false, color = 'zz', beep = 1 } }).mention
    assert_true(mcfg.on == false and mcfg.color == 'FFA040' and mcfg.beep == false, 'Suite 102: mention settings sanitized (bad colour falls back)')
    assert_true(plugin.sanitizeConfig({}).mention.on == true, 'Suite 102: mention highlighting on by default')
    assert_true(c.windows[1].tabs[5].channels.tell_in and c.windows[1].tabs[5].channels.tell_out and c.windows[1].tabs[5].channels.petchat == nil, 'Suite 102: Tells preset is player tells only')
    local old = plugin.sanitizeConfig({ version = 1, windows = { { id = 'w', tabs = { { id = 'tells', channels = { tell_in = true, tell_out = true, petchat = true } }, { id = 'mine', channels = { tell_in = true, petchat = true, say = true } } } } } })
    assert_true(old.windows[1].tabs[1].channels.petchat == nil and old.windows[1].tabs[1].channels.tell_in, 'Suite 102: v1 Tells preset migrates pet chat out')
    assert_true(old.windows[1].tabs[2].channels.petchat == true, 'Suite 102: migration leaves custom tabs alone')
    assert_true(plugin.sanitizeConfig({ version = 2, windows = { { id = 'w', tabs = { { id = 'tells', channels = { tell_in = true, tell_out = true, petchat = true } } } } } }).windows[1].tabs[1].channels.petchat == true, 'Suite 102: v2 configs are not migrated')
    local mig4 = plugin.sanitizeConfig({ version = 3, windows = { { id = 'w', tabs = { { id = 'loot', channels = { loot = true, exp = true } }, { id = 'soc', channels = { say = true } } } } } })
    assert_true(mig4.windows[1].tabs[1].channels.nms == true, 'Suite 102: v3 tabs that showed loot gain the NMS channel')
    assert_true(mig4.windows[1].tabs[2].channels.nms == nil, 'Suite 102: ...and tabs without loot do not')
    assert_true(plugin.sanitizeConfig({ version = 4, windows = { { id = 'w', tabs = { { id = 'loot', channels = { loot = true } } } } } }).windows[1].tabs[1].channels.nms == nil, 'Suite 102: a v4 tab that dropped the NMS channel is left alone')
    assert_true(c.windows[1].tabs[4].channels.nms == true and c.windows[1].tabs[4].channels.loot == true, 'Suite 102: the default Loot & XP tab shows NMS lines')
    c = plugin.sanitizeConfig({ maxLines = 'x', opacity = 7, appendMode = 'weird', colors = { say = 'ZZZ', group = 'FF00FF', bogus = 'FFFFFF' },
        windows = { { id = 'a', tabs = { { channels = { bogus = true, say = true }, send = 'nope', exclude = { 'WTS', 7, '' } } } }, { id = 'a', tabs = {} } } })
    assert_eq(c.maxLines, 2000, 'Suite 102: bad maxLines falls back')
    assert_eq(c.opacity, 1.0, 'Suite 102: opacity clamped')
    assert_eq(c.appendMode, 'text', 'Suite 102: append mode falls back')
    assert_true(c.colors.say == nil and c.colors.group == 'FF00FF' and c.colors.bogus == nil, 'Suite 102: color overrides validated')
    local hc = plugin.sanitizeConfig({ highlights = { { text = 'x', color = 'zz' }, { text = '' }, 'junk', { text = 'y', color = '00FF00', beep = true, flash = false } }, muted = { Bob = true, Eve = false, [1] = true } })
    assert_true(#hc.highlights == 2 and hc.highlights[1].color == 'FFD700' and hc.highlights[1].flash == true and hc.highlights[2].beep == true and hc.highlights[2].flash == false, 'Suite 102: highlights sanitized with defaults')
    assert_true(hc.muted.bob == true and hc.muted.eve == nil and next(hc.muted, 'bob') == nil, 'Suite 102: mute list lowercased and filtered')
    local t1 = c.windows[1].tabs[1]
    assert_true(t1.channels.bogus == nil and t1.channels.say == true and t1.send == 'say', 'Suite 102: tab channels / send sanitized')
    assert_eq(#t1.exclude, 1, 'Suite 102: keyword lists keep only non-empty strings')
    assert_eq(t1.exclude[1], 'wts', 'Suite 102: keywords lowercased')
    assert_true(c.windows[2].id ~= c.windows[1].id and #c.windows[2].tabs == 1, 'Suite 102: duplicate window ids disambiguated, empty tab list seeded')
    local ser = plugin.serialize({ a = 1, b = 'x', c = { true, false }, ['d e'] = { z = 2 } })
    local back = assert(loadstring('return ' .. ser))()
    assert_true(back.a == 1 and back.b == 'x' and back.c[2] == false and back['d e'].z == 2, 'Suite 102: serializer roundtrips nested tables')

    -- 4b. Inline renderer: tokens and word-wrapped layout (fake measurer: 7 px per char)
    local ie = { raw = 'Your [' .. IT .. '] absorbs energy. (04.82%)', hms = '10:00:00' }
    local toks = plugin.tokenize(ie)
    assert_true(#ie.links == 1 and ie.links[1].name == 'Earthen Bracer of Fortitude (Enchanted)', 'Suite 102: tokenize collects the item link')
    assert_true(toks[2].t == '[' and toks[3].t == 'Earthen' and toks[3].link == 1 and toks[3].sp == false, 'Suite 102: bracket hugs the link words')
    assert_true(toks[7].t == '(Enchanted)' and toks[7].link == 1 and toks[8].t == ']' and toks[8].sp == false, 'Suite 102: closing bracket hugs the last link word')
    local measure = function(t) return #t * 7 end
    local runs = {}
    local nl = plugin.layoutEntry(ie, 10000, 7, true, measure, 13, function(line, text, link, ts, gap) runs[#runs + 1] = { line = line, text = text, link = link, ts = ts, gap = gap } end)
    assert_eq(nl, 1, 'Suite 102: wide layout is one line')
    assert_true(runs[1].text == '[10:00:00]' and runs[1].ts == true, 'Suite 102: timestamp run first')
    assert_true(runs[2].text == 'Your [' and runs[2].gap == 7, 'Suite 102: plain run after the timestamp with a space gap')
    assert_true(runs[3].text == 'Earthen Bracer of Fortitude (Enchanted)' and runs[3].link == 1 and runs[3].gap == 0, 'Suite 102: link words coalesce into one run hugging the bracket')
    assert_true(runs[4].text == '] absorbs energy. (04.82%)' and runs[4].gap == 0, 'Suite 102: trailing plain run')
    runs = {}
    nl = plugin.layoutEntry(ie, 120, 7, false, measure, 13, function(line, text, link, ts, gap) runs[#runs + 1] = { line = line, text = text } end)
    assert_true(nl > 1, 'Suite 102: narrow layout wraps')
    local tooWide = nil
    for _, r in ipairs(runs) do if #r.text * 7 > 120 and r.text:find(' ') then tooWide = r.text end end
    assert_true(tooWide == nil, 'Suite 102: no multi-word run exceeds the wrap width: ' .. tostring(tooWide))
    assert_true(plugin.layoutEntry(ie, 120, 20, false, function(t) return #t * 20 end, 20, nil) > nl, 'Suite 102: a larger font re-measures and wraps more')
    local pe = { raw = P('Bob') .. " tells you, 'hi'", hms = '10:00:00' }
    local ptoks = plugin.tokenize(pe)
    assert_true(ptoks[1].t == 'Bob' and ptoks[1].link == nil and #pe.links == 0, 'Suite 102: player links tokenize as plain names')
    assert_eq(plugin.sanitizeConfig({ renderer = 'weird' }).renderer, 'inline', 'Suite 102: renderer defaults to inline')
    local fw = plugin.sanitizeConfig({ windows = { { id = 'a', fontScale = 9, font = 0 }, { id = 'b', fontScale = 'x', font = 2.7 } } }).windows
    assert_true(fw[1].fontScale == 2.5 and fw[1].font == nil and fw[2].fontScale == 1.0 and fw[2].font == nil, 'Suite 102: per-window font scale clamped, saved font selections dropped')
    assert_eq(plugin.sanitizeConfig({ renderer = 'console' }).renderer, 'console', 'Suite 102: classic renderer selectable')

    -- 5. Tab filters
    local tab = { channels = { say = true }, include = {}, exclude = { 'wts' } }
    assert_eq(plugin.tabAccepts(tab, { channel = 'say', text = 'hello' }), true, 'Suite 102: channel match accepted')
    assert_eq(plugin.tabAccepts(tab, { channel = 'ooc', text = 'hello' }), false, 'Suite 102: other channel rejected')
    assert_eq(plugin.tabAccepts(tab, { channel = 'say', text = 'WTS sword' }), false, 'Suite 102: exclude keyword (case-insensitive)')
    tab.include = { 'buff' }
    assert_eq(plugin.tabAccepts(tab, { channel = 'say', text = 'hello' }), false, 'Suite 102: include keyword required when set')
    assert_eq(plugin.tabAccepts(tab, { channel = 'say', text = 'need a Buff' }), true, 'Suite 102: include keyword matched')
    assert_eq(plugin.tabAccepts({ channels = nil, include = {}, exclude = {} }, { channel = 'unknown', text = '' }), true, 'Suite 102: unfiltered tab takes everything')

    -- 6. Lifecycle under a mock core
    local S = { events = {}, binds = {}, cmds = {}, saves = 0 }
    local cfgDir = os.getenv('TMPDIR') or '/tmp'
    -- The clock is frozen unless a test advances S.nowMs: the drain budget
    -- (12 ms per tick) must not depend on how fast the test machine is.
    S.nowMs = 0
    local mockMq = {
        configDir = cfgDir,
        gettime = function() return S.nowMs end,
        event = function(name, pat, fn, opts) S.events[name] = { pat = pat, fn = fn, opts = opts } end,
        unevent = function(name) S.events[name] = nil end,
        -- doevents(name): deliver the lines MQ has queued for that event only
        doevents = function(...)
            S.doeventsArgs = { ... }
            local ev = S.events.TACChatAll
            if not ev then return end
            local lines = S.pendingLines or {}
            S.pendingLines = {}
            for _, l in ipairs(lines) do ev.fn(l) end
        end,
        bind = function(cmd, fn) S.binds[cmd] = fn end,
        unbind = function(cmd) S.binds[cmd] = nil end,
        cmd = function(s) S.cmds[#S.cmds + 1] = s end,
        cmdf = function(f, ...) S.cmds[#S.cmds + 1] = string.format(f, ...) end,
        TLO = { MacroQuest = { Path = function() return function() return cfgDir end end },
                Me = { CleanName = function() return 'Genro' end },
                Pet = { CleanName = function() return 'Spinevenom' end } },
    }
    local ctrl = {}
    local noop = function() end
    local mockImGui = setmetatable({
        Button = function() return false end, SmallButton = function() return false end,
        Checkbox = function(_, v) return v end, SliderInt = function(_, v) return v, false end, SliderFloat = function(_, v) return v, false end,
        CollapsingHeader = function() return false end, BeginTable = function() return false end,
    }, { __index = function() return noop end })
    local core = setmetatable({ mq = mockMq, ImGui = mockImGui, saveLoadout = function() S.saves = S.saves + 1 end, accent = noop, px = function(v) return v end,
        pushTheme = noop, popTheme = noop, preBeginWindow = noop, postBeginWindow = noop },
        { __index = function(_, k) if k == 'ctrl' then return ctrl end end })
    os.remove(cfgDir .. '/triune_chat_Genro.lua')
    local histPath = cfgDir .. '/triune_chat_history_Genro.txt'
    os.remove(histPath)
    print = quiet
    plugin.onInit(core)
    plugin.onInit(core) -- the manager may re-init without onDestroy
    print = origPrint
    assert_true(S.events.TACChatAll ~= nil and S.events.TACChatAll.pat == '#*#' and S.events.TACChatAll.opts.keepLinks == true, 'Suite 102: catch-all event with keepLinks')
    assert_true(S.binds['/tacchat'] ~= nil, 'Suite 102: /tacchat bound (not /chat, which EQ owns)')
    assert_eq(ctrl.show_chat, false, 'Suite 102: show_chat seeded off')
    local cfg = plugin.cfg
    for _, f in ipairs(fixture) do S.events.TACChatAll.fn(f[1]) end
    plugin.onTick()
    local rt = plugin.rt
    assert_eq(rt.stats.total, #fixture, 'Suite 102: every queued line ingested on tick')
    assert_eq(rt.stats.unknown, 1, 'Suite 102: unclassified counter')
    assert_eq(rt.unknownRecent[1], 'Some completely new server message nobody has seen.', 'Suite 102: unclassified lines kept for review')
    local win = cfg.windows[1]
    local tells = rt.tabs[win.id .. '/' .. win.tabs[5].id]
    assert_eq(tells and tells.unread, 3, 'Suite 102: hidden Tells tab counts unread player tells only (pet chat is not a tell; the offline notice is one)')
    assert_true(tells.rebuild == true and tells.pendingLast == 0 and tells.last == 3, 'Suite 102: an undrawn tab still fills its own buffer (the first draw merges it with the ring)')
    local sample = rt.ring.items[rt.ring.first]
    assert_true(plugin.renderLine(sample, true):find('^%[%d%d:%d%d:%d%d%] \a#%x%x%x%x%x%x') ~= nil, 'Suite 102: rendered line = timestamp + channel color')

    -- Tell / notification history: written as lines arrive, flushed on the tick
    local H = plugin.history
    assert_eq(plugin.sanitizeConfig({}).history.on, true, 'Suite 102: history defaults on')
    assert_eq(plugin.sanitizeConfig({}).history.lines, 1000, 'Suite 102: history keeps 1000 lines by default')
    assert_eq(plugin.sanitizeConfig({ history = { on = false, lines = 99999 } }).history.lines, 5000, 'Suite 102: history lines clamped')
    assert_eq(plugin.sanitizeConfig({ history = { on = false } }).history.on, false, 'Suite 102: history can be turned off')
    assert_eq(H.path(), histPath, 'Suite 102: history file lives next to the config')
    local kept = 0
    for i = rt.ring.first, rt.ring.last do
        local e = rt.ring.items[i]
        if not e.muted and (e.channel == 'tell_in' or e.channel == 'tell_out' or e.notify) then kept = kept + 1 end
    end
    assert_true(kept >= 2, 'Suite 102: fixture carries tells to keep')
    local hf = io.open(histPath, 'r')
    local histLines = {}
    if hf then for l in hf:lines() do histLines[#histLines + 1] = l end; hf:close() end
    assert_eq(#histLines, kept, 'Suite 102: one history line per tell / notification, none for other channels')
    assert_true(rt.hist and rt.hist.last - rt.hist.first + 1 == kept and rt.hist.fileLines == kept, 'Suite 102: in-memory history copy tracks the file')
    -- encode / decode round trip keeps links, colours, tabs and backslashes
    local tricky = { t = 1700000000, channel = 'tell_in', sender = 'Bob', outgoing = false, notify = true, mention = true, hl = 'FFA040',
                     text = "Bob tells you, 'see [Earthen Bracer of Fortitude (Enchanted)]\t\\ok'",
                     raw = P('Bob') .. " tells you, '" .. ESC .. "00FF00see " .. IT .. "\t\\ok'" }
    local enc = H.encode(tricky)
    assert_true(enc:find('\n') == nil and enc:find(L, 1, true) == nil and enc:find(ESC, 1, true) == nil, 'Suite 102: encoded history line is one printable line')
    local dec = H.decode(enc)
    assert_true(dec ~= nil and dec.raw == tricky.raw and dec.text == tricky.text and dec.sender == 'Bob' and dec.channel == 'tell_in'
        and dec.notify == true and dec.mention == true and dec.hl == 'FFA040' and dec.outgoing == false and dec.t == 1700000000 and dec.restored == true,
        'Suite 102: history round trip keeps every field')
    assert_eq(dec.player, 'Bob', 'Suite 102: restored tell sender is clickable')
    assert_true(dec.hms:find('^%d%d/%d%d %d%d:%d%d$') ~= nil, 'Suite 102: a restored line from another day carries its date')
    local todayEnc = H.encode({ t = os.time(), channel = 'tell_out', sender = 'Bob', outgoing = true, text = "You told Bob, 'hi'", raw = "You told Bob, 'hi'" })
    assert_true(H.decode(todayEnc).hms:find('^%d%d:%d%d:%d%d$') ~= nil and H.decode(todayEnc).player == 'Bob', 'Suite 102: a restored line from today shows the time; outgoing tell names its recipient')
    assert_true(H.decode('garbage') == nil and H.decode('1\tnotachannel\t\t0\t\tx\tx') == nil, 'Suite 102: unreadable history lines are skipped')
    assert_true(plugin.renderLine(sample, false):find('^\a#') ~= nil, 'Suite 102: timestamps optional')
    local linkEntry
    for i = rt.ring.first, rt.ring.last do
        local e = rt.ring.items[i]
        if e and e.raw:find(L, 1, true) and e.channel == 'item' then linkEntry = e break end
    end
    assert_true(linkEntry ~= nil and plugin.renderLine(linkEntry, false):find(L, 1, true) == nil, 'Suite 102: rendered lines carry no raw link payload')
    assert_true(plugin.renderLine(linkEntry, false):find('[Earthen Bracer of Fortitude (Enchanted)]', 1, true) ~= nil, 'Suite 102: rendered lines show the item name')
    assert_true(#rt.recentLinks >= 3 and rt.recentLinks[#rt.recentLinks].name == 'Earthen Bracer of Fortitude (Enchanted)', 'Suite 102: item links collected for the Links menu')
    assert_eq(#plugin.extractItemLinks('Luck! [' .. IT2 .. '] became [' .. IT .. '] said ' .. P('Bob')), 2, 'Suite 102: extractItemLinks skips player links')
    local rl = rt.recentLinks[#rt.recentLinks]
    mockMq.ExecuteTextLink = function() error('must never be called: native exception on this server') end
    mockMq.ExtractLinks = function() error('must never be called') end
    rt.echo = nil
    mockMq.TLO.FindItem = function() return setmetatable({}, { __call = function() return false end }) end
    assert_eq(plugin.openItemLink(rl), true, 'Suite 102: UI click queues the link')
    assert_true(rt.pendingLink ~= nil, 'Suite 102: nothing executes on the render thread')
    plugin.onTick()
    assert_true(rt.pendingLink == nil and rt.echo:find('not in your inventory or bank', 1, true) ~= nil, 'Suite 102: an item you do not carry is reported, never sent to ExecuteTextLink')
    local inspected = false
    mockMq.TLO.FindItem = function(name) return setmetatable({ Inspect = function() inspected = (name == '=Earthen Bracer of Fortitude (Enchanted)') end }, { __call = function() return true end }) end
    assert_eq(plugin.executeLink(rl), true, 'Suite 102: Inspect() opens a carried item')
    assert_true(inspected and rt.echo:find('^Opened Earthen') ~= nil, 'Suite 102: Inspect path reported')
    mockMq.TLO.FindItem = nil
    mockMq.ExtractLinks, mockMq.ExecuteTextLink = nil, nil
    cfg.appendMode = 'unformatted'
    assert_eq(plugin.renderLine(sample, false), sample.text, 'Suite 102: plain mode renders resolved text')
    cfg.appendMode = 'text'
    assert_eq(plugin.channelColor('tell_in'), 'FF66FF', 'Suite 102: default channel color')
    cfg.colors.tell_in = '123456'
    assert_eq(plugin.channelColor('tell_in'), '123456', 'Suite 102: color override wins')

    plugin.sendText(win.tabs[2], 'hello')
    assert_eq(S.cmds[#S.cmds], '/g hello', 'Suite 102: Social tab sends to /g')
    plugin.sendText(win.tabs[2], '/ac status')
    assert_eq(S.cmds[#S.cmds], '/ac status', 'Suite 102: slash commands pass through')
    plugin.sendText(win.tabs[5], 'hi')
    assert_true(S.cmds[#S.cmds] == '/ac status' and rt.echo ~= nil, 'Suite 102: tell without a target is refused with a hint')
    win.tabs[5].tellTarget = 'Bob'
    plugin.sendText(win.tabs[5], 'hi bob')
    assert_eq(S.cmds[#S.cmds], '/tell Bob hi bob', 'Suite 102: tell routed to the tab target')
    assert_eq(#cfg.inputHistory, 0, 'Suite 102: sendText itself records no history (the input line does, with its links)')

    print = quiet
    S.binds['/tacchat']('toggle')
    assert_true(ctrl.show_chat == true and S.saves >= 1, 'Suite 102: /tacchat toggle opens and saves the loadout')
    S.binds['/tacchat']('tab', 'Tells')
    assert_eq(win.activeTab, 5, 'Suite 102: /tacchat tab <name> activates the tab')
    S.binds['/tacchat']('capture', 'on')
    assert_true(cfg.capture == true and rt.captureFile ~= nil, 'Suite 102: capture on opens the file')
    S.events.TACChatAll.fn('You gain party experience!!')
    plugin.onTick()
    S.binds['/tacchat']('capture', 'off')
    print = origPrint
    local capf = io.open(rt.capturePath, 'r')
    local capText = capf and capf:read('*a') or ''
    if capf then capf:close() end
    assert_true(capText:find('exp          | You gain party experience!!', 1, true) ~= nil, 'Suite 102: capture writes channel | line')
    os.remove(rt.capturePath)

    cfg.timestamps = false
    rt.dirty = true
    rt.lastSave = 0
    plugin.onTick()
    assert_eq(rt.dirty, false, 'Suite 102: dirty config autosaves on tick')

    -- 7. Highlights, mutes, per-tab logging
    cfg.highlights = { { text = 'buff', color = 'FFD700', beep = true, flash = true } }
    cfg.muted = { playertwo = true }
    local beeps = 0
    local origCmd = mockMq.cmd
    mockMq.cmd = function(c) if c == '/beep' then beeps = beeps + 1 else S.cmds[#S.cmds + 1] = c end end
    rt.lastBeepAt = 0
    S.events.TACChatAll.fn(P('Playerone') .. " tells you, 'need a BUFF please'")
    S.events.TACChatAll.fn(P('Playerone') .. " tells you, 'buff again'")
    S.events.TACChatAll.fn(P('Playertwo') .. " says out of character, 'spam'")
    plugin.onTick()
    local hlEntry, mutedEntry = rt.ring.items[rt.ring.last - 2], rt.ring.items[rt.ring.last]
    assert_true(hlEntry.hl == 'FFD700' and hlEntry.flash == true, 'Suite 102: highlight colours and flags the line (case-insensitive)')
    assert_eq(beeps, 1, 'Suite 102: beep throttled to once a second')
    assert_true(mutedEntry.muted == true and plugin.tabAccepts(win.tabs[1], mutedEntry) == false, 'Suite 102: muted sender hidden in every tab')
    local tellsSt = rt.tabs[win.id .. '/' .. win.tabs[5].id]
    local socialSt = rt.tabs[win.id .. '/' .. win.tabs[2].id]
    assert_true(socialSt.flashAt > 0 and tellsSt.flashAt == 0, 'Suite 102: hidden tab flashes on a highlighted line, the active one does not')
    mockMq.cmd = origCmd
    win.tabs[5].logToFile = true
    S.events.TACChatAll.fn(P('Playerone') .. " tells you, 'log me'")
    plugin.onTick()
    assert_true(tellsSt.logFile ~= nil, 'Suite 102: tab log file opened on demand')
    local logPath = string.format('%s/tac_chat_Genro_Tells_%s.txt', cfgDir, os.date('%Y%m%d'))
    local lf = io.open(logPath, 'r')
    local logText = lf and lf:read('*a') or ''
    if lf then lf:close() end
    assert_true(logText:find("Playerone tells you, 'log me'", 1, true) ~= nil, 'Suite 102: tab log line written and flushed')
    win.tabs[5].logToFile = false

    -- 8. Tab / window management
    local w2 = plugin.newWindow('Second')
    assert_true(#cfg.windows == 2 and w2.title == 'Second' and #w2.tabs == 1 and w2.tabs[1].channels == nil, 'Suite 102: new window seeded with an All tab')
    local t = plugin.addTab(win, 'Extra', 'loot')
    assert_true(#win.tabs == 8 and win.activeTab == 8 and t.channels.loot == true and t.id ~= win.tabs[1].id, 'Suite 102: addTab appends, activates, unique id')
    rt.tabOrderGen[win.id] = nil
    rt.selectReq = nil
    assert_true(plugin.moveTab(win, 8, -1) and win.tabs[7] == t and win.activeTab == 7, 'Suite 102: moveTab swaps and follows')
    assert_true(rt.tabOrderGen[win.id] == 1 and rt.selectReq and rt.selectReq[win.id] == t.id, 'Suite 102: a move renews the tab bar id (ImGui keeps its own order otherwise) and selects the moved tab explicitly')
    assert_eq(plugin.moveTab(win, 1, -1), false, 'Suite 102: moveTab refuses to leave the list')
    assert_true(plugin.moveTabToWindow(win, 7, w2) and #win.tabs == 7 and w2.tabs[2] == t and w2.activeTab == 2, 'Suite 102: tab moved to another window')

    assert_eq(plugin.moveTabToWindow(w2, 1, w2), false, 'Suite 102: no move onto itself')
    assert_true(plugin.removeTab(w2, 2) and #w2.tabs == 1, 'Suite 102: removeTab')
    assert_eq(plugin.removeTab(w2, 1), false, 'Suite 102: last tab cannot be removed')
    assert_true(plugin.findWindow('second') == w2 and plugin.findWindow('nope') == nil, 'Suite 102: findWindow by title')
    -- panes
    assert_eq(plugin.moveTabToPane(win, 1, 2, 'h'), true, 'Suite 102: split moves the All tab into a new pane')
    assert_true(win.panes == 2 and win.tabs[1].pane == 2 and win.splitDir == 'h' and math.abs(win.paneSizes[1] + win.paneSizes[2] - 1) < 0.001, 'Suite 102: two panes, sizes normalised')
    assert_true(win.activeByPane[2] == win.tabs[1].id and plugin.isTabActive(win, 1), 'Suite 102: the moved tab is active in its pane')
    assert_eq(plugin.moveTabToPane(win, 1, 1), false, 'Suite 102: the only tab of a pane cannot leave it')
    assert_eq(plugin.moveTabToPane(win, 2, 3, 'v'), true, 'Suite 102: a third pane, stacked')
    assert_true(win.panes == 3 and win.splitDir == 'v' and win.tabs[2].pane == 3, 'Suite 102: third pane created')
    assert_true(plugin.moveTab(win, 3, 1) and win.tabs[4].pane == 1, 'Suite 102: moveTab swaps within the same pane only')
    local moved = win.tabs[4]
    plugin.setActiveTab(win, 4)
    assert_true(plugin.isTabActive(win, 4) and win.activeTab == 4, 'Suite 102: setActiveTab keeps pane-1 activeTab in sync')
    plugin.moveTabToPane(win, 3, 3)
    assert_true(win.tabs[3].pane == 3, 'Suite 102: move to an existing pane')
    plugin.unsplit(win)
    assert_true(win.panes == 1 and win.tabs[1].pane == 1 and win.tabs[2].pane == 1, 'Suite 102: unsplit collapses to one pane')
    local pc = plugin.sanitizeConfig({ windows = { { id = 'p', panes = 4, splitDir = 'x', paneSizes = { 3, 0, 'z' }, activeByPane = { [2] = 'b' },
        tabs = { { id = 'a', pane = 1 }, { id = 'b', pane = 3 }, { id = 'c', pane = 9 }, { id = 'd', pane = 3 } } } } }).windows[1]
    assert_true(pc.panes == 3 and pc.splitDir == 'h', 'Suite 102: sanitize collapses the empty pane (2 of 4) and defaults the direction')
    assert_true(pc.tabs[1].pane == 1 and pc.tabs[2].pane == 2 and pc.tabs[3].pane == 3 and pc.tabs[4].pane == 2, 'Suite 102: out-of-range pane clamps to the last pane, gaps renumber')
    assert_true(math.abs(pc.paneSizes[1] + pc.paneSizes[2] + pc.paneSizes[3] - 1) < 0.001 and pc.paneSizes[1] > pc.paneSizes[2], 'Suite 102: pane sizes normalised, bad values replaced')
    assert_true(pc.activeByPane[1] == 'a' and pc.activeByPane[2] == 'b', 'Suite 102: active tab per pane kept or seeded')
    plugin.closeWindow(w2)
    assert_true(#cfg.windows == 1 and cfg.windows[1] == win, 'Suite 102: closeWindow removes an extra window')
    plugin.closeWindow(win)
    assert_true(#cfg.windows == 1 and win.open == false and ctrl.show_chat == false, 'Suite 102: closing the last window hides the plugin instead of deleting it')
    win.open = true
    print = quiet
    S.binds['/tacchat']('window', 'new', 'Cmd')
    assert_true(#cfg.windows == 2 and cfg.windows[2].title == 'Cmd' and ctrl.show_chat == true, 'Suite 102: /tacchat window new')
    S.binds['/tacchat']('window', 'close', 'Cmd')
    assert_eq(#cfg.windows, 1, 'Suite 102: /tacchat window close')
    S.binds['/tacchat']('mute', 'Spammer')
    assert_eq(cfg.muted.spammer, true, 'Suite 102: /tacchat mute lowercases')
    S.binds['/tacchat']('unmute', 'SPAMMER')
    assert_eq(cfg.muted.spammer, nil, 'Suite 102: /tacchat unmute')
    S.binds['/tacchat']('settings')
    assert_true(rt.editor ~= nil and rt.editor.winId == win.id, 'Suite 102: /tacchat settings opens the editor on the active tab')
    print = origPrint

    -- 9. Full draw pass under a permissive ImGui mock (window, toolbar menu, inline log, editor)
    local drawMock = setmetatable({
        Begin = function() return true, true end,
        BeginChild = function() return true end,
        BeginTabBar = function() return true end,
        BeginTabItem = function() return true end,
        BeginPopup = function() return true end,
        BeginMenu = function() return true end,
        BeginCombo = function() return true end,
        BeginTable = function() return true end,
        Button = function() return false end, SmallButton = function() return false end,
        MenuItem = function() return false end, Selectable = function() return false end,
        Checkbox = function(_, v) return v end,
        InputText = function(_, v) return v, false end, InputTextWithHint = function(_, _, v) return v, false end,
        SliderInt = function(_, v) return v end, SliderFloat = function(_, v) return v end,
        CalcTextSize = function(t) return #t * 7 end,
        GetContentRegionAvail = function() return 400, 300 end,
        GetScrollY = function() return 0 end, GetScrollMaxY = function() return 0 end,
        GetTextLineHeightWithSpacing = function() return 16 end, GetFontSize = function() return 13 end,
        IsItemHovered = function() return false end, IsItemClicked = function() return false end, IsMouseClicked = function() return false end,
        CollapsingHeader = function() return false end,
        ColorEdit3 = function(_, col) return col, false end,
    }, { __index = function() return noop end })
    core.ImGui = drawMock
    ctrl.show_chat = true
    cfg.renderer = 'inline'
    cfg.timestamps = true
    win.fontScale = 1.3
    rt.tabMenuTarget = { win = win, ti = 1 }
    plugin.echo('status line')
    for _, st in pairs(rt.tabs) do st.rebuild = true end
    local okDraw, errDraw = pcall(plugin.onDrawUI)
    assert_true(okDraw, 'Suite 102: inline renderer + tab menu + editor draw without error: ' .. tostring(errDraw))

    -- Ghost windows: the chrome alpha follows the hover state on the mocked clock
    local G = plugin.ghost
    local gw = plugin.sanitizeConfig({ windows = { { id = 'a', ghost = true }, { id = 'b', ghost = 'yes' } } }).windows
    assert_true(gw[1].ghost == true and gw[2].ghost == false, 'Suite 102: ghost is a per-window boolean')
    local pushes, pops = {}, 0
    _G.ImGuiHoveredFlags = _G.ImGuiHoveredFlags or { RootAndChildWindows = 3, AllowWhenBlockedByActiveItem = 128, AllowWhenBlockedByPopup = 32 }
    local hadCol = _G.ImGuiCol
    _G.ImGuiCol = { Text = 0, TextDisabled = 1, TextLink = 2, Border = 5, TitleBg = 10, TitleBgActive = 11, Tab = 33, TabActive = 35, FrameBg = 7, ScrollbarGrab = 15, Button = 21 }
    drawMock.GetStyleColorVec4 = function(idx) return { x = 0.5, y = 0.6, z = 0.7, w = 0.9 } end
    drawMock.PushStyleColor = function(idx, r, g, b, a) pushes[#pushes + 1] = { idx = idx, a = a } end
    drawMock.PopStyleColor = function(n) pops = pops + (n or 1) end
    local bgAlpha
    drawMock.SetNextWindowBgAlpha = function(a) bgAlpha = a end
    local hovered = false
    drawMock.IsWindowHovered = function() return hovered end
    win.ghost = true
    win.opacity = 0.8
    rt.tabMenuTarget = nil   -- an open menu of the window would hold it
    local beginPopup = drawMock.BeginPopup
    drawMock.BeginPopup = function() return false end
    drawMock.IsPopupOpen = function() return false end
    S.nowMs = 1000
    okDraw, errDraw = pcall(plugin.onDrawUI)
    assert_true(okDraw, 'Suite 102: ghost window draws: ' .. tostring(errDraw))
    local g = rt.ghost[win.id]
    assert_true(g ~= nil and g.a == 1 and g.held == false, 'Suite 102: ghost starts fully drawn, not held')
    assert_true(math.abs(bgAlpha - 0.8) < 0.001, 'Suite 102: background alpha = window opacity while drawn')
    S.nowMs = 1000 + G.LINGER_MS + 200   -- linger over, 200 ms into the fade-out
    pushes = {}
    okDraw = pcall(plugin.onDrawUI)
    assert_true(okDraw and g.a < 1 and g.a > 0, 'Suite 102: chrome fades once the mouse has been away: ' .. tostring(g.a))
    assert_true(math.abs(bgAlpha - 0.8 * g.a) < 0.001, 'Suite 102: background alpha follows the fade')
    S.nowMs = S.nowMs + G.OUT_MS
    okDraw = pcall(plugin.onDrawUI)
    assert_true(okDraw and g.a == 0, 'Suite 102: fully faded: only the text is left')
    pushes = {}
    pops = 0
    okDraw = pcall(plugin.onDrawUI)
    local fadedTitle, fadedTab, textBack, chromeBack = false, false, false, false
    for _, v in ipairs(pushes) do
        if v.idx == 10 and v.a == 0 then fadedTitle = true end
        if v.idx == 33 and v.a == 0 then fadedTab = true end
        if v.idx == 0 and math.abs(v.a - 0.9) < 0.001 then textBack = true end
        if v.idx == 10 and math.abs(v.a - 0.9) < 0.001 then chromeBack = true end
    end
    assert_true(okDraw and fadedTitle and fadedTab and textBack, 'Suite 102: a faded window pushes its chrome colours at alpha 0 and the text colour back for the log')
    assert_true(chromeBack == false, 'Suite 102: no menu open: the chrome colours are not pushed back')
    assert_eq(pops, #pushes, 'Suite 102: every ghost colour push is popped')
    local styleVarAlpha = false
    local origPSV = drawMock.PushStyleVar
    drawMock.PushStyleVar = function(id, v) if id == 0 and v == 0 then styleVarAlpha = true end end
    okDraw = pcall(plugin.onDrawUI)
    drawMock.PushStyleVar = origPSV
    assert_true(okDraw and styleVarAlpha == false, 'Suite 102: the global style alpha is never used (it hid the text in the field)')
    hovered = true
    S.nowMs = S.nowMs + 50
    okDraw = pcall(plugin.onDrawUI)   -- the hover is seen this frame, applied to the alpha next frame
    S.nowMs = S.nowMs + 50
    okDraw = pcall(plugin.onDrawUI)
    assert_true(okDraw and g.held == true and g.a > 0, 'Suite 102: hovering fades the chrome back in: ' .. tostring(g.a))
    S.nowMs = S.nowMs + G.IN_MS
    okDraw = pcall(plugin.onDrawUI)
    assert_true(okDraw and g.a == 1, 'Suite 102: fully back under the mouse')
    hovered = false
    rt.activeInputWin = nil
    -- typing in the window holds it even with the mouse away
    local activeInput = true
    drawMock.IsItemActive = function() return activeInput end
    S.nowMs = S.nowMs + G.LINGER_MS + G.OUT_MS + 100
    okDraw = pcall(plugin.onDrawUI)
    S.nowMs = S.nowMs + 50
    okDraw = pcall(plugin.onDrawUI)
    assert_true(okDraw and g.held == true and g.a == 1, 'Suite 102: an active input holds a ghost window: ' .. tostring(g.a))
    activeInput = false
    drawMock.IsItemActive = nil
    win.ghost = false
    okDraw = pcall(plugin.onDrawUI)
    assert_true(okDraw and math.abs(bgAlpha - 0.8) < 0.001, 'Suite 102: ghost off: drawn in full again')
    -- an open menu of the window holds it too
    win.ghost = true
    drawMock.BeginPopup = beginPopup
    drawMock.IsPopupOpen = function() return true end
    rt.tabMenuTarget = { win = win, ti = 1 }
    S.nowMs = S.nowMs + G.LINGER_MS + G.OUT_MS + 100
    okDraw = pcall(plugin.onDrawUI)
    S.nowMs = S.nowMs + 50
    okDraw = pcall(plugin.onDrawUI)
    assert_true(okDraw and g.held == true and g.a == 1, 'Suite 102: an open menu holds a ghost window: ' .. tostring(g.a))
    -- with the menu open the chrome colours come back for it
    pushes = {}
    okDraw = pcall(plugin.onDrawUI)
    chromeBack = false
    for _, v in ipairs(pushes) do if v.idx == 10 and math.abs(v.a - 0.9) < 0.001 then chromeBack = true end end
    assert_true(okDraw and (g.a >= 1 or chromeBack), 'Suite 102: an open menu draws with the original colours')
    win.ghost = false
    win.opacity = nil
    _G.ImGuiCol = hadCol
    drawMock.IsPopupOpen = nil
    drawMock.GetStyleColorVec4, drawMock.PushStyleColor, drawMock.PopStyleColor = nil, nil, nil
    drawMock.SetNextWindowBgAlpha, drawMock.IsWindowHovered = nil, nil
    print = quiet
    plugin.chatCommand('ghost')
    print = origPrint
    assert_eq(cfg.windows[1].ghost, true, 'Suite 102: /tacchat ghost toggles the first window')
    print = quiet
    plugin.chatCommand('ghost', cfg.windows[1].title)
    plugin.chatCommand('ghost', 'no such window')
    print = origPrint
    assert_eq(cfg.windows[1].ghost, false, 'Suite 102: /tacchat ghost <title> toggles that window; an unknown name changes nothing')

    -- Tells and notifications outlive the main ring: a conversation tab is
    -- not emptied by a fight's worth of combat lines.
    local function tabNamed(w, name) for i, t in ipairs(w.tabs) do if t.name == name then return t, i end end end
    local tellsTab = tabNamed(win, 'Tells')
    local socialTab = tabNamed(win, 'Social')
    local notifyTab = tabNamed(win, 'Notifications')
    assert_true(plugin.tabSource(tellsTab) == rt.keep and plugin.tabSource(notifyTab) == rt.keep and plugin.tabSource(socialTab) == rt.ring
        and plugin.tabSource({ tellWith = 'Bob', channels = nil }) == rt.keep and plugin.tabSource({ channels = { tell_in = true, say = true } }) == rt.ring,
        'Suite 102: conversation, Tells and Notifications tabs read from the kept ring; mixed tabs from the main ring')
    cfg.maxLines = 200
    cfg.tellPopouts = true
    plugin.TB.clearAll()   -- Clear all tabs: fresh rings and empty tab buffers
    assert_true(rt.ring.cap == 200 and rt.ring.last == 0 and rt.tabs[win.id .. '/' .. tellsTab.id].last == 0, 'Suite 102: Clear all tabs empties every buffer with the rings')
    S.events.TACChatAll.fn(P('Alice') .. " tells you, 'remember me'")
    S.events.TACChatAll.fn(P('Alice') .. " says, 'Genro are you there'")   -- a mention: a notification
    plugin.onTick()
    local tw = plugin.findTellWindow()
    local aliceTab = tw and plugin.findTellTab(tw, 'Alice')
    assert_true(aliceTab ~= nil, 'Suite 102: the tell opened a conversation tab')
    okDraw = pcall(plugin.onDrawUI)   -- every tab builds from its ring (the mock selects them all)
    local aliceSt = rt.tabs[tw.id .. '/' .. aliceTab.id]
    local tellsSt2 = rt.tabs[win.id .. '/' .. tellsTab.id]
    local notifySt = rt.tabs[win.id .. '/' .. notifyTab.id]
    local socialSt = rt.tabs[win.id .. '/' .. socialTab.id]
    assert_true(okDraw and aliceSt.last - aliceSt.first + 1 == 1 and tellsSt2.last - tellsSt2.first + 1 == 1 and notifySt.last - notifySt.first + 1 == 1
        and socialSt.last - socialSt.first + 1 == 2, 'Suite 102: the tell and the mention land in their tabs')
    for i = 1, 300 do
        S.events.TACChatAll.fn(P('Someone') .. " says, 'spam line " .. i .. "'")
        if i % 100 == 0 then plugin.onTick() end
    end
    plugin.onTick()
    assert_true(rt.ring.first > 2, 'Suite 102: the main ring evicted the tell and the mention')
    okDraw = pcall(plugin.onDrawUI)
    assert_true(okDraw and aliceSt.last - aliceSt.first + 1 == 1 and aliceSt.entries[aliceSt.first].text:find('remember me', 1, true) ~= nil,
        'Suite 102: the conversation tab still holds the tell after 300 lines of chat')
    assert_true(tellsSt2.last - tellsSt2.first + 1 == 1 and notifySt.last - notifySt.first + 1 == 1,
        'Suite 102: the Tells and Notifications tabs keep theirs too')
    assert_true(socialSt.last - socialSt.first + 1 == 200 and socialSt.entries[socialSt.first].text:find('spam line', 1, true) ~= nil, 'Suite 102: a general tab that takes every line is bounded by Buffer lines')
    for _, st in pairs(rt.tabs) do st.rebuild = true end
    okDraw = pcall(plugin.onDrawUI)
    assert_true(okDraw and aliceSt.last - aliceSt.first + 1 == 1 and tellsSt2.last - tellsSt2.first + 1 == 1,
        'Suite 102: a rebuild (filter / timestamp change) refills a conversation tab from the kept ring')
    -- Every tab owns its buffer: a guild line in a tab that does not take the
    -- combat spam survives the main ring evicting it (the user's guild / ooc
    -- history used to vanish after a fight), through rebuilds too.
    local guildTab = { id = 'gt', name = 'Guild', channels = { guild = true }, include = {}, exclude = {}, send = 'guild' }
    win.tabs[#win.tabs + 1] = guildTab
    S.events.TACChatAll.fn(P('Guildie') .. " tells the guild, 'raid at eight'")
    plugin.onTick()
    okDraw = pcall(plugin.onDrawUI)
    local guildSt = rt.tabs[win.id .. '/' .. guildTab.id]
    assert_true(okDraw and guildSt.last - guildSt.first + 1 == 1 and guildSt.entries[guildSt.first].text:find('raid at eight', 1, true) ~= nil, 'Suite 102: the guild line lands in the guild tab')
    local guildId = guildSt.entries[guildSt.first].id
    for i = 1, 250 do
        S.events.TACChatAll.fn('You slash a rat for ' .. i .. ' points of damage.')
        if i % 100 == 0 then plugin.onTick() end
    end
    plugin.onTick()
    assert_true(rt.ring.first > guildId and rt.ring.items[guildId] == nil, 'Suite 102: the main ring evicted the guild line')
    okDraw = pcall(plugin.onDrawUI)
    assert_true(okDraw and guildSt.last - guildSt.first + 1 == 1 and guildSt.entries[guildSt.first].id == guildId, 'Suite 102: the guild tab still shows it after the ring moved on')
    guildSt.rebuild = true
    okDraw = pcall(plugin.onDrawUI)
    assert_true(okDraw and guildSt.last - guildSt.first + 1 == 1 and guildSt.entries[guildSt.first].id == guildId, 'Suite 102: a rebuild keeps the lines only the tab still holds')
    S.events.TACChatAll.fn(P('Guildie') .. " tells the guild, 'bring food'")
    plugin.onTick()
    guildSt.rebuild = true
    okDraw = pcall(plugin.onDrawUI)
    assert_true(okDraw and guildSt.last - guildSt.first + 1 == 2 and guildSt.entries[guildSt.first].id == guildId and guildSt.entries[guildSt.last].text:find('bring food', 1, true) ~= nil,
        'Suite 102: a rebuild merges the tab buffer with the ring, oldest first, nothing doubled')
    guildTab.exclude = { 'food' }
    guildSt.rebuild = true
    okDraw = pcall(plugin.onDrawUI)
    assert_true(okDraw and guildSt.last - guildSt.first + 1 == 1 and guildSt.entries[guildSt.first].id == guildId, 'Suite 102: a filter change re-filters the lines the tab holds')
    guildTab.exclude = {}
    plugin.TB.clear(win, guildTab)
    guildSt.rebuild = true
    okDraw = pcall(plugin.onDrawUI)
    assert_true(okDraw and guildSt.last - guildSt.first + 1 == 0, 'Suite 102: Clear this tab: a rebuild does not bring the cleared lines back from the ring')
    S.events.TACChatAll.fn(P('Guildie') .. " tells the guild, 'after the clear'")
    plugin.onTick()
    okDraw = pcall(plugin.onDrawUI)
    assert_true(okDraw and guildSt.last - guildSt.first + 1 == 1 and guildSt.entries[guildSt.first].text:find('after the clear', 1, true) ~= nil, 'Suite 102: lines after the clear show')
    assert_eq(plugin.TB.cap(guildTab), 200, 'Suite 102: a general tab holds Buffer lines')
    assert_eq(plugin.TB.cap(tellsTab), cfg.history.lines, 'Suite 102: a tells tab holds the tell / notification line count')
    -- moving a tab to another window carries its buffer
    local w2 = plugin.newWindow('Second')
    plugin.moveTabToWindow(win, #win.tabs, w2)
    assert_true(rt.tabs[w2.id .. '/' .. guildTab.id] == guildSt and rt.tabs[win.id .. '/' .. guildTab.id] == nil, 'Suite 102: a moved tab keeps its buffer under the new window')
    plugin.moveTabToWindow(w2, #w2.tabs, win)
    plugin.removeTab(win, #win.tabs)
    for i = #cfg.windows, 1, -1 do if cfg.windows[i] == w2 then table.remove(cfg.windows, i) end end
    assert_true(rt.tabs[win.id .. '/' .. guildTab.id] == nil, 'Suite 102: removing the tab drops its state')
    -- a tell to Alice while she is offline: the notice lands in her tab and
    -- the Tells tab as an undelivered outgoing tell, in the warning colour,
    -- with a status line above the input
    S.events.TACChatAll.fn('alice is not online at this time.')
    plugin.onTick()
    okDraw = pcall(plugin.onDrawUI)
    local lastAlice = aliceSt.entries[aliceSt.last]
    assert_true(okDraw and aliceSt.last - aliceSt.first + 1 == 2 and lastAlice.tellFail == true and lastAlice.channel == 'tell_out' and lastAlice.sender == 'Alice',
        'Suite 102: the offline notice joins the conversation as an undelivered tell')
    assert_eq(lastAlice.hl, 'FFB84D', 'Suite 102: in the warning colour')
    assert_true(tellsSt2.last - tellsSt2.first + 1 == 2, 'Suite 102: and the Tells tab shows it')
    assert_true(rt.echo ~= nil and rt.echo:find('Alice is not online', 1, true) ~= nil, 'Suite 102: the status line says so')
    S.events.TACChatAll.fn(P('Bob') .. " tells you, 'new person'")
    plugin.onTick()
    okDraw = pcall(plugin.onDrawUI)
    assert_true(okDraw and aliceSt.last - aliceSt.first + 1 == 2 and plugin.findTellTab(tw, 'Bob') ~= nil, 'Suite 102: a tell from someone else leaves the other conversation intact')
    assert_eq(rt.keep.cap, cfg.history.lines, 'Suite 102: the kept ring is bounded by the history line count')
    cfg.tellPopouts = false
    cfg.maxLines = 2000
    rt.ring.cap = 2000
    -- a config with no windows at draw time is reported and reloaded instead of crashing the draw
    local savedWindows = cfg.windows
    cfg.windows = nil
    local repairPrints = {}
    print = function(...) repairPrints[#repairPrints + 1] = table.concat({ ... }, ' ') end
    okDraw, errDraw = pcall(plugin.onDrawUI)
    print = origPrint
    assert_true(okDraw and type(cfg.windows) == 'table' and #cfg.windows >= 1, 'Suite 102: missing windows table repaired at draw time: ' .. tostring(errDraw))
    assert_true(repairPrints[1] ~= nil and repairPrints[1]:find('config had no windows', 1, true) ~= nil and repairPrints[1]:find('init ran: 2', 1, true) ~= nil, 'Suite 102: repair diagnostic names the state: ' .. tostring(repairPrints[1]))
    win = cfg.windows[1]
    -- line context menu: "Show link in MQ window" echoes the raw line (link intact) through print
    local printedRaw = {}
    print = function(...) printedRaw[#printedRaw + 1] = table.concat({ ... }, ' ') end
    drawMock.MenuItem = function(label) return label == 'Show link in MQ window (clickable there)' end
    rt.ctxEntry = linkEntry
    rt.tabMenuTarget = nil
    okDraw, errDraw = pcall(plugin.onDrawUI)
    print = origPrint
    drawMock.MenuItem = function() return false end
    assert_true(okDraw, 'Suite 102: line context menu draws: ' .. tostring(errDraw))
    local echoed = false
    for _, l in ipairs(printedRaw) do if l:find(L, 1, true) and l:find('link: ', 1, true) then echoed = true end end
    assert_true(echoed, 'Suite 102: Show link in MQ window echoes the line with its \\x12 tags intact')
    local fonts = plugin.probeFonts()
    assert_true(fonts.err ~= nil and #fonts.list == 0, 'Suite 102: font probe reports an unsupported binding instead of failing')
    rt.tabMenuReq = { win = win, ti = 2 }
    okDraw, errDraw = pcall(plugin.onDrawUI)
    assert_true(okDraw and rt.tabMenuReq == nil and rt.tabMenuTarget.ti == 2, 'Suite 102: a tab right-click request opens the menu at window scope: ' .. tostring(errDraw))
    plugin.moveTabToPane(win, 1, 2, 'h')
    okDraw, errDraw = pcall(plugin.onDrawUI)
    assert_true(okDraw and win.panes == 2, 'Suite 102: two side-by-side panes draw: ' .. tostring(errDraw))
    win.splitDir = 'v'
    okDraw, errDraw = pcall(plugin.onDrawUI)
    assert_true(okDraw, 'Suite 102: stacked panes draw: ' .. tostring(errDraw))
    plugin.unsplit(win)
    -- ImGui scope balance under an injected error: counts of Begin*/End* must match and the error must be captured
    local bal = { child = 0, win = 0, tab = 0, popup = 0, tabbar = 0 }
    local origBeginChild, origEndChild, origBegin, origEnd = drawMock.BeginChild, drawMock.EndChild, drawMock.Begin, drawMock.End
    drawMock.BeginChild = function() bal.child = bal.child + 1 return true end
    drawMock.EndChild = function() bal.child = bal.child - 1 end
    drawMock.Begin = function() bal.win = bal.win + 1 return true, true end
    drawMock.End = function() bal.win = bal.win - 1 end
    drawMock.BeginTabItem = function() bal.tab = bal.tab + 1 return true end
    drawMock.EndTabItem = function() bal.tab = bal.tab - 1 end
    drawMock.BeginTabBar = function() bal.tabbar = bal.tabbar + 1 return true end
    drawMock.EndTabBar = function() bal.tabbar = bal.tabbar - 1 end
    drawMock.BeginPopup = function() bal.popup = bal.popup + 1 return true end
    drawMock.EndPopup = function() bal.popup = bal.popup - 1 end
    drawMock.InputText = function() error('binding exploded') end
    plugin.moveTabToPane(win, 1, 2, 'h')
    rt.stats.drawErr, rt.stats.drawErrShown = nil, nil
    rt.tabMenuTarget = { win = win, ti = 1 }
    rt.editor = { kind = 'tab', winId = win.id, tabId = win.tabs[1].id }
    print = quiet
    okDraw, errDraw = pcall(plugin.onDrawUI)
    print = origPrint
    assert_true(okDraw, 'Suite 102: an error inside a tab never escapes onDrawUI: ' .. tostring(errDraw))
    assert_true(rt.stats.drawErr ~= nil and rt.stats.drawErr:find('binding exploded', 1, true) ~= nil, 'Suite 102: the underlying error is captured for stats')
    assert_true(rt.stats.diagErr == nil, 'Suite 102: the error diagnostics themselves do not fail: ' .. tostring(rt.stats.diagErr))
    assert_true(bal.child == 0 and bal.win == 0 and bal.tab == 0 and bal.popup == 0 and bal.tabbar == 0, string.format('Suite 102: ImGui scopes balanced after the error (child %d win %d tab %d popup %d tabbar %d)', bal.child, bal.win, bal.tab, bal.popup, bal.tabbar))
    -- the failure flips the next frame into safe mode (one pane, default font), and the trace dumps on error
    print = quiet
    S.binds['/tacchat']('trace', 'on')
    assert_true(rt.trace ~= nil, 'Suite 102: /tacchat trace on')
    rt.stats.drawErr, rt.stats.drawErrShown = nil, nil
    rt.frameFailed = false
    okDraw = pcall(plugin.onDrawUI)          -- still erroring (InputText throws): records steps + dumps
    print = origPrint
    local tf = io.open(cfgDir .. '/tac_chat_trace_Genro.txt', 'r')
    local traceText = tf and tf:read('*a') or ''
    if tf then tf:close() end
    assert_true(traceText:find('BeginTabBar pane', 1, true) ~= nil and traceText:find('ERROR', 1, true) ~= nil, 'Suite 102: draw trace dumped with scope steps and the error')
    os.remove(cfgDir .. '/tac_chat_trace_Genro.txt')
    print = quiet
    okDraw = pcall(plugin.onDrawUI)
    print = origPrint
    assert_true(rt.safeMode == true, 'Suite 102: safe mode engaged after a failed frame')
    print = quiet
    S.binds['/tacchat']('safemode', 'off')
    S.binds['/tacchat']('trace', 'off')
    print = origPrint
    assert_true(rt.safeMode == false and rt.trace == nil, 'Suite 102: safe mode and trace switched off by command')
    drawMock.InputText = function(_, v) return v, false end
    drawMock.BeginChild, drawMock.EndChild, drawMock.Begin, drawMock.End = origBeginChild, origEndChild, origBegin, origEnd
    drawMock.BeginTabItem = function() return true end
    drawMock.EndTabItem, drawMock.BeginTabBar, drawMock.EndTabBar, drawMock.BeginPopup, drawMock.EndPopup = noop, function() return true end, noop, function() return true end, noop
    rt.editor = nil
    rt.stats.drawErr, rt.stats.drawErrShown = nil, nil
    rt.frameFailed = false
    plugin.unsplit(win)
    okDraw, errDraw = pcall(plugin.onDrawUI)
    assert_true(okDraw and rt.stats.drawErr == nil, 'Suite 102: clean draw after the injected error is gone: ' .. tostring(rt.stats.drawErr or errDraw))
    local allSt = rt.tabs[win.id .. '/' .. win.tabs[1].id]
    assert_true(allSt.rebuild == false and allSt.last > 0 and allSt.entries[1].nlines ~= nil, 'Suite 102: draw pass rebuilt the tab and laid out entries')
    -- Regression: a tab must keep showing lines after the ring has evicted its
    -- oldest entries (the queue is trimmed from the front, so `#` is unusable).
    cfg.maxLines = 300
    rt.ring.cap = 300
    for i = 1, 900 do S.events.TACChatAll.fn('You receive ' .. i .. ' gold.') end
    -- A drain is budgeted (at most 400 lines / 12 ms per tick, the rest stays
    -- queued in order), so a burst takes a few ticks; the tick stays short.
    plugin.onTick()
    assert_true(plugin.profile.drainLines == 400 and #rt.queue == 500 and plugin.profile.deferred == 500,
        string.format('Suite 102: one tick drains at most 400 lines and keeps the rest queued (drained %d, queued %d)', plugin.profile.drainLines, #rt.queue))
    assert_true(rt.queue[1] == 'You receive 401 gold.' and rt.queue[#rt.queue] == 'You receive 900 gold.', 'Suite 102: deferred lines keep their order')
    local ticks = 0
    while #rt.queue > 0 and ticks < 10 do plugin.onTick(); ticks = ticks + 1 end
    assert_true(#rt.queue == 0 and ticks == 2, 'Suite 102: the backlog drains over the next ticks (' .. ticks .. ')')
    okDraw, errDraw = pcall(plugin.onDrawUI)
    assert_true(okDraw, 'Suite 102: draw after eviction: ' .. tostring(errDraw))
    assert_true(allSt.first <= allSt.last and allSt.entries[allSt.last] ~= nil and allSt.entries[allSt.last].text == 'You receive 900 gold.', 'Suite 102: newest line still at the end of the tab queue after eviction')
    assert_true(allSt.last - allSt.first + 1 == 300 and allSt.entries[allSt.first].text == 'You receive 601 gold.', 'Suite 102: tab buffer bounded by Buffer lines, newest kept')
    for i = 1, 600 do S.events.TACChatAll.fn('You receive ' .. (900 + i) .. ' gold.') end
    ticks = 0
    while #rt.queue > 0 and ticks < 10 do plugin.onTick(); ticks = ticks + 1 end
    okDraw, errDraw = pcall(plugin.onDrawUI)
    assert_true(okDraw and allSt.entries[allSt.last].text == 'You receive 1500 gold.' and allSt.first == 1, 'Suite 102: queue compacts and keeps rendering the newest lines: ' .. tostring(errDraw))
    -- The event queue itself is capped: a stall that piles up more than 3000
    -- lines drops the oldest half rather than growing without bound.
    local dropsBefore = plugin.profile.dropped
    for i = 1, 3001 do S.events.TACChatAll.fn('spam ' .. i) end
    assert_true(#rt.queue == 1501 and plugin.profile.dropped - dropsBefore == 1500 and rt.queue[1] == 'spam 1501' and rt.queue[#rt.queue] == 'spam 3001',
        string.format('Suite 102: event queue capped at 3000 (queued %d, dropped %d)', #rt.queue, plugin.profile.dropped - dropsBefore))
    rt.queue = {}
    cfg.maxLines = 2000
    rt.ring.cap = 2000
    cfg.renderer = 'console'
    for _, st in pairs(rt.tabs) do st.rebuild = true end
    okDraw, errDraw = pcall(plugin.onDrawUI)
    assert_true(okDraw, 'Suite 102: classic renderer draws without error (no ConsoleWidget in the mock): ' .. tostring(errDraw))
    cfg.renderer = 'inline'
    rt.editor = nil

    -- 10. Tells: recent-partner list and the tabbed Tells window
    core.ImGui = drawMock
    cfg.recentTells = {}
    S.events.TACChatAll.fn(P('Playerone') .. " tells you, 'hi'")
    S.events.TACChatAll.fn("You told " .. P('Playertwo') .. ", 'hello'")
    S.events.TACChatAll.fn(P('Playerone') .. " tells you, 'again'")
    S.events.TACChatAll.fn("Spinevenom tells you, 'Attacking a rat Master.'")
    plugin.onTick()
    assert_eq(#cfg.recentTells, 2, 'Suite 102: recent tells lists each partner once (pets excluded)')
    assert_true(cfg.recentTells[1] == 'Playerone' and cfg.recentTells[2] == 'Playertwo', 'Suite 102: recent tells are most recent first, incoming and outgoing')
    for i = 1, 7 do plugin.noteTeller('Person' .. i) end
    assert_true(#cfg.recentTells == 5 and cfg.recentTells[1] == 'Person7', 'Suite 102: recent tells capped at five')
    assert_eq(#cfg.windows, 1, 'Suite 102: no Tells window while the option is off')
    cfg.tellPopouts = true
    S.events.TACChatAll.fn(P('Playerone') .. " tells you, 'pop'")
    S.events.TACChatAll.fn(P('Playerone') .. " tells you, 'pop2'")
    plugin.onTick()
    local tw = plugin.findTellWindow()
    assert_true(tw ~= nil and #cfg.windows == 2 and tw.open and tw.title == 'Tells' and tw.tellWindow == true and tw.id == 'tells', 'Suite 102: a tell opens the one Tells window')
    local t1 = plugin.findTellTab(tw, 'playerone')
    assert_true(t1 ~= nil and #tw.tabs == 1 and t1.name == 'Playerone' and t1.send == 'tell' and t1.tellTarget == 'Playerone' and t1.tellWith == 'Playerone', 'Suite 102: the conversation is one tab, set to reply to that person')
    S.events.TACChatAll.fn("You told " .. P('Playerone') .. ", 'back at you'")
    S.events.TACChatAll.fn(P('Playertwo') .. " tells you, 'other convo'")
    S.events.TACChatAll.fn('You receive 5 gold.')
    plugin.onTick()
    local t2, t2i = plugin.findTellTab(tw, 'Playertwo')
    assert_true(t2 ~= nil and t2i == 2 and #tw.tabs == 2 and #cfg.windows == 2, 'Suite 102: a second person gets a second tab, not a second window')
    assert_true(plugin.isTabActive(tw, 1) and not plugin.isTabActive(tw, 2), 'Suite 102: an arriving tell does not steal the selected conversation')
    okDraw, errDraw = pcall(plugin.onDrawUI)
    assert_true(okDraw and rt.stats.drawErr == nil, 'Suite 102: the Tells window draws: ' .. tostring(rt.stats.drawErr or errDraw))
    local st1 = rt.tabs[tw.id .. '/' .. t1.id]
    assert_true(st1 ~= nil and st1.last == 5, 'Suite 102: a conversation tab holds that whole conversation (both directions, from the ring): ' .. tostring(st1 and st1.last))
    local st2 = rt.tabs[tw.id .. '/' .. t2.id]
    assert_true(st2 ~= nil and st2.last == 2, 'Suite 102: ...and only that person (their earlier tell too): ' .. tostring(st2 and st2.last))
    -- the other player's name on a line is the clickable run
    local inLine, outLine, goldLine = rt.ring.items[rt.ring.last - 1], rt.ring.items[rt.ring.last - 2], rt.ring.items[rt.ring.last]
    assert_eq(inLine.player, 'Playertwo', 'Suite 102: the sender of an incoming tell is the clickable name')
    assert_eq(outLine.player, 'Playerone', 'Suite 102: the recipient of an outgoing tell is the clickable name')
    assert_true(goldLine.player == nil, 'Suite 102: a line with no player has no clickable name')
    local function runsOf(e)
        local out = {}
        plugin.layoutEntry(e, 10000, 7, false, function(t) return #t * 7 end, 13, function(_, text, _, _, _, isName) out[#out + 1] = { text = text, name = isName } end)
        return out
    end
    local r1 = runsOf(inLine)
    assert_true(r1[1].text == 'Playertwo' and r1[1].name == true and r1[2].name == false, 'Suite 102: the name is its own run at the start of a tell: ' .. tostring(r1[1].text))
    local r2 = runsOf(outLine)
    assert_true(r2[1].text == 'You told' and r2[1].name == false and r2[2].text == 'Playerone' and r2[2].name == true and r2[3].name == false, 'Suite 102: the name run is found mid-line: ' .. tostring(r2[2] and r2[2].text))
    S.events.TACChatAll.fn(P('Groupguy') .. " tells the group, 'inc'")
    S.events.TACChatAll.fn("a rat says 'Squeak'")
    S.events.TACChatAll.fn("You tell your party, 'ok'")
    S.events.TACChatAll.fn("You told Plainname, 'no link on this one'")
    plugin.onTick()
    assert_eq(rt.ring.items[rt.ring.last - 3].player, 'Groupguy', 'Suite 102: group / say / guild senders are clickable too')
    assert_true(rt.ring.items[rt.ring.last - 2].player == nil and rt.ring.items[rt.ring.last - 1].player == nil, 'Suite 102: NPCs and my own lines are not')
    local r3 = runsOf(rt.ring.items[rt.ring.last])
    assert_true(r3[2].text == 'Plainname,' and r3[2].name == true, 'Suite 102: an unlinked name is matched with its punctuation stuck on: ' .. tostring(r3[2] and r3[2].text))
    -- a clicked name is honoured before the next draw: the tab is added, selected (SetSelected on that frame) and its input focused
    local savedTIF = rawget(_G, 'ImGuiTabItemFlags')
    rawset(_G, 'ImGuiTabItemFlags', { SetSelected = 2 })
    local selectedLabels, focusCalls = {}, 0
    drawMock.BeginTabItem = function(label, _, flags) if flags then selectedLabels[#selectedLabels + 1] = label end return true end
    drawMock.SetKeyboardFocusHere = function() focusCalls = focusCalls + 1 end
    plugin.requestTell('Playerthree')
    okDraw, errDraw = pcall(plugin.onDrawUI)
    local t3, t3i = plugin.findTellTab(tw, 'Playerthree')
    assert_true(okDraw and t3 ~= nil and #tw.tabs == 4 and plugin.isTabActive(tw, t3i), 'Suite 102: clicking a name adds that person\'s tab and selects it: ' .. tostring(errDraw))

    assert_true(t3.send == 'tell' and t3.tellTarget == 'Playerthree' and t3.tellWith == 'Playerthree', 'Suite 102: the new tab is ready to send to them')
    assert_true(#selectedLabels == 1 and selectedLabels[1]:find('Playerthree', 1, true) ~= nil, 'Suite 102: the tab item is drawn with SetSelected once: ' .. tostring(selectedLabels[1]))
    assert_true(focusCalls >= 1 and rt.focusRequested == false and (rt.selectReq == nil or rt.selectReq[tw.id] == nil), 'Suite 102: the input took focus and the one-frame requests are cleared')
    selectedLabels = {}
    okDraw = pcall(plugin.onDrawUI)
    assert_true(okDraw and #selectedLabels == 0, 'Suite 102: the next frame draws the tab bar plainly')
    plugin.requestTell('playerthree')
    okDraw = pcall(plugin.onDrawUI)
    assert_true(okDraw and #tw.tabs == 4 and plugin.isTabActive(tw, t3i), 'Suite 102: clicking a name that already has a tab just selects it (case-insensitive)')
    drawMock.BeginTabItem = function() return true end
    drawMock.SetKeyboardFocusHere = noop
    rawset(_G, 'ImGuiTabItemFlags', savedTIF)
    plugin.chatCommand('tell', 'Playerfour')

    assert_true(#tw.tabs == 5 and plugin.findTellTab(tw, 'Playerfour') ~= nil and plugin.isTabActive(tw, 5), 'Suite 102: /tacchat tell <name> opens a conversation the same way')
    -- closing conversations: a tab at a time, the last one closes the window
    assert_true(plugin.closeTab(tw, 5) and plugin.closeTab(tw, select(2, plugin.findTellTab(tw, 'Playerthree'))) and #tw.tabs == 3 and plugin.findTellTab(tw, 'Playerthree') == nil and plugin.findTellTab(tw, 'Playerone') ~= nil, 'Suite 102: closing a conversation removes its tab')
    assert_true(plugin.closeTab(tw, 1) and plugin.closeTab(tw, 1) and plugin.closeTab(tw, 1) and plugin.findTellWindow() == nil and #cfg.windows == 1, 'Suite 102: closing the last conversation closes the Tells window')

    -- closing the window from its title bar removes it; the next tell brings it back
    S.events.TACChatAll.fn(P('Playerone') .. " tells you, 'pop3'")
    plugin.onTick()
    tw = plugin.findTellWindow()
    assert_true(tw ~= nil and #tw.tabs == 1, 'Suite 102: a tell after closing recreates the window with just that conversation')
    drawMock.Begin = function() return false, true end
    okDraw, errDraw = pcall(plugin.onDrawUI)
    drawMock.Begin = function() return true, true end
    assert_true(okDraw and plugin.findTellWindow() == nil and #cfg.windows >= 1, 'Suite 102: closing the Tells window removes it: ' .. tostring(errDraw))
    assert_true(cfg.windows[1] == win and win.open == false, 'Suite 102: closing the main window still just hides it')
    win.open = true
    ctrl.show_chat = true
    S.events.TACChatAll.fn(P('Playerone') .. " tells you, 'back?'")
    plugin.onTick()
    tw = plugin.findTellWindow()
    assert_true(tw ~= nil and plugin.findTellTab(tw, 'Playerone') ~= nil, 'Suite 102: the next tell recreates the window')
    -- the Tells window is per-session: sanitize drops it (and the old per-person popouts), the main window survives
    local persisted = plugin.sanitizeConfig({ version = 2, windows = { { id = 'main', tabs = { { id = 'all' } } }, { id = 'tells', tellWindow = true, tabs = { { id = 'tell1', tellWith = 'Someone' } } }, { id = 'tell1', tellWith = 'Someone', tabs = { { id = 'tell', tellWith = 'Someone' } } } } })
    assert_true(#persisted.windows == 1 and persisted.windows[1].id == 'main', 'Suite 102: the Tells window is not reloaded from disk')
    local rc = plugin.sanitizeConfig({ recentTells = { 'A', 3, 'B', '', 'C', 'D', 'E', 'F', 'G' } }).recentTells
    assert_true(#rc == 5 and rc[2] == 'B' and rc[5] == 'E', 'Suite 102: recent tells sanitized and capped')
    -- the game's tell-window format echoes my own tells as "Genro tells you, '...'":
    -- they must land in the recipient's conversation, never open a tab for me
    local winCount, tabCount = #cfg.windows, #tw.tabs
    local popTab = plugin.findTellTab(tw, 'Playerone')
    plugin.sendText(popTab, 'sent from the tab')
    S.events.TACChatAll.fn("Genro tells you, 'sent from the tab'")
    plugin.sendText(popTab, '/tell Playertwo via slash command')
    S.events.TACChatAll.fn("Genro tells you, 'via slash command'")
    S.events.TACChatAll.fn("Genro tells you, 'typed in the game box'")
    plugin.onTick()
    assert_true(plugin.findTellTab(tw, 'Genro') == nil and #cfg.windows == winCount and #tw.tabs == tabCount + 1 and plugin.findTellTab(tw, 'Playertwo') ~= nil, 'Suite 102: echoed self tells open the recipient\'s tab, never one for me')
    local lastTwo = rt.ring.items[rt.ring.last]
    assert_true(lastTwo.channel == 'tell_out' and lastTwo.outgoing and lastTwo.sender == 'Playertwo', 'Suite 102: an unmatched echo goes to the last recipient: ' .. tostring(lastTwo.sender))
    assert_eq(rt.ring.items[rt.ring.last - 1].sender, 'Playertwo', 'Suite 102: /tell typed in the input is matched to its echo')
    assert_eq(rt.ring.items[rt.ring.last - 2].sender, 'Playerone', 'Suite 102: a tell sent from the tab is matched to its echo')
    assert_eq(cfg.recentTells[1], 'Playertwo', 'Suite 102: echoed tells update the recent list with the recipient')
    S.events.TACChatAll.fn(P('Playerthree') .. " tells you, 'yo'")
    plugin.onTick()
    plugin.sendText(popTab, '/r back at you')
    S.events.TACChatAll.fn("Genro tells you, 'back at you'")
    plugin.onTick()
    assert_eq(rt.ring.items[rt.ring.last].sender, 'Playerthree', 'Suite 102: /r replies resolve to the last person who sent a tell')
    -- pet chatter is never a tell: no Tells tab, not in recent tells, and the pet is remembered for the session
    local recentBefore = #cfg.recentTells
    assert_true(rt.pets.Xorbaz == nil, 'Suite 102: Xorbaz is not a polled pet name')
    S.events.TACChatAll.fn("Xorbaz tells you, 'I beg forgiveness, Master. That target is too far away.")
    S.events.TACChatAll.fn('Xorbaz scores a critical hit! (400)')
    plugin.onTick()
    assert_true(plugin.findTellTab(tw, 'Xorbaz') == nil and #cfg.recentTells == recentBefore, 'Suite 102: a pet line with the Master mid-sentence opens no conversation')
    assert_true(rt.ring.items[rt.ring.last - 1].channel == 'petchat' and rt.ring.items[rt.ring.last].channel == 'pet', 'Suite 102: the pet is learned from its chatter, so its crits file under Pet: ' .. rt.ring.items[rt.ring.last].channel)
    plugin.onZoned()
    assert_true(rt.pets.Xorbaz == true, 'Suite 102: learned pets survive the name refresh')
    rt.learnedPets = nil
    plugin.onZoned()
    plugin.closeWindow(tw)
    cfg.tellPopouts = false
    assert_true(plugin.findTellWindow() == nil and #cfg.windows == 1, 'Suite 102: Tells window closed')

    -- the log height leaves room for the status row and the input frame
    local chatSrc = readFile('TAC/lua/tac/chat.lua')
    assert_true(chatSrc:find('GetFrameHeightWithSpacing', 1, true) ~= nil and chatSrc:find('GetTextLineHeightWithSpacing)', 1, true) ~= nil, 'Suite 102: input row height is measured, not guessed')
    assert_true(chatSrc:find('pv(SV.WindowPadding, core.px(', 1, true) ~= nil and chatSrc:find('PopStyleVar, pushedVars', 1, true) ~= nil, 'Suite 102: compact window chrome is pushed and popped')

    -- 10b. Mentions of my name and the Notifications tab
    local notifyTab
    for _, t in ipairs(win.tabs) do if t.notifyOnly then notifyTab = t end end
    assert_true(notifyTab ~= nil, 'Suite 102: the main window still has its Notifications tab')
    cfg.highlights = { { text = 'wts', lower = 'wts', color = '00FF00', beep = false, flash = true } }
    cfg.muted = { mutedguy = true }
    cfg.mention.on = true
    cfg.mention.beep = true
    rt.lastBeepAt = 0
    beeps = 0
    mockMq.cmd = function(c) if c == '/beep' then beeps = beeps + 1 else S.cmds[#S.cmds + 1] = c end end
    local before = rt.ring.last
    S.events.TACChatAll.fn(P('Groupguy') .. " tells the group, 'genro pull that one'")
    S.events.TACChatAll.fn(P('Groupguy') .. " tells the group, 'Genrox is here'")
    S.events.TACChatAll.fn("[Triune] Genro fired Distant Strike")
    S.events.TACChatAll.fn("You tell your party, 'Genro here'")
    S.events.TACChatAll.fn("a rat says 'Hail, Genro'")
    S.events.TACChatAll.fn(P('Mutedguy') .. " shouts, 'Genro!'")
    S.events.TACChatAll.fn(P('Auc') .. " auctions, 'WTS stuff'")
    S.events.TACChatAll.fn(P('Groupguy') .. " tells the group, 'WTS Genro'")
    S.events.TACChatAll.fn(P('Emoter') .. " waves at Genro.")
    plugin.onTick()
    local m1 = rt.ring.items[before + 1]
    assert_true(m1.mention == true and m1.notify == true and m1.hl == 'FFA040' and m1.flash == true, 'Suite 102: my name said by another player flags, colours and flashes the line (any case)')
    assert_eq(beeps, 1, 'Suite 102: mention beep uses the shared once-a-second throttle')
    for i = 2, 6 do
        local e = rt.ring.items[before + i]
        assert_true(e.mention == nil and e.notify == nil and e.hl == nil, 'Suite 102: no mention for a longer name / Triune output / my own line / an NPC / a muted sender: ' .. e.text)
    end
