    assert_eq(inserted[1] and inserted[1].name, 'Fungus Covered Scale Tunic', 'Suite 103: and the display name')
    assert_true(plugin.linkToChat('spells', 13, '/g'), 'Suite 103: linkToChat sends to a channel')
    assert_eq(sent[1], '/g ' .. plugin.spellLink(13), 'Suite 103: the channel command carries the link')
    assert_true(plugin.linkToChat('spells', 13, 'gu'), 'Suite 103: a channel without its slash is accepted')
    assert_eq(sent[2], '/gu ' .. plugin.spellLink(13), 'Suite 103: and gets the slash back')
    assert_true(not plugin.linkToChat('items', 999999), 'Suite 103: linkToChat declines an unknown item')
    assert_eq(#inserted + #sent, 3, 'Suite 103: nothing is sent for an unknown item')
    assert_true(plugin.onCommand('linkitem', { 'linkitem', 'fungus', 'covered', 'scale', 'tunic' }), 'Suite 103: /ac linkitem handled')
    assert_eq(inserted[2] and inserted[2].text, plugin.itemLink(2735), 'Suite 103: /ac linkitem by name goes to the input line')
    plugin.onCommand('linkitem', { 'linkitem', '/tell', 'Bob', '2002735' })
    assert_eq(sent[3], '/tell Bob ' .. plugin.itemLink(2002735), 'Suite 103: /ac linkitem /tell Name sends the tell')
    plugin.onCommand('linkspell', { 'linkspell', '/rs', 'complete', 'heal' })
    assert_eq(sent[4], '/rs ' .. plugin.spellLink(13), 'Suite 103: /ac linkspell /rs sends to raid')
    plugin.onCommand('linkcursor', { 'linkcursor' })
    assert_eq(inserted[3] and inserted[3].text, plugin.itemLink(2002735), 'Suite 103: /ac linkcursor links the cursor item at its tier')
    plugin.onCommand('linknpc', { 'linknpc', '/g', 'crow' })
    assert_eq(sent[5], '/g [Crow (North Qeynos)]', 'Suite 103: /ac linknpc sends the NPC link')
    plugin.onCommand('linktarget', { 'linktarget' })
    assert_eq(inserted[4] and inserted[4].text, '[myconid spore king (The Ruins of Sebilis)]', 'Suite 103: /ac linktarget links the database NPC behind the target')
    assert_true(plugin.linkToChat('npcs', 6, '/gu'), 'Suite 103: linkToChat handles NPCs')
    assert_eq(sent[6], '/gu [Crow (North Qeynos)]', 'Suite 103: NPC link sent to guild')
    local before = #inserted + #sent
    plugin.onCommand('linkitem', { 'linkitem', 'nothing', 'here' })
    plugin.onCommand('linkitem', { 'linkitem' })
    assert_eq(#inserted + #sent, before, 'Suite 103: /ac linkitem with no match or no text sends nothing')
    core.runtime.pluginManager = nil
    local clip = nil
    core.ImGui.SetClipboardText = function(t) clip = t end
    assert_true(plugin.linkToChat('items', 2735), 'Suite 103: without Chat Windows the link goes to the clipboard')
    assert_eq(clip, plugin.itemLink(2735), 'Suite 103: clipboard holds the raw link')
    core.ImGui.SetClipboardText = nil
    core.mq.cmdf = nil
    print = origPrint
    local gsrcLink = readFile('TAC/lua/tac/gamedb.lua')
    assert_true(gsrcLink:find("drawLinkButton('items', card.fullId, st.key or 'main')", 1, true) ~= nil, 'Suite 103: item cards carry the Link to chat button')
    assert_true(gsrcLink:find("drawLinkButton('spells', id, st.key or 'main')", 1, true) ~= nil, 'Suite 103: spell cards carry the Link to chat button')
    assert_true(gsrcLink:find("drawLinkButton('npcs', id, st.key or 'main')", 1, true) ~= nil, 'Suite 103: NPC cards carry the Link to chat button')

    -- 6. missing data is reported, not fatal
    DB.setDir(dir .. 'missing/')
    assert_true(not DB.readManifest().present, 'Suite 103: missing manifest flagged')
    DB.ensure('items')
    while DB.stepLoad(1) do end
    assert_true(DB.kinds.items.failed == true, 'Suite 103: missing index marks the kind failed')
    assert_eq(#DB.search('items', 'cloth'), 0, 'Suite 103: search on a missing index is empty')
    plugin.onDestroy()
    assert_eq(tracker.knownImmunity, nil, 'Suite 103: onDestroy removes the cast tracker hook')
    os.execute('rm -rf "' .. root .. '"')

    -- 7. core wiring and the chat hook
    local src = readFile('TAC/lua/triune.lua')
    assert_true(src:find('        show_gamedb              = false,', 1, true) ~= nil, 'Suite 103: defaultCtrl seeds show_gamedb')
    assert_true(src:find('if c.show_gamedb == nil then c.show_gamedb = false end', 1, true) ~= nil, 'Suite 103: sanitize seeds show_gamedb')
    assert_true(src:find("'gamedb.lua',", 1, true) ~= nil, 'Suite 103: discover() known-plugin probe lists gamedb.lua')
    assert_true(src:find('pcall(tracker.knownImmunity, spellName, tid, kind)', 1, true) ~= nil, 'Suite 103: cast tracker consults the database immunity hook')
    assert_true(src:find('dbChecked[tid] = nil', 1, true) ~= nil and src:find('dbChecked        = {}', 1, true) ~= nil, 'Suite 103: cast tracker clear() forgets database checks')
    -- the real createCastTracker with the hook installed
    do
        local body = src:match("local function createCastTracker%(%).-\nend\n") or src:match("local function createCastTracker%(%).-return tracker[%s\r\n]+end")
        assert_true(body ~= nil, 'Suite 103: createCastTracker body extracted')
        local calls = {}
        local env = setmetatable({
            isDetrimentalSpell = isDetrimentalSpell,
            mq = { TLO = { Spawn = function() return setmetatable({ CleanName = function() return 'a_mob' end }, { __call = function() return true end }) end } },
            print = quiet,
        }, { __index = _G })
        local chunk = loadstring(body .. '\nreturn createCastTracker()')
        assert_true(chunk ~= nil, 'Suite 103: createCastTracker body compiles')
        setfenv(chunk, env)
        local trk = chunk()
        trk.knownImmunity = function(spell, tid)
            calls[#calls + 1] = spell .. '@' .. tid
            if spell == 'Mesmerize' then return 'Unmezzable' end
            return nil
        end
        local locked, why = trk.isLockedOut('Mesmerize', 55, 'debuff')
        assert_true(locked == true and why == 'Immune', 'Suite 103: tracker reports the database immunity as Immune')
        trk.isLockedOut('Mesmerize', 55, 'debuff')
        assert_eq(#calls, 1, 'Suite 103: the database is consulted once per spawn and spell')
        assert_eq(trk.isLockedOut('Ice Comet', 55, 'dd'), false, 'Suite 103: non-immune spell is not locked')
        assert_eq(#calls, 2, 'Suite 103: each spell is checked once')
        trk.isLockedOut('Ice Comet', 55, 'dd')
        assert_eq(#calls, 2, 'Suite 103: negative results are cached too')
        assert_eq(trk.isLockedOut('Mesmerize', 56, 'debuff'), true, 'Suite 103: another spawn is checked on its own')
        assert_eq(trk.isLockedOut('Complete Heal', 55, 'heal'), false, 'Suite 103: beneficial spells never reach the hook')
        trk.clear(55)
        trk.isLockedOut('Mesmerize', 55, 'debuff')
        assert_eq(#calls, 4, 'Suite 103: clear(spawn) forgets the database check for that spawn')
        trk.knownImmunity = nil
        assert_eq(trk.isLockedOut('Mesmerize', 57, 'debuff'), false, 'Suite 103: without the hook the tracker behaves as before')
    end
    local gsrc = readFile('TAC/lua/tac/gamedb.lua')
    for _, bad in ipairs({ 'mq.delay(', 'mq.doevents()', 'require(', 'io.popen', 'os.execute' }) do
        assert_true(gsrc:find(bad, 1, true) == nil, 'Suite 103: gamedb.lua does not use ' .. bad)
    end
    assert_true(gsrc:find('core.pushTheme()', 1, true) ~= nil, 'Suite 103: gamedb.lua uses the core theme')
    assert_true(gsrc:find("flag = 'show_gamedb'", 1, true) ~= nil and gsrc:find('headerButton = true', 1, true) ~= nil, 'Suite 103: window metadata drives the header button')
    print = quiet
    local chat = assert(loadfile('TAC/lua/tac/chat.lua'))()
    print = origPrint
    assert_eq(chat.linkItemId('0000FBFA4' .. string.rep('0', 68)), 1032100, 'Suite 103: chat link payload carries the item id in hex (Earthen Bracer of Fortitude, Enchanted)')
    -- clicking a chat link opens a database card when the plugin is available
    local popped = nil
    local chatCore = {
        ctrl = {}, mq = { TLO = {}, event = noop, unevent = noop, bind = noop, unbind = noop, cmd = noop, gettime = function() return 0 end,
                          configDir = './tests/__nonexistent_cfg__' },
        ImGui = mockImGui, colors = {}, px = function(n) return n end, pushTheme = noop, popTheme = noop, accent = noop,
        preBeginWindow = noop, postBeginWindow = noop, saveLoadout = noop, setTooltip = noop,
        runtime = { pluginManager = { plugins = { gamedb = { enabled = true, instance = { search = function() return true end, popout = function(kind, id) popped = kind .. ':' .. id; return true end } } } } },
    }
    print = quiet
    chat.onInit(chatCore)
    chat.openItemLink({ name = 'Earthen Bracer of Fortitude (Enchanted)', payload = '0000FBFA4' .. string.rep('0', 68) })
    chat.runPendingLink()
    print = origPrint
    assert_eq(popped, 'items:1032100', 'Suite 103: a chat item link opens a database card for the exact id')
    -- an NPC's dialogue link ("[Respawning] will repopulate over time") is an
    -- item link carrying the server's saylink proxy id: clicking it says the
    -- link text instead of looking for an item
    local said = {}
    chatCore.mq.cmdf = function(fmt, ...) said[#said + 1] = string.format(fmt, ...) end
    local saylink = { name = 'Respawning', payload = '0000F423F' .. string.rep('0', 68) }
    assert_true(chat.isSaylink(saylink), 'Suite 103: item id 999999 marks a dialogue link')
    assert_true(not chat.isSaylink({ name = 'x', payload = '0000FBFA4' .. string.rep('0', 68) }), 'Suite 103: a real item is not a dialogue link')
    popped = nil
    print = quiet
    chat.openItemLink(saylink)
    chat.runPendingLink()
    print = origPrint
    assert_eq(said[1], '/say Respawning', 'Suite 103: clicking a dialogue link says its text to the target')
    assert_nil(popped, 'Suite 103: and opens no database card')
    assert_true(chat.rt.echo:find("Said 'Respawning'", 1, true) ~= nil, 'Suite 103: the status line reports the say')
    assert_true(not chat.lookupInDatabase(saylink), 'Suite 103: Look up in Database refuses a dialogue link')
    chat.cfg.saylinkId = 424242
    assert_true(not chat.isSaylink(saylink), 'Suite 103: /tacchat saylink <id> moves the proxy id')
    chat.cfg.saylinkId = 999999
    assert_true(chat.lookupInDatabase({ name = 'x', payload = '00000F23C' .. string.rep('0', 68) }), 'Suite 103: Look up in Database resolves by id')
    -- links handed in by the database land in the input line as [Name] and
    -- become the raw link when the line is sent
    chatCore.ctrl.show_chat = false
    local link1 = L .. '0000FBFA4' .. string.rep('0', 68) .. bracer .. L
    local link2 = '[Complete Heal]'
    assert_true(chat.insertLink(link1, bracer), 'Suite 103: insertLink places an item link')
    local fkey = chat.focusTargetKey()
    local fwin, ftab = chat.tabByKey(fkey)
    assert_true(fwin ~= nil and ftab ~= nil, 'Suite 103: the link went to the focus target tab')
    local fst = chat.rt.tabs[fkey]
    assert_eq(fst and fst.input, '[' .. bracer .. ']', 'Suite 103: the input line shows the link as [Name]')
    assert_eq(fst and fst.links[bracer], link1, 'Suite 103: the raw link waits in the tab')
    assert_eq(chatCore.ctrl.show_chat, true, 'Suite 103: inserting a link shows the chat window')
    assert_eq(chat.rt.focusKey, fkey, 'Suite 103: and asks for the input to take focus')
    assert_true(chat.insertLink(link2), 'Suite 103: insertLink reads a spell link name from its brackets')
    assert_eq(fst.input, '[' .. bracer .. '] [Complete Heal]', 'Suite 103: a second link follows after a space')
    assert_eq(chat.expandLinks(fst, fst.input .. ' for sale'), link1 .. ' ' .. link2 .. ' for sale', 'Suite 103: sending swaps the item placeholder for the raw link and leaves the spell text')
    assert_nil(fst.links, 'Suite 103: the link table is cleared with the draft')
    assert_eq(chat.expandLinks(fst, '[not a link]'), '[not a link]', 'Suite 103: brackets with no link are plain text')
    assert_true(not chat.insertLink('', 'x'), 'Suite 103: empty text is refused')
    fst.input = ''
    -- the game's own chat line: an item window icon click writes the item's
    -- name there (the client keeps the link as a tag MQ cannot read), so the
    -- name is matched to the displayed item, its link built from the id and
    -- placed here, and the name taken back out of the game line
    local gameLine = 'wts '
    local setCalls = 0
    local edit = setmetatable({ Text = function() return gameLine end, SetText = function(t) setCalls = setCalls + 1; gameLine = t; return true end },
        { __call = function() return 'TRUE' end })
    chatCore.mq.TLO.Window = function(name) return { Child = function(c) if name == 'ChatWindow' and c == 'CW_ChatInput' then return edit end end } end
    local shown = { [1] = { name = bracer, id = 1032100 }, [2] = { name = 'Sword of Fire', id = 5001 } }
    chatCore.mq.TLO.DisplayItem = function(i)
        local it = shown[i]
        if not it then return nil end
        return { Name = function() return it.name end, ID = function() return it.id end }
    end
    chatCore.mq.TLO.FindItem = function(n) if n == '=Carried Thing' then return { ID = function() return 777 end } end return { ID = function() return nil end } end
    local cmds = {}
    chatCore.mq.cmd = function(c) cmds[#cmds + 1] = c end
    chat.cfg.gameLinks = true
    chat.cfg.gameLineClose = false
    chat.GL.last = nil
    assert_eq(chat.GL.harvest(), 0, 'Suite 103: the first look at the game line only remembers it')
    gameLine = 'wts ' .. bracer
    assert_eq(chat.GL.harvest(), 1, 'Suite 103: a displayed item\'s name added to the game line becomes a link')
    assert_eq(gameLine, 'wts', 'Suite 103: the name is taken back out of the game line, the typed text stays')
    assert_eq(setCalls, 1, 'Suite 103: the game line is written back once')
    assert_eq(fst.input, '[' .. bracer .. ']', 'Suite 103: the link shows in this input as [Name]')
    assert_eq(fst.links[bracer], link1, 'Suite 103: the link is the 77-byte body for the item id')
    assert_eq(chat.GL.harvest(), 0, 'Suite 103: nothing new, nothing done')
    gameLine = 'wts hello'
    assert_eq(chat.GL.harvest(), 0, 'Suite 103: typed text that is no item name is not a link')
    assert_eq(setCalls, 1, 'Suite 103: and, with closing off, never written back')
    assert_eq(chat.GL.gameFocus, true, 'Suite 103: but shows the game line has the keyboard')
    gameLine = 'wts helloSword of Fire'
    assert_eq(chat.GL.harvest(), 1, 'Suite 103: a second displayed item links too')
    assert_eq(gameLine, 'wts hello', 'Suite 103: its name leaves the game line')
    assert_eq(fst.input, '[' .. bracer .. '] [Sword of Fire]', 'Suite 103: it follows the first link')
    assert_eq(fst.links['Sword of Fire'], L .. '000001389' .. string.rep('0', 68) .. 'Sword of Fire' .. L, 'Suite 103: built from that item\'s id')
    gameLine = 'wts helloCarried Thing'
    assert_eq(chat.GL.harvest(), 1, 'Suite 103: a name no item window shows is looked up in your own bags')
    assert_eq(fst.links['Carried Thing'], L .. '000000309' .. string.rep('0', 68) .. 'Carried Thing' .. L, 'Suite 103: and linked by that id')
    gameLine = 'wts helloUnknown Junk'
    assert_eq(chat.GL.harvest(), 0, 'Suite 103: an unknown name is not a link')
    assert_eq(gameLine, 'wts helloUnknown Junk', 'Suite 103: and stays in the game line')
    gameLine = ''
    chat.GL.harvest()
    chat.cfg.gameLinks = false
    gameLine = bracer
    chat.GL.poll()
    assert_eq(gameLine, bracer, 'Suite 103: links off, the game line keeps the name')
    chat.cfg.gameLinks = true
    -- closing the game line: Enter seen by the game opens it (the model),
    -- and while Enter is this input's key the line is emptied and closed
    -- with a keypress; text typed into the line proves it open and does the
    -- same; Enter on an open line sends and closes; Esc closes
    chat.cfg.gameLineClose = true
    chat.cfg.enterFocus = true
    chatCore.ctrl.show_chat = true
    chat.GL.gameFocus = false
    gameLine = ''
    chat.GL.harvest()
    local keys = {}
    local savedIsKeyPressed, savedGetIO = mockImGui.IsKeyPressed, mockImGui.GetIO
    mockImGui.IsKeyPressed = function(k) return keys[k] == true end
    mockImGui.GetIO = function() return { WantCaptureKeyboard = false, WantTextInput = false } end
    local hadKey103 = _G.ImGuiKey
    _G.ImGuiKey = _G.ImGuiKey or { Enter = 525, KeypadEnter = 615, Escape = 526 }
    local KEY = _G.ImGuiKey
    keys[KEY.Enter] = true
    chat.GL.poll()
    assert_eq(cmds[#cmds], '/keypress ENTER', 'Suite 103: Enter reaching the game opens its line; a keypress closes it again')
    assert_eq(chat.GL.gameFocus, false, 'Suite 103: the model says the line is closed')
    keys[KEY.Enter] = nil
    local before = #cmds
    gameLine = 'wwww'
    chat.GL.poll()
    assert_eq(gameLine, '', 'Suite 103: keys typed into the game line: it is emptied')
    assert_eq(cmds[#cmds], '/keypress ENTER', 'Suite 103: and closed')
    assert_eq(#cmds, before + 1, 'Suite 103: with one keypress')
    before = #cmds
    chat.GL.gameFocus = true
    keys[KEY.Enter] = true
    chat.GL.poll()
    assert_eq(#cmds, before, 'Suite 103: Enter on a line the model says is open sends it: no keypress')
    assert_eq(chat.GL.gameFocus, false, 'Suite 103: and the line is closed')
    keys[KEY.Enter] = nil
    chat.GL.gameFocus = true
    keys[KEY.Escape] = true
    chat.GL.poll()
    assert_eq(chat.GL.gameFocus, false, 'Suite 103: Esc closes the line')
    assert_eq(#cmds, before, 'Suite 103: without a keypress')
    keys[KEY.Escape] = nil
    mockImGui.GetIO = function() return { WantCaptureKeyboard = true, WantTextInput = true } end
    keys[KEY.Enter] = true
    chat.GL.poll()
    assert_eq(#cmds, before, 'Suite 103: Enter typed into ImGui never reached the game: nothing happens')
    assert_eq(chat.GL.gameFocus, false, 'Suite 103: and the model does not move')
    keys[KEY.Enter] = nil
    mockImGui.GetIO = function() return { WantCaptureKeyboard = false, WantTextInput = false } end
    chat.cfg.enterFocus = false
    keys[KEY.Enter] = true
    chat.GL.poll()
    assert_eq(#cmds, before, 'Suite 103: with Enter not this input\'s key the game line is left open')
    assert_eq(chat.GL.gameFocus, true, 'Suite 103: and the model says so')
    keys[KEY.Enter] = nil
    chat.cfg.enterFocus = true
    chat.GL.gameFocus = false
    mockImGui.IsKeyPressed, mockImGui.GetIO = savedIsKeyPressed, savedGetIO
    _G.ImGuiKey = hadKey103
    chatCore.mq.cmd = noop
    chatCore.mq.TLO.DisplayItem = nil
    chatCore.mq.TLO.FindItem = nil
    chatCore.mq.TLO.Window = nil
    fst.input = ''; fst.links = nil
    -- "[Spell Name]" / "[NPC (Zone)]" in a received line is a text link when
    -- the database knows the name; other brackets stay text; lines seen
    -- before the indexes were in are tokenized again once they are
    local dbReady = true
    local targets = { ['[Complete Heal]'] = { 'spells', 13 }, ['[Ice Comet]'] = { 'spells', 732 }, ['[Crow (North Qeynos)]'] = { 'npcs', 6 } }
    chatCore.runtime.pluginManager.plugins.gamedb.instance.textLinkTarget = function(text)
        if not dbReady then return nil, nil, false end
        local t = targets[text]
        if t then return t[1], t[2], true end
        return nil, nil, true
    end
    chatCore.runtime.pluginManager.plugins.gamedb.instance.DB = { isLoaded = function() return dbReady end }
    local se = { raw = "Bob says, 'try [Complete Heal] or [Ice Comet] [not a spell] on [Crow (North Qeynos)]'", text = '', id = 1 }
    local toks = chat.tokenize(se)
    assert_eq(#se.links, 3, 'Suite 103: two spell links and an NPC link found in the line')
    assert_eq(se.links[1].dbId .. '/' .. se.links[2].dbId .. '/' .. se.links[3].kind .. se.links[3].dbId, '13/732/npcs6', 'Suite 103: text links carry kind and id')
    local words = {}
    for _, t in ipairs(toks) do words[#words + 1] = t.t .. (t.link and ('<' .. t.link .. '>') or '') end
    assert_eq(table.concat(words, ' '), "Bob says, 'try Complete<1> Heal<1> or Ice<2> Comet<2> [not a spell] on Crow<3> (North<3> Qeynos)<3> '", 'Suite 103: link names are link words without brackets, other brackets stay text')
    assert_nil(se.linkRetry, 'Suite 103: a resolved line needs no retry')
    local itemAndSpell = { raw = 'Loot ' .. link1 .. ' and [Complete Heal]', text = '', id = 2 }
    chat.tokenize(itemAndSpell)
    assert_eq(#itemAndSpell.links, 2, 'Suite 103: item and text links share one link list')
    assert_eq(itemAndSpell.links[1].name .. '|' .. tostring(itemAndSpell.links[2].dbId), bracer .. '|13', 'Suite 103: item link first, spell link second')
    local triuneLine = { raw = '[Triune] cast [Complete Heal]', text = '', id = 4, channel = 'triune' }
    chat.tokenize(triuneLine)
    assert_eq(#triuneLine.links, 0, 'Suite 103: Triune output lines are never scanned for text links')
    dbReady = false
    chat.rt.textIndexReady = nil
    local early = { raw = 'early [Complete Heal] line', text = '', id = 3 }
    chat.tokenize(early)
    assert_eq(#early.links, 0, 'Suite 103: before the indexes are in, brackets stay text')
    assert_true(early.linkRetry, 'Suite 103: and the line is marked for a retry')
    early.layouts, early.layoutKeys = { x = 1 }, { 'x' }
    chat.rt.ring.items[chat.rt.ring.last + 1] = early
    chat.rt.ring.last = chat.rt.ring.last + 1
    chat.retryTextLinks()
    assert_true(early.tokens ~= nil, 'Suite 103: retry does nothing while the indexes load')
    dbReady = true
    chat.retryTextLinks()
    assert_nil(early.tokens, 'Suite 103: once the indexes are in, the marked line drops its tokens')
    assert_nil(early.layouts, 'Suite 103: and its cached layouts')
    chat.tokenize(early)
    assert_eq(#early.links, 1, 'Suite 103: re-tokenized, the spell link is found')
    chat.openTextLink(early.links[1])
    popped = nil
    chat.runPendingLink()
    assert_eq(popped, 'spells:13', 'Suite 103: clicking a spell link opens the spell card')
    chat.openTextLink(se.links[3])
    chat.runPendingLink()
    assert_eq(popped, 'npcs:6', 'Suite 103: clicking an NPC link opens the NPC card')
    chat.rt.ring.items[chat.rt.ring.last] = nil
    chat.rt.ring.last = chat.rt.ring.last - 1
    print = quiet
    chat.onDestroy()
    print = origPrint
    assert_eq(chat.linkItemId('00000F23C' .. string.rep('0', 68)), 62012, 'Suite 103: base tier link id (Paradisal Tunic of Faith)')
    assert_eq(chat.linkItemId('000000000'), nil, 'Suite 103: zero id is not a link id')
    assert_eq(chat.linkItemId('1'), nil, 'Suite 103: short payload has no id')
    assert_true(chat.uses and chat.uses.gamedb ~= nil, 'Suite 103: chat declares its gamedb use')
    local csrc = readFile('TAC/lua/tac/chat.lua')
    assert_true(csrc:find("'Look up in Database'", 1, true) ~= nil, 'Suite 103: chat tab menu offers the database lookup')
    local isrc = readFile('TAC/lua/tac/inventory.lua')
    assert_true(isrc:find('db.itemSummary(it.id)', 1, true) ~= nil, 'Suite 103: inventory tooltips show the database summary')
    assert_true(select(2, isrc:gsub('shiftHeld%(%) and openDatabaseCard%(it%)', '')) == 2, 'Suite 103: bag and bank slots open the card on Shift+Right-click')
    assert_true(isrc:find('if ImGui.IsItemClicked(1) then openDatabaseCard(it) end', 1, true) ~= nil, 'Suite 103: list rows open the card on right-click')
    assert_true(isrc:find("gamedb = 'Database lines in item tooltips", 1, true) ~= nil, 'Suite 103: inventory declares its gamedb use')
    local msrc = readFile('TAC/lua/tac/map.lua')
    assert_true(msrc:find('function plugin.showZone(zoneShort)', 1, true) ~= nil, 'Suite 103: map plugin exposes showZone for NPC spawn rows')
    assert_true(gsrc:find("map.showZone(s[1])", 1, true) ~= nil, 'Suite 103: NPC spawn rows carry a Map button')
    local ssrc = readFile('TAC/lua/tac/spellbook.lua')
    assert_true(ssrc:find('db.spellSummary(dbId)', 1, true) ~= nil and ssrc:find("db.popout('spells', dbId)", 1, true) ~= nil, 'Suite 103: spellbook tooltips use the database summary and middle-click cards')
end)()


-- ==========================================================================
-- Suite 104: Diagnostic logger (tac/triune_log.lua) + core wiring
-- ==========================================================================
;(function()
    print('--- Suite 104: Diagnostic logger (tac/triune_log.lua) ---')
    -- configDir '.' -> resolveDir probes ./../Logs (absent here) and falls
    -- back to '.', so the files land in the repo root; removed at the end.
    local L = tlog
    L._reset()
    local fileOn, dbgOn = false, false
    L.init({
        configDir = '.', version = 'T', getFileEnabled = function() return fileOn end,
        getDebug = function() return dbgOn end, identity = function() return 'TestSrv', 'Suite104' end,
        headerInfo = function() return { { 'class', 'WAR' } } end,
    })
    assert_eq(L.stripColors('\ag[Triune]\ax hi \a#FF00AAx \a-r y'), '[Triune] hi x  y', 'Suite 104: MQ colour codes are stripped')

    L.debug('t', 'dropped %d', 1)
    dbgOn = true
    L.debug('t', 'kept %d', 2)
    L.info('t', 'info %s', 'x')
    L.warn('t', 'plain')
    L.info('t', 'bad %d', 'notnum')
    L.capturePrint('\ar[Triune]\ax red line')
    local r = L.recent()
    assert_eq(#r, 5, 'Suite 104: debug lines are dropped while Debug Mode is off, everything else is kept')
    assert_true(r[1]:find('DBG %[t%] kept 2') ~= nil, 'Suite 104: debug line kept once Debug Mode is on')
    assert_true(r[4]:find('bad %%d notnum') ~= nil, 'Suite 104: a bad format string never throws')
    assert_true(r[5]:find('WRN %[chat%] %[Triune%] red line') ~= nil, 'Suite 104: captured red print lines are classed as warnings')
    assert_true(not L.isFileOpen(), 'Suite 104: no file while Log To File is off')

    fileOn = true
    L.tick()
    assert_true(L.isFileOpen(), 'Suite 104: tick opens the file once Log To File is on: ' .. tostring(L.lastOpenError()))
    local path = L.currentFilePath()
    assert_true(path ~= nil and path:find('triune_TestSrv_Suite104%.log$') ~= nil, 'Suite 104: file named after server + character: ' .. tostring(path))
    L.info('t', 'live line')
    L.flush()
    local content = readFile(path)
    assert_true(content:find('==== Triune vT log session', 1, true) ~= nil, 'Suite 104: session header written')
    assert_true(content:find('class:%s+WAR') ~= nil, 'Suite 104: header rows come from headerInfo()')
    assert_true(content:find('5 buffered lines', 1, true) ~= nil, 'Suite 104: ring contents replayed on open')
    assert_true(content:find('live line', 1, true) ~= nil, 'Suite 104: live lines appended')

    local dumpPath, derr = L.dump({
        { title = 'ctrl', value = { b = true, a = { x = 1, s = '\agq\ax' } } },
        { title = 'lines', value = { 'one', 'two' } },
    })
    assert_true(dumpPath ~= nil, 'Suite 104: dump writes a file: ' .. tostring(derr))
    local d = dumpPath and readFile(dumpPath) or ''
    assert_true(d:find('#### ctrl', 1, true) ~= nil, 'Suite 104: dump sections are titled')
    assert_true(d:find('a = {\n    s = "q",\n    x = 1,\n  },', 1, true) ~= nil, 'Suite 104: dump serialises nested tables with sorted keys and stripped colours')
    assert_true(d:find('#### lines\none\ntwo', 1, true) ~= nil, 'Suite 104: string-list sections are written line by line')
    assert_true(d:find('#### Recent log lines (6)', 1, true) ~= nil, 'Suite 104: dump ends with the ring buffer')
    local cyc = {}; cyc.self = cyc
    assert_true(L.serializeValue(cyc):find('<cycle>', 1, true) ~= nil, 'Suite 104: cyclic tables are cut short')

    fileOn = false
    L.tick()
    assert_true(not L.isFileOpen(), 'Suite 104: turning the option off closes the file')
    os.remove(path)
    if dumpPath then os.remove(dumpPath) end
    L._reset()

    -- Core wiring
    assert_true(src:find("local tlog              = require('tac.triune_log')", 1, true) ~= nil, 'Suite 104: triune.lua loads the logger')
    assert_true(src:find('tlog.hookPrint()', 1, true) ~= nil, 'Suite 104: print() is hooked so existing output is captured')
    assert_true(src:find('log_to_file              = false,', 1, true) ~= nil, 'Suite 104: log_to_file has a ctrl default')
    assert_true(src:find('log                   = tlog,', 1, true) ~= nil, 'Suite 104: plugins get core.log')
    assert_true(src:find('        tlog.tick()', 1, true) ~= nil, 'Suite 104: main loop ticks the logger')
    assert_true(src:find("cmd == 'log' or cmd == 'logfile'", 1, true) ~= nil, 'Suite 104: /ac log command')
    assert_true(src:find("cmd == 'dump' or cmd == 'dumpstate'", 1, true) ~= nil, 'Suite 104: /ac dump command')
    assert_true(src:find('function runtime.buildDiagnosticDump()', 1, true) ~= nil, 'Suite 104: diagnostic dump builder')
    assert_true(src:find('xpcall(runMainLoop, runtime.onMainLoopError)', 1, true) ~= nil, 'Suite 104: main loop crash is trapped and logged')
    assert_true(src:find("ImGui.Checkbox('Log To File'", 1, true) ~= nil, 'Suite 104: Settings has the Log To File checkbox')
    assert_true(src:find("ImGui.Button('Dump Diagnostics Now')", 1, true) ~= nil, 'Suite 104: Settings has the dump button')
    assert_true(src:find('xpcall(p.instance.onTick, debug.traceback)', 1, true) ~= nil, 'Suite 104: plugin hooks run under xpcall for tracebacks')
end)()


-- ==========================================================================
-- Suite 105: Bard songs -- keep singing vs sing once and resing on drop
-- ==========================================================================
;(function()
    print('--- Suite 105: Bard keep singing / sing once ---')
    local bardKeepSinging = loadFunc(src, 'bardKeepSinging', {})
    assert_true(bardKeepSinging({ cls = 'Brd', keep_singing = true, when = 'always' }), 'Suite 105: Brd gem with the box checked keeps singing')
    assert_true(bardKeepSinging({ cls = 'Brd', when = 'twist while fighting' }), 'Suite 105: legacy twist while fighting still keeps singing')
    assert_eq(bardKeepSinging({ cls = 'Brd', when = 'missing buff' }), false, 'Suite 105: unchecked Brd gem sings once')
    assert_eq(bardKeepSinging({ cls = 'Brd', keep_singing = false, when = 'in combat' }), false, 'Suite 105: box explicitly off sings once')
    assert_eq(bardKeepSinging({ cls = 'Clr', keep_singing = true }), false, 'Suite 105: non-bard gems never keep singing')
    assert_eq(bardKeepSinging(nil), false, 'Suite 105: nil gem is safe')

    local rt = { sungBuffs = {} }
    local clock = 100
    local env = { runtime = rt, os = setmetatable({ clock = function() return clock end }, { __index = os }) }
    local markSung = loadFunc(src, 'markSung', env)
    markSung('1_Aegolism', 'Clr')
    assert_eq(rt.sungBuffs['1_Aegolism'], true, 'Suite 105: non-bard marks stay a plain true')
    markSung('1_Selo', 'Brd')
    local st = rt.sungBuffs['1_Selo']
    assert_type(st, 'table', 'Suite 105: bard marks are a record')
    assert_eq(st.at, 100, 'Suite 105: record remembers when it was sung')
    assert_eq(st.seen, false, 'Suite 105: record starts unseen')
    st.seen = true
    markSung('1_Selo', 'Brd')
    assert_true(rt.sungBuffs['1_Selo'] == st, 'Suite 105: re-marking keeps the existing record')

    local up = false
    env.buffActive = function() return up end
    env.print = function() end
    env.BARD_DROP_GRACE = 2.0 -- module upvalue, supplied through the sandbox
    local bardSongDropped = loadFunc(src, 'bardSongDropped', env)
    rt.sungBuffs = {}
    assert_eq(bardSongDropped('1_Selo', 1, 'Selo'), false, 'Suite 105: no mark -> nothing to drop')
    markSung('1_Selo', 'Brd')
    clock = 110
    assert_eq(bardSongDropped('1_Selo', 1, 'Selo'), false, 'Suite 105: never seen up -> mark holds (undetectable song)')
    clock = 200
    assert_eq(bardSongDropped('1_Selo', 1, 'Selo'), false, 'Suite 105: still never seen -> holds for the life, as before')
    up = true
    assert_eq(bardSongDropped('1_Selo', 1, 'Selo'), false, 'Suite 105: song up -> holds')
    assert_eq(rt.sungBuffs['1_Selo'].seen, true, 'Suite 105: song was seen')
    up = false
    clock = 201
    assert_eq(bardSongDropped('1_Selo', 1, 'Selo'), false, 'Suite 105: one missed read is not a drop')
    assert_eq(rt.sungBuffs['1_Selo'].missingSince, 201, 'Suite 105: miss is timestamped')
    up = true
    clock = 202
    assert_eq(bardSongDropped('1_Selo', 1, 'Selo'), false, 'Suite 105: song back -> holds')
    assert_nil(rt.sungBuffs['1_Selo'].missingSince, 'Suite 105: a flicker resets the miss timer')
    up = false
    clock = 203
    bardSongDropped('1_Selo', 1, 'Selo')
    clock = 204.5
    assert_eq(bardSongDropped('1_Selo', 1, 'Selo'), false, 'Suite 105: inside the grace window -> holds')
    clock = 205.1
    assert_eq(bardSongDropped('1_Selo', 1, 'Selo'), true, 'Suite 105: gone past the grace window -> dropped')
    assert_nil(rt.sungBuffs['1_Selo'], 'Suite 105: drop releases the mark so the song is re-sung')
    rt.sungBuffs['1_Old'] = true
    assert_eq(bardSongDropped('1_Old', 1, 'Old'), false, 'Suite 105: a plain true mark is never released')

    -- wiring
    assert_true(src:find("if dur > 0 and buffActive(id, g.spell) and not bardKeepSinging(g) then", 1, true) ~= nil, 'Suite 105: castGem lets a keep-singing song recast over its own effect')
    assert_true(src:find("if bardKeepSinging(extra) then return true end", 1, true) ~= nil, 'Suite 105: missing buff never gates a keep-singing song')
    assert_true(src:find("if runtime.sungBuffs[key] and not bardSongDropped(key, targetId, spellName) then return false end", 1, true) ~= nil, 'Suite 105: missing buff releases a sung mark on drop')
    assert_true(src:find("ImGui.Checkbox('Twist##ks', ksCur)", 1, true) ~= nil, 'Suite 105: Spell Gems row has the Twist box for bards')
    assert_true(src:find("if cls == 'Brd' then g.keep_singing = not lu.bene end", 1, true) ~= nil, 'Suite 105: picking a song defaults the box from beneficial/detrimental')
    assert_true(src:find("keep_singing = (cls == 'Brd' and not bene) or nil,", 1, true) ~= nil, 'Suite 105: Import Bar defaults the box the same way')
    assert_true(src:find("tostring(g.keep_singing)", 1, true) ~= nil, 'Suite 105: the box is part of the loadout signature')
end)()

-- ==========================================================================
-- Suite 106: shared window options (title bar, ghost, lock) and the
-- right-click menu every window gets, riding on the Begin / End hooks
-- ==========================================================================
;(function()
    print('--- Suite 106: window options ---')
    local S = { cols = {}, popCols = 0, saves = 0, tooltips = {}, menuItems = {}, clicks = {}, popupOpen = false, hovered = false, released = false, anyItem = false, now = 0 }
    local mockImGui = setmetatable({
        PushStyleVar = function() end, PopStyleVar = function() end,
        PushStyleColor = function(idx, r, g, b, a) S.cols[#S.cols + 1] = { idx = idx, a = a } end,
        PopStyleColor = function(n) S.popCols = S.popCols + (n or 1); for _ = 1, (n or 1) do table.remove(S.cols) end end,
        GetStyleColorVec4 = function(idx) return { x = 0.2, y = 0.3, z = 0.4, w = 0.8 } end,
        IsWindowHovered = function() return S.hovered end,
        IsMouseReleased = function() return S.released end,
        IsAnyItemHovered = function() return S.anyItem end,
        IsPopupOpen = function() return S.popupOpen end,
        OpenPopup = function(id) S.opened = id end,
        BeginPopup = function(id) return S.opened == id end,
        EndPopup = function() S.opened = nil end,
        MenuItem = function(label, _, checked) S.menuItems[#S.menuItems + 1] = { label = label, checked = checked }; return S.clicks[label] == true end,
        BeginMenu = function() return true end, EndMenu = function() end,
        IsItemHovered = function() return false end,
        TextDisabled = function(t) S.header = t end,
        Separator = function() end, SetWindowFontScale = function() end, SetNextItemWidth = function() end,
        Combo = function(_, idx) return idx end,
    }, { __index = function() return function() end end })
    local ctrl = { ui_scale = 1.0, window_scale = {}, window_opts = {}, saved_window_positions = {} }
    local defs = {
        { key = 'group', name = 'Group Window', canLock = true, getLock = function() return S.locked == true end, setLock = function(v) S.locked = v end, setOpen = function(v) S.open = v end },
        { key = 'plain', name = 'Plain Window', canLock = false, setOpen = function(v) S.open = v end },
    }
    local runtime = {
        saveLoadout = function() S.saves = S.saves + 1 end, checkDisplaySizeChange = function() end,
        getManagedWindows = function() return defs end,
        saveWindowPositions = function() S.savedPositions = true end, triggerRestoreWindows = function() S.restored = true end,
    }
    local UI = {}
    local env = setmetatable({
        ctrl = ctrl, runtime = runtime, ImGui = mockImGui, UI = UI, mq = { gettime = function() return S.now end },
        ImGuiCol = { WindowBg = 2, Border = 5, TitleBg = 10, TitleBgActive = 11, Text = 0, Button = 21, ButtonHovered = 22, ScrollbarGrab = 15 },
        ImGuiWindowFlags = { NoTitleBar = 1, NoResize = 2, NoMove = 4 },
        ImGuiHoveredFlags = { RootAndChildWindows = 3, AllowWhenBlockedByActiveItem = 128, AllowWhenBlockedByPopup = 32 },
        ImGuiPopupFlags = { AnyPopupId = 128, AnyPopupLevel = 256 },
        ImGuiStyleVar = setmetatable({}, { __index = function(_, k) return k end }),
    }, { __index = _G })
    local function slice(startMarker, endMarker)
        local a = assert(src:find(startMarker, 1, true), 'Suite 106: source marker ' .. startMarker)
        local b = assert(src:find(endMarker, a, true), 'Suite 106: source marker ' .. endMarker)
        return src:sub(a, b - 1)
    end
    local code = slice('function UI.setTooltip(fmt, ...)', '\n-- UI: theme and style helpers')
        .. '\n' .. slice('function UI.pushTheme()', 'function UI.pushDisabledSliderStyle()')
        .. '\n' .. slice('function UI.windowOpts(key, create)', 'function runtime.saveWindowPositions(silent)')
    local chunk = assert((loadstring or load)(code, 'winopts'))
    setfenv(chunk, env)
    chunk()
    UI.setTooltip = function(t) S.tooltips[#S.tooltips + 1] = t end

    -- 1. Core wiring
    assert_true(src:find("if type(ctrl.window_opts) ~= 'table' then ctrl.window_opts = {} end", 1, true) ~= nil, 'Suite 106: sanitize seeds window_opts')
    for _, k in ipairs({ 'preEndWindow', 'windowFlags', 'windowBgAlpha', 'drawWindowMenuItems', 'windowOpts', 'setWindowOpt' }) do
        assert_true(src:find('            ' .. k .. ' ', 1, true) ~= nil or src:find('            ' .. k .. '=', 1, true) ~= nil, 'Suite 106: core API exposes ' .. k)
    end
    assert_true(src:find("ImGui.Begin(winTitle, open, UI.windowFlags('main', winFlags))", 1, true) ~= nil, 'Suite 106: main window takes the shared flags')
    assert_true(src:find("UI.preEndWindow('main')", 1, true) ~= nil and src:find("UI.preEndWindow('mini', true)", 1, true) ~= nil, 'Suite 106: core windows call the pre-End hook')
    assert_true(src:find("UI.windowBgAlpha('mini', ctrl.mini_alpha or 0.92)", 1, true) ~= nil, 'Suite 106: mini HUD opacity rides the ghost fade')
    -- every hooked plugin window: flags through the core, pre-End hook before End
    local hooked = { 'auto_accept', 'boxnet', 'hud_spellgems', 'buffbot', 'hud_cooldowns', 'hud_unitframes', 'cursor', 'hud_effects', 'hud_xtarget', 'auto_aa', 'spellbook', 'hud_group', 'dps', 'inventory', 'gamedb', 'map', 'buttons' }
    for _, f in ipairs(hooked) do
        local psrc = readFile('TAC/lua/tac/' .. f .. '.lua')
        assert_true(psrc:find('core.windowFlags(', 1, true) ~= nil, 'Suite 106: ' .. f .. ' passes its window flags through core.windowFlags')
        assert_true(psrc:find('core.preEndWindow(', 1, true) ~= nil, 'Suite 106: ' .. f .. ' calls core.preEndWindow before End')
        local nPre = select(2, psrc:gsub('core%.preBeginWindow%(', ''))
        local nEnd = select(2, psrc:gsub('core%.preEndWindow%(', ''))
        assert_true(nEnd >= nPre, 'Suite 106: ' .. f .. ' has a pre-End call for each hooked window (' .. nEnd .. ' vs ' .. nPre .. ')')
    end
    for _, f in ipairs({ 'hud_effects', 'hud_unitframes', 'hud_spellgems', 'hud_xtarget', 'hud_group', 'buttons' }) do
        local psrc = readFile('TAC/lua/tac/' .. f .. '.lua')
        assert_true(psrc:find('core.drawWindowMenuItems(', 1, true) ~= nil and psrc:find("core%.preEndWindow%([^)]-, true%)") ~= nil, 'Suite 106: ' .. f .. ' folds the shared items into its own menu and keeps the core one off')
    end
    for _, f in ipairs({ 'hud_effects', 'hud_unitframes', 'hud_spellgems', 'hud_xtarget', 'hud_group', 'hud_cooldowns' }) do
        assert_true(readFile('TAC/lua/tac/' .. f .. '.lua'):find('core.windowBgAlpha(', 1, true) ~= nil, 'Suite 106: ' .. f .. ' opacity rides the ghost fade')
    end

    -- 2. Options and flags
    assert_eq(UI.windowFlags('group', 8), 8, 'Suite 106: no options: flags pass through')
    UI.setWindowOpt('group', 'notitle', true)
    assert_eq(UI.windowFlags('group', 8), 9, 'Suite 106: Hide title bar adds NoTitleBar')
    assert_eq(S.saves, 1, 'Suite 106: an option change saves the loadout')
    UI.setWindowOpt('group', 'lock', true)
    assert_eq(UI.windowFlags('group', 0), 7, 'Suite 106: core lock adds NoMove + NoResize')
    UI.setWindowOpt('group', 'notitle', false)
    UI.setWindowOpt('group', 'lock', false)
    assert_nil(ctrl.window_opts.group, 'Suite 106: cleared options drop the record')
    assert_eq(S.saves, 4, 'Suite 106: each change saved once')
    UI.setWindowOpt('group', 'lock', false)
    assert_eq(S.saves, 4, 'Suite 106: no change, no save')

    -- 3. Ghost: frame colours pushed before Begin at the fade, content colours pushed back after, balanced by preEnd + popTheme
    UI.setWindowOpt('group', 'ghost', true)
    S.now = 1000
    S.hovered = false
    UI.pushTheme()
    UI.preBeginWindow('group')
    assert_true(runtime.ghost.group ~= nil and runtime.ghost.group.a == 1, 'Suite 106: ghost starts fully drawn')
    assert_true(runtime.ghostPush.group == nil, 'Suite 106: nothing pushed while fully drawn')
    UI.postBeginWindow('group')
    UI.preEndWindow('group')
    UI.popTheme()
    S.now = 1000 + runtime.GHOST.LINGER_MS + runtime.GHOST.OUT_MS + 50   -- the mouse has been away: fully faded
    S.cols, S.popCols = {}, 0
    UI.pushTheme()
    local themeCols = #S.cols
    UI.preBeginWindow('group')
    local g = runtime.ghost.group
    assert_true(g.a == 0, 'Suite 106: fully faded after linger + fade time: ' .. tostring(g.a))
    local gp = runtime.ghostPush.group
    assert_true(gp ~= nil and gp.frameN == #S.cols - themeCols and gp.frameN >= 7, 'Suite 106: frame colours pushed before Begin: ' .. tostring(gp and gp.frameN))
    local titleFaded, textFaded = false, false
    for _, c in ipairs(S.cols) do
        if c.idx == 10 and c.a == 0 then titleFaded = true end
        if c.idx == 0 and c.a == 0 then textFaded = true end
    end
    assert_true(titleFaded and textFaded, 'Suite 106: title bar and its text are at alpha 0 for Begin')
    assert_true(math.abs(UI.windowBgAlpha('group', 0.9)) < 0.001, 'Suite 106: the window\'s own opacity is scaled by the fade')
    assert_eq(UI.windowBgAlpha('other', 0.9), 0.9, 'Suite 106: a window without ghost keeps its opacity')
    UI.postBeginWindow('group')
    assert_true(gp.contentN >= 3, 'Suite 106: content colours (text, buttons) pushed back after Begin: ' .. tostring(gp.contentN))
    local textBack = false
    for _, c in ipairs(S.cols) do if c.idx == 0 and math.abs(c.a - 0.8) < 0.001 then textBack = true end end
    assert_true(textBack, 'Suite 106: the text colour is back at its original alpha for the content')
    local before = #S.cols
    UI.preEndWindow('group')
    assert_eq(#S.cols, before - 3, 'Suite 106: preEndWindow pops the content colours (inside the window)')
    assert_eq(gp.contentN, 0, 'Suite 106: content count cleared')
    UI.popTheme()
    assert_eq(#S.cols, 0, 'Suite 106: popTheme pops the frame colours and the theme: stack balanced')
    assert_nil(runtime.ghostPush.group, 'Suite 106: push record released')
    -- hover brings it back
    S.hovered = true
    S.now = S.now + 10
    UI.pushTheme(); UI.preBeginWindow('group'); UI.postBeginWindow('group'); UI.preEndWindow('group'); UI.popTheme()
    assert_true(g.held == true, 'Suite 106: hovered window is held')
    S.now = S.now + runtime.GHOST.IN_MS
    UI.pushTheme(); UI.preBeginWindow('group'); UI.postBeginWindow('group'); UI.preEndWindow('group'); UI.popTheme()
    assert_true(g.a == 1 and #S.cols == 0, 'Suite 106: fully back under the mouse, nothing left on the stack')
    -- a popup anywhere holds it
    S.hovered = false
    S.popupOpen = true
    S.now = S.now + runtime.GHOST.LINGER_MS + runtime.GHOST.OUT_MS
    UI.pushTheme(); UI.preBeginWindow('group'); UI.postBeginWindow('group'); UI.preEndWindow('group'); UI.popTheme()
    S.now = S.now + 50
    UI.pushTheme(); UI.preBeginWindow('group'); UI.postBeginWindow('group'); UI.preEndWindow('group'); UI.popTheme()
    assert_true(g.held == true and g.a == 1, 'Suite 106: an open popup holds a ghost window')
    S.popupOpen = false
    -- a window that skips preEndWindow is still balanced by popTheme
    S.now = S.now + runtime.GHOST.LINGER_MS + runtime.GHOST.OUT_MS + 50
    UI.pushTheme(); UI.preBeginWindow('group'); UI.postBeginWindow('group'); UI.popTheme()
    assert_eq(#S.cols, 0, 'Suite 106: popTheme pops content colours a window forgot (stack stays balanced)')
    UI.setWindowOpt('group', 'ghost', false)
    UI.pushTheme(); UI.preBeginWindow('group'); UI.postBeginWindow('group'); UI.preEndWindow('group'); UI.popTheme()
    assert_nil(runtime.ghost.group, 'Suite 106: ghost off drops the fade state')

    -- 4. The shared menu: opens on a right-click over the window that no item took
    S.hovered, S.released, S.anyItem = true, true, true
    UI.pushTheme(); UI.preBeginWindow('plain'); UI.postBeginWindow('plain'); UI.preEndWindow('plain'); UI.popTheme()
    assert_nil(S.opened, 'Suite 106: right-click over an item does not open the window menu')
    S.anyItem = false
    S.menuItems = {}
    UI.pushTheme(); UI.preBeginWindow('plain'); UI.postBeginWindow('plain'); UI.preEndWindow('plain'); UI.popTheme()
    assert_true(S.opened == nil and #S.menuItems >= 5, 'Suite 106: right-click over empty window space opens the shared menu (' .. #S.menuItems .. ' items)')
    assert_eq(S.header, 'Plain Window', 'Suite 106: the menu is headed with the window name')
    local labels = {}
    for _, m in ipairs(S.menuItems) do labels[m.label] = m end
    assert_true(labels['Hide title bar'] and labels['Ghost: fade the frame when the mouse is away'] and labels['Lock position & size'] and labels['Close window'] and labels['Save all window positions'],
        'Suite 106: menu offers title bar, ghost, lock, layout and close')
    S.released = false
    S.clicks = { ['Hide title bar'] = true }
    S.opened = '##tacWindowMenu_plain'
    UI.pushTheme(); UI.preBeginWindow('plain'); UI.postBeginWindow('plain'); UI.preEndWindow('plain'); UI.popTheme()
    assert_true(ctrl.window_opts.plain and ctrl.window_opts.plain.notitle == true, 'Suite 106: Hide title bar from the menu sets the option')
    S.clicks = { ['Close window'] = true }
    S.opened = '##tacWindowMenu_plain'
    UI.pushTheme(); UI.preBeginWindow('plain'); UI.postBeginWindow('plain'); UI.preEndWindow('plain'); UI.popTheme()
    assert_eq(S.open, false, 'Suite 106: Close window closes through the Window Layout entry')
    S.clicks = { ['Lock position & size'] = true }
    S.opened = '##tacWindowMenu_group'
    UI.pushTheme(); UI.preBeginWindow('group'); UI.postBeginWindow('group'); UI.preEndWindow('group'); UI.popTheme()
    assert_true(S.locked == true and ctrl.window_opts.group == nil, 'Suite 106: a window with its own lock locks through it, not the core option')
    S.clicks = {}
    S.opened = nil
    -- a window with its own menu keeps the core one off
    S.released, S.hovered, S.anyItem = true, true, false
    UI.pushTheme(); UI.preBeginWindow('plain'); UI.postBeginWindow('plain'); UI.preEndWindow('plain', true); UI.popTheme()
    assert_nil(S.opened, 'Suite 106: ownMenu windows do not get the core menu')
    -- drawWindowMenuItems with items turned off (as the HUD menus use it)
    S.menuItems = {}
    UI.drawWindowMenuItems('group', { header = false, lock = false, scale = false, layout = false, close = false })
    assert_eq(#S.menuItems, 2, 'Suite 106: HUD menus get just Hide title bar + Ghost')

    -- 5. Windows outside the Window Layout table: a name and a close action of their own
    S.menuItems, S.closedCompact = {}, false
    S.clicks = { ['Close window'] = true }
    UI.drawWindowMenuItems('dps_compact', { name = 'DPS compact window', onClose = function() S.closedCompact = true end })
    assert_true(S.header == 'DPS compact window' and S.closedCompact == true, 'Suite 106: an unmanaged window names itself and closes through its own action')
    S.clicks = {}
    S.menuItems = {}
    UI.drawWindowMenuItems('gamedb_pop', { name = 'Database cards', close = false })
    local hasClose = false
    for _, m in ipairs(S.menuItems) do if m.label == 'Close window' then hasClose = true end end
    assert_true(S.header == 'Database cards' and not hasClose, 'Suite 106: close can be left out (the cards close with their X)')
    -- several windows under one theme scope: postEndWindow pops each one's ghost colours right after its End
    UI.setWindowOpt('gamedb_pop', 'ghost', true)
    S.hovered, S.popupOpen = false, false
    S.now = S.now + 10
    UI.pushTheme(); UI.preBeginWindow('gamedb_pop'); UI.postBeginWindow('gamedb_pop'); UI.preEndWindow('gamedb_pop', false, { close = false }); UI.postEndWindow('gamedb_pop'); UI.popTheme()
    S.now = S.now + runtime.GHOST.LINGER_MS + runtime.GHOST.OUT_MS + 50
    S.cols = {}
    UI.pushTheme()
    local base = #S.cols
    for _ = 1, 3 do
        UI.preBeginWindow('gamedb_pop')
        assert_true(#S.cols > base, 'Suite 106: each card pushes its frame colours')
        UI.postBeginWindow('gamedb_pop'); UI.preEndWindow('gamedb_pop', false, { close = false }); UI.postEndWindow('gamedb_pop')
        assert_eq(#S.cols, base, 'Suite 106: postEndWindow pops them before the next card')
    end
    assert_eq(#runtime.ghostStack, 0, 'Suite 106: nothing left for popTheme to pop')
    UI.popTheme()
    assert_eq(#S.cols, 0, 'Suite 106: theme scope balanced across three cards')
    UI.setWindowOpt('gamedb_pop', 'ghost', false)
    local dsrc = readFile('TAC/lua/tac/dps.lua')
    assert_true(dsrc:find("core.preBeginWindow('dps_compact')", 1, true) ~= nil and dsrc:find("core.windowFlags('dps_compact', flags)", 1, true) ~= nil and dsrc:find("name = 'DPS compact window', onClose = closeCompact", 1, true) ~= nil,
        'Suite 106: the DPS compact window has its own layout key with the shared options and menu')
    local gsrc = readFile('TAC/lua/tac/gamedb.lua')
    assert_true(gsrc:find("core.preBeginWindow('gamedb_pop')", 1, true) ~= nil and gsrc:find("core.postEndWindow('gamedb_pop')", 1, true) ~= nil, 'Suite 106: database cards share one key and pop per card')
end)()

-- ============================================================================
-- Suite 107: Update Checker plugin (tac/update_check.lua) -- version compare,
-- release JSON parsing, settings round-trip, and the non-blocking contract.
-- ============================================================================
do
    print('--- Suite 107: Update Checker plugin ---')
    local P = assert(loadfile('TAC/lua/tac/update_check.lua'))()
    assert_eq(P.id, 'update_check', 'Suite 107: plugin id')
    assert_true(P.onInit ~= nil and P.onTick ~= nil and P.onDrawUI ~= nil and P.onDrawSettings ~= nil and P.onDestroy ~= nil
        and P.onCommand ~= nil and P.onSaveSettings ~= nil and P.onLoadSettings ~= nil, 'Suite 107: full plugin lifecycle')
    assert_eq(P.runOutOfCombatOnly, false, 'Suite 107: polling ticks are microseconds, so the plugin keeps ticking in combat')
    assert_eq(P.hasThread, false, 'Suite 107: no fiber; the request is a state machine driven by onTick')

    -- Version comparison: tags are 'V2.14' / 'v2.15' / '2.0.3'
    local c = P.compareVersions
    assert_true(c('V2.16', '2.15') > 0, 'Suite 107: V2.16 is newer than 2.15')
    assert_true(c('v2.15', '2.15') == 0, 'Suite 107: v prefix is ignored')
    assert_true(c('V2.14', '2.15') < 0, 'Suite 107: V2.14 is older than 2.15')
    assert_true(c('3', '2.99') > 0, 'Suite 107: major wins over minor')
    assert_true(c('2.15.1', '2.15') > 0, 'Suite 107: extra patch component counts as newer')
    assert_true(c('2.15', '2.15-beta') == 0, 'Suite 107: suffixes without digits are ignored')
    assert_eq(#P.parseVersion('V2.0.3'), 3, 'Suite 107: parseVersion keeps every numeric component')

    -- Release JSON: only what the GitHub /releases/latest payload provides
    local payload = '{"url":"https://api.github.com/x","tag_name":"V2.16","name":"Release \\"V2.16\\"",'
        .. '"html_url":"https://github.com/gennro/TriuneAutocombat/releases/tag/V2.16","published_at":"2026-09-20T10:00:00Z",'
        .. '"body":"## 2026-09-20\\n\\n- **Thing** (`x.lua`).\\n  - Detail with a } brace\\n\\n---\\n\\n## Install\\n1. ignore","assets":[{"name":"a.zip"}]}'
    assert_true(P.jsonComplete(payload), 'Suite 107: complete payload passes jsonComplete')
    assert_true(not P.jsonComplete(payload:sub(1, #payload - 5)), 'Suite 107: truncated payload fails jsonComplete')
    assert_true(not P.jsonComplete(payload:sub(1, 60)), 'Suite 107: payload cut inside a string fails jsonComplete')
    assert_true(P.jsonComplete('  {"a":"}"}  '), 'Suite 107: braces inside strings do not count')
    assert_eq(P.jsonString(payload, 'tag_name'), 'V2.16', 'Suite 107: tag_name extracted')
    assert_eq(P.jsonString(payload, 'name'), 'Release "V2.16"', 'Suite 107: escaped quotes unescaped')
    assert_eq(P.jsonString(payload, 'published_at'), '2026-09-20T10:00:00Z', 'Suite 107: published_at extracted')
    assert_eq(P.jsonString(payload, 'missing'), nil, 'Suite 107: missing key returns nil')
    local notes = P.summarizeNotes(P.jsonString(payload, 'body'))
    assert_true(notes:find('2026-09-20', 1, true) ~= nil and notes:find('- Thing (x.lua).', 1, true) ~= nil,
        'Suite 107: notes summary strips markdown markers')
    assert_true(notes:find('Install', 1, true) == nil, 'Suite 107: notes summary stops at the --- install section')
    assert_eq(P.summarizeNotes(''), nil, 'Suite 107: empty notes give nil')

    -- Settings round-trip
    P.onLoadSettings({ autoCheck = false, frequency = 'weekly', popup = false, skipTag = 'V2.16', lastCheckAt = 123, lastTag = 'V2.14' })
    local saved = P.onSaveSettings()
    assert_true(saved.autoCheck == false and saved.frequency == 'weekly' and saved.popup == false and saved.skipTag == 'V2.16'
        and saved.lastCheckAt == 123 and saved.lastTag == 'V2.14', 'Suite 107: settings round-trip')
    P.onLoadSettings({ frequency = 'bogus', skipTag = '' })
    saved = P.onSaveSettings()
    assert_eq(saved.frequency, 'weekly', 'Suite 107: unknown frequency is ignored')
    assert_eq(saved.skipTag, nil, 'Suite 107: empty skipTag clears the skip')
    assert_true(P.onCommand('nope', { 'nope' }) == false, 'Suite 107: unrelated commands are not claimed')

    -- Non-blocking contract: no process spawn, no mq.delay, async COM polling
    local src = readFile('TAC/lua/tac/update_check.lua')
    assert_true(src:find('io.popen', 1, true) == nil and src:find('os.execute', 1, true) == nil,
        'Suite 107: the update checker never spawns a process')
    assert_true(src:find('mq.delay', 1, true) == nil, 'Suite 107: the update checker never calls mq.delay')
    assert_true(src:find("variant(VT_BOOL, 'boolVal', -1)", 1, true) ~= nil, 'Suite 107: WinHttpRequest is opened in async mode')
    assert_true(src:find('succeeded[0] = -1', 1, true) ~= nil, 'Suite 107: WaitForResponse out-param is pre-set for Wine')
    assert_true(src:find("if not http.headers then", 1, true) ~= nil and src:find('vt.get_Status(req, s)', 1, true) ~= nil,
        'Suite 107: Status is polled before the body is touched')
    assert_true(src:find("pcall(ffi.typeof, 'IWinHttpRequest')", 1, true) ~= nil, 'Suite 107: cdef is guarded against plugin reloads')
    assert_true(src:find("'User-Agent'", 1, true) ~= nil, 'Suite 107: GitHub API requests carry a User-Agent')
end

-- ============================================================================
-- Suite 108: Inventory & Bank Manager -- Box Inventories (snapshot codec,
-- paging, box search, give workflow over a scripted client, trade accept,
-- trust gating, settings round-trip, commands).
-- ============================================================================
print('--- Suite 108: Inventory Box Inventories ---')
do
    local printed = {}
    local quietPrint = function(...) printed[#printed + 1] = table.concat({ ... }, ' ') end
    local noop = function() end
    local passthrough = function(_, v) return v end
    local mockImGui = setmetatable({
        Checkbox = passthrough, Button = function() return false end, SmallButton = function() return false end,
        IsItemHovered = function() return false end, BeginTable = function() return false end,
        Begin = function() return false, false end, BeginPopup = function() return false end,
        SliderInt = function(_, v) return v, false end, InputTextWithHint = function(_, _, v) return v, false end,
        RadioButton = function() return false end, Selectable = function() return false end,
        BeginChild = function() return true end, BeginTabBar = function() return true end, BeginTabItem = function() return true end,
    }, { __index = function() return function() end end })

    -- A scripted client: cursor / target / spawns / trade window are plain
    -- fields the test flips, and every mq command is recorded.
    local function makeWorld()
        local w = { cmds = {}, cursorId = 0, targetId = 0, tradeOpen = false, hisName = '', spawns = {}, items = {}, saves = 0, nowMs = 100000 }
        local mq = {
            configDir = './tests/__nonexistent_cfg__',
            cmd = function(c) w.cmds[#w.cmds + 1] = c end,
            cmdf = function(f, ...) w.cmds[#w.cmds + 1] = string.format(f, ...) end,
            gettime = function() return w.nowMs end,
            TLO = {
                Me = { CleanName = function() return 'Giver' end, X = function() return 0 end, Y = function() return 0 end, Z = function() return 0 end },
                Zone = { ShortName = function() return 'poknowledge' end },
                Cursor = setmetatable({ ID = function() return w.cursorId end }, { __call = function() return w.cursorId > 0 end }),
                Target = { ID = function() return w.targetId end },
                Window = function(name)
                    if name == 'TradeWnd' then
                        return setmetatable({ Open = function() return w.tradeOpen end,
                            Child = function() return setmetatable({ Text = function() return w.hisName end }, { __call = function() return true end }) end },
                            { __call = function() return true end })
                    end
                    return setmetatable({ Open = function() return false end }, { __call = function() return true end })
                end,
                Spawn = function(q)
                    local name = q:match('^pc =(.+)$') or q:match('^pc (.+)$')
                    local sp = name and w.spawns[name]
                    if not sp then return setmetatable({}, { __call = function() return false end }) end
                    return setmetatable({ ID = function() return sp.id end, Distance3D = function() return sp.dist end, Distance = function() return sp.dist end },
                        { __call = function() return true end })
                end,
            },
        }
        local ctrl = { plugins = {}, show_inv = true }
        local core = {
            VERSION = '3.1', ctrl = ctrl, mq = mq, ImGui = mockImGui, runtime = {}, DATA = {},
            colors = { GOLD = { 1, 1, 1, 1 }, ARC = { 1, 1, 1, 1 }, MUTED = { 1, 1, 1, 1 }, GOOD = { 1, 1, 1, 1 }, WARN = { 1, 1, 1, 1 }, ERR = { 1, 1, 1, 1 } },
            px = function(n) return n end, pushTheme = noop, popTheme = noop, accent = noop, setTooltip = noop,
            preBeginWindow = noop, postBeginWindow = noop,
            saveLoadout = function() w.saves = w.saves + 1 end,
            -- Cooperative delay stand-in: advance the scripted world, then test the condition.
            delay = function(ms, cond)
                if w.onDelay then w.onDelay(ms) end
                if cond then local ok, r = pcall(cond) return ok and r == true end
                return false
            end,
        }
        return core, w, ctrl
    end

    -- A fake boxnet API: records sends, exposes peers and trust.
    local function makeBoxnet(me, peers)
        local bn = { sent = {}, broadcasts = {}, subs = {}, gen = 1, trust = true, peersList = peers or {} }
        function bn.available() return true end
        function bn.myName() return me end
        function bn.peers() return bn.peersList end
        function bn.peer(name) for _, p in ipairs(bn.peersList) do if p.name:lower() == name:lower() then return p end end return nil end
        function bn.generation() return bn.gen end
        function bn.trusted() return bn.trust end
        function bn.send(name, kind, data) bn.sent[#bn.sent + 1] = { to = name, kind = kind, data = data } return true end
        function bn.broadcast(kind, data) bn.broadcasts[#bn.broadcasts + 1] = { kind = kind, data = data } return true end
        function bn.command(name, line) bn.sent[#bn.sent + 1] = { to = name, kind = 'cmd', data = line } return true end
        function bn.subscribe(kind, fn) bn.subs[kind] = fn return function() bn.subs[kind] = nil end end
        return bn
    end

    local function loadInv()
        local fn = assert(loadfile('TAC/lua/tac/inventory.lua'))
        local origPrint = print
        print = quietPrint
        local ok, inst = pcall(fn)
        print = origPrint
        assert_true(ok and type(inst) == 'table', 'Suite 108: inventory.lua loads')
        return inst
    end

    local origPrint = print
    print = quietPrint

    -- 1. Codec: describeLocation, pack / unpack round trip, flags
    do
        local inv = loadInv()
        local L = inv.invLogic
        assert_eq(select(2, L.describeLocation('INVENTORY', 3, 4)), 'in pack3 4', 'Suite 108: bag slot notify address')
        assert_eq(L.describeLocation('INVENTORY', 3, 4), 'Bag 3 [Slot 4]', 'Suite 108: bag slot label')
        assert_eq(select(2, L.describeLocation('INVENTORY', 5)), 'pack5', 'Suite 108: loose pack slot address')
        assert_eq(select(2, L.describeLocation('WORN', 13)), '13', 'Suite 108: worn slot address is the slot number')
        assert_eq(L.describeLocation('WORN', 13), 'Worn [Main Hand]', 'Suite 108: worn slot label')
        assert_eq(select(2, L.describeLocation('BANK', 2, 7)), 'in bank2 7', 'Suite 108: bank slot address')
        assert_eq(select(2, L.describeLocation('SHAREDBANK', 1, 2)), 'in sharedbank1 2', 'Suite 108: shared bank slot address')
        assert_eq(select(2, L.describeLocation('CURSOR', 0)), '', 'Suite 108: cursor has no notify address')
        local it = { id = 1001, icon = 500, name = 'Peridot', location = 'INVENTORY', slotIndex = 2, subSlot = 5, count = 7, stackable = true,
            stackSize = 20, weight = 0.1, value = 1000, type = 'Gem', category = 'Gem', lore = false, nodrop = false, tradeskill = true,
            magic = true, clicky = nil, augs = { { slot = 1, name = 'Aug A' }, { slot = 2, name = 'Aug B' } } }
        local p = L.packItem(it)
        assert_eq(#p, 15, 'Suite 108: packed item has 15 fields')
        assert_eq(p[4], 'I', 'Suite 108: location packs to a code')
        assert_eq(p[13], L.FLAG.tradeskill + L.FLAG.stackable + L.FLAG.magic, 'Suite 108: flags pack to a bit set')
        assert_eq(p[15], 'Aug A|Aug B', 'Suite 108: augs pack as |-separated text')
        local u = L.unpackItem(p, 'Bob')
        assert_eq(u.name, 'Peridot', 'Suite 108: unpack keeps the name')
        assert_eq(u.owner, 'Bob', 'Suite 108: unpack tags the owner')
        assert_true(u.remote == true, 'Suite 108: unpacked items are marked remote')
        assert_eq(u.notifyCmd, 'in pack2 5', 'Suite 108: unpack rebuilds the notify address')
        assert_eq(u.displayLocation, 'Bag 2 [Slot 5]', 'Suite 108: unpack rebuilds the label')
        assert_true(u.tradeskill and u.stackable and u.magic and not u.lore and not u.nodrop, 'Suite 108: unpack restores the flags')
        assert_eq(u.qtyText, '7/20', 'Suite 108: unpacked items are decorated for the list')
        assert_eq(#u.augs, 2, 'Suite 108: unpack parses the aug names')
        assert_eq(L.unpackItem(L.packItem({ id = 5, name = 'Sword', location = 'WORN', slotIndex = 13 }), 'X').wornSlot, 'Main Hand', 'Suite 108: worn items keep their slot name')
        assert_nil(L.unpackItem('junk', 'X'), 'Suite 108: unpack rejects non-tables')
        -- Content signature: order-insensitive, changes with counts / slots
        local a = L.contentSignature({ { id = 1, count = 2, notifyCmd = 'in pack1 1' }, { id = 2, count = 1, notifyCmd = 'in pack1 2' } })
        local b = L.contentSignature({ { id = 2, count = 1, notifyCmd = 'in pack1 2' }, { id = 1, count = 2, notifyCmd = 'in pack1 1' } })
        local c = L.contentSignature({ { id = 1, count = 3, notifyCmd = 'in pack1 1' }, { id = 2, count = 1, notifyCmd = 'in pack1 2' } })
        assert_eq(a, b, 'Suite 108: signature ignores scan order')
        assert_neq(a, c, 'Suite 108: signature changes when a stack count changes')
    end

    -- 2. Paging + merge + container rebuild
    do
        local inv = loadInv()
        local L = inv.invLogic
        assert_eq(#L.paginate({}, 3), 1, 'Suite 108: an empty list is one empty page')
        local pages = L.paginate({ 1, 2, 3, 4, 5, 6, 7 }, 3)
        assert_eq(#pages, 3, 'Suite 108: 7 items in pages of 3 -> 3 pages')
        assert_eq(#pages[3], 1, 'Suite 108: the last page holds the remainder')
        local st = {
            items = {
                { id = 1, name = 'A', location = 'INVENTORY', slotIndex = 1, subSlot = 1, count = 1 },
                { id = 2, name = 'B', location = 'INVENTORY', slotIndex = 1, subSlot = 3, count = 1 },
                { id = 3, name = 'C', location = 'BANK', slotIndex = 2, subSlot = 1, count = 1 },
                { id = 4, name = 'D', location = 'INVENTORY', slotIndex = 4, count = 1 },
            },
            containers = {
                inventory = { { slot = 1, name = 'Backpack', capacity = 8, used = 2, slots = {} }, { slot = 4, name = 'D', capacity = 1, used = 1, slots = {} } },
                bank = { { slot = 2, name = 'Bank Bag', capacity = 10, used = 1, slots = {} } },
                sharedBank = {},
            },
            counts = { total = 4, freeInvSlots = 6, totalInvSlots = 9 },
            bankLive = false, bankLastSync = '2026-09-15 10:00:00',
        }
        local snap = L.buildSnapshot(st, 123)
        assert_eq(#snap.items, 4, 'Suite 108: snapshot packs every item')
        assert_eq(snap.meta.counts.freeInvSlots, 6, 'Suite 108: snapshot meta carries the counts')
        assert_eq(#snap.meta.inventory, 2, 'Suite 108: snapshot meta lists the bags')
        assert_nil(snap.meta.inventory[1].slots, 'Suite 108: snapshot bags carry no slot maps')
        assert_eq(snap.meta.bankSync, '2026-09-15 10:00:00', 'Suite 108: snapshot meta carries the bank sync time')
        local pg = L.paginate(snap.items, 3)
        local rec = { name = 'Bob' }
        assert_true(L.mergePage(rec, { gen = 7, page = 2, pages = 2, items = pg[2] }, 50) == false, 'Suite 108: a partial snapshot is not complete')
        assert_nil(rec.items, 'Suite 108: nothing published until every page is in')
        assert_true(L.mergePage(rec, { gen = 7, page = 2, pages = 2, items = pg[2] }, 50) == false, 'Suite 108: a duplicate page is ignored')
        assert_true(L.mergePage(rec, { gen = 7, page = 1, pages = 2, meta = snap.meta, items = pg[1] }, 60) == true, 'Suite 108: the last page completes the snapshot')
        assert_eq(#rec.items, 4, 'Suite 108: pages assemble in order regardless of arrival')
        assert_eq(rec.items[1].name, 'A', 'Suite 108: page 1 items come first')
        assert_eq(rec.at, 60, 'Suite 108: completion time recorded')
        assert_eq(rec.gen, 7, 'Suite 108: snapshot generation recorded')
        assert_nil(rec.partial, 'Suite 108: partial buffer cleared')
        assert_eq(rec.containers.inventory[1].slots[3].name, 'B', 'Suite 108: bag slot maps rebuilt from the items')
        assert_eq(rec.containers.inventory[2].slots[1].name, 'D', 'Suite 108: a loose pack item fills its 1-slot container')
        assert_eq(rec.containers.bank[1].slots[1].name, 'C', 'Suite 108: bank slot maps rebuilt too')
        -- A newer generation restarts the assembly
        assert_true(L.mergePage(rec, { gen = 8, page = 1, pages = 2, items = {} }, 70) == false, 'Suite 108: a new generation starts over')
        assert_eq(rec.partial.gen, 8, 'Suite 108: partial tracks the new generation')
        assert_eq(#rec.items, 4, 'Suite 108: the complete older snapshot stays until the new one completes')
    end

    -- 3. Box search / sort, give blockers, distance
    do
        local inv = loadInv()
        local L = inv.invLogic
        local items = {
            { owner = 'Zed', name = 'Peridot', location = 'INVENTORY', notifyCmd = 'in pack1 1', displayLocation = 'Bag 1' },
            { owner = 'Amy', name = 'Peridot', location = 'BANK', notifyCmd = 'in bank1 1', displayLocation = 'Bank 1' },
            { owner = 'Amy', name = 'Sword', location = 'WORN', notifyCmd = '13', displayLocation = 'Worn' },
            { owner = 'Amy', name = 'Pearl', location = 'SHAREDBANK', notifyCmd = 'in sharedbank1 1', displayLocation = 'Shared' },
        }
        local rows = L.filterBoxItems(items, 'peridot', 'ALL', 'ALL')
        assert_eq(#rows, 2, 'Suite 108: search matches across owners')
        assert_eq(rows[1].owner .. '/' .. rows[2].owner, 'Amy/Zed', 'Suite 108: rows sort by owner')
        assert_eq(#L.filterBoxItems(items, '', 'BANK', 'ALL'), 2, 'Suite 108: Bank filter includes the shared bank')
        assert_eq(#L.filterBoxItems(items, '', 'ALL', 'amy'), 3, 'Suite 108: owner filter is case-insensitive')
        assert_eq(#L.filterBoxItems(items, '', 'WORN', 'zed'), 0, 'Suite 108: owner + location combine')
        assert_nil(L.giveBlocker({ id = 1, location = 'INVENTORY' }), 'Suite 108: a bag item can be given')
        assert_eq(L.giveBlocker({ id = 1, location = 'INVENTORY', nodrop = true }), 'NO TRADE item', 'Suite 108: NO TRADE blocks a give')
        assert_true(L.giveBlocker({ id = 1, location = 'BANK' }) ~= nil, 'Suite 108: bank items cannot be given directly')
        assert_true(L.giveBlocker({ id = 1, location = 'SHAREDBANK' }) ~= nil, 'Suite 108: shared bank items cannot be given directly')
        assert_true(L.giveBlocker({ id = 0, location = 'INVENTORY' }) ~= nil, 'Suite 108: unknown ids cannot be given')
        assert_eq(L.dist3({ x = 0, y = 0, z = 0 }, { x = 3, y = 4, z = 0 }), 5, 'Suite 108: dist3')
        assert_nil(L.dist3({ x = 0 }, { x = 1, y = 1 }), 'Suite 108: dist3 needs both positions')
    end

    -- 4. Give workflow on the scripted client: happy path
    do
        local core, w, ctrl = makeWorld()
        local inv = loadInv()
        local bn = makeBoxnet('Giver', { { name = 'Taker', hb = { zone = 'poknowledge', x = 5, y = 0, z = 0 } } })
        rawset(core, 'boxnet', bn)
        inv.onInit(core)
        inv.scanner.scanAll = function() inv.state.lastScanTime = os.time() end
        inv.probe.locate = function(id, cmd) return { cmd = cmd, name = 'Peridot', count = 5, stackable = true, nodrop = false } end
        w.spawns.Taker = { id = 77, dist = 8 }
        -- The world reacts to each command as the game would.
        w.onDelay = function()
            local last = w.cmds[#w.cmds] or ''
            if last:find('/itemnotify', 1, true) then w.cursorId = 1001
            elseif last:find('/target id 77', 1, true) then w.targetId = 77
            elseif last == '/click left target' then w.tradeOpen = true
            elseif last:find('TRDW_Trade_Button', 1, true) then w.tradeOpen = false w.cursorId = 0 end
        end
        local it = { id = 1001, name = 'Peridot', location = 'INVENTORY', notifyCmd = 'in pack1 1', count = 5, stackable = true }
        local ok, why = inv.net.requestGive(it, 'Taker')
        assert_true(ok, 'Suite 108: a local give is queued (' .. tostring(why) .. ')')
        assert_eq(#inv.state.net.gives, 1, 'Suite 108: give job in the queue')
        assert_true(inv.net.requestGive(it, 'Giver') == false, 'Suite 108: cannot give to yourself')
        inv.net.processGives()
        assert_eq(#inv.state.net.gives, 0, 'Suite 108: the queue drains')
        local joined = table.concat(w.cmds, '\n')
        assert_true(joined:find('/shiftkey /itemnotify in pack1 1 leftmouseup', 1, true) ~= nil, 'Suite 108: whole stack picked up with shift')
        assert_true(joined:find('/target id 77', 1, true) ~= nil, 'Suite 108: receiver targeted by spawn id')
        assert_true(joined:find('/click left target', 1, true) ~= nil, 'Suite 108: trade opened with /click left target')
        assert_true(joined:find('/notify TradeWnd TRDW_Trade_Button leftmouseup', 1, true) ~= nil, 'Suite 108: giver clicks Trade')
        assert_true(joined:find('/autoinventory', 1, true) == nil, 'Suite 108: nothing to clean up after a good trade')
        local accept = nil
        for _, m in ipairs(bn.sent) do if m.kind == 'inv:trade_accept' then accept = m end end
        assert_true(accept ~= nil and accept.to == 'Taker' and accept.data.name == 'Peridot', 'Suite 108: receiver told to accept the trade')
        assert_true(inv.state.net.log[1].text:find('Gave Peridot to Taker', 1, true) ~= nil, 'Suite 108: success logged')
        -- Cursor-occupied guard on the next job
        w.cursorId = 500
        inv.net.enqueueGive({ itemId = 1001, notifyCmd = 'in pack1 1', name = 'Peridot', to = 'Taker' })
        inv.net.processGives()
        assert_true(inv.state.net.log[1].text:find('cursor is already holding', 1, true) ~= nil, 'Suite 108: a busy cursor refuses the give')
        w.cursorId = 0
        -- Out of range
        w.spawns.Taker.dist = 40
        inv.net.enqueueGive({ itemId = 1001, notifyCmd = 'in pack1 1', name = 'Peridot', to = 'Taker' })
        inv.net.processGives()
        assert_true(inv.state.net.log[1].text:find('trade range', 1, true) ~= nil, 'Suite 108: out of range refuses the give')
        -- Not in zone
        w.spawns.Taker = nil
        inv.net.enqueueGive({ itemId = 1001, notifyCmd = 'in pack1 1', name = 'Peridot', to = 'Taker' })
        inv.net.processGives()
        assert_true(inv.state.net.log[1].text:find('not in this zone', 1, true) ~= nil, 'Suite 108: a receiver in another zone refuses the give')
    end

    -- 5. Give workflow: receiver never accepts -> cancel + autoinventory; partial quantity
    do
        local core, w = makeWorld()
        local inv = loadInv()
        local bn = makeBoxnet('Giver', { { name = 'Taker', hb = { zone = 'poknowledge' } } })
        rawset(core, 'boxnet', bn)
        inv.onInit(core)
        inv.scanner.scanAll = function() inv.state.lastScanTime = os.time() end
        inv.probe.locate = function(id, cmd) return { cmd = cmd, name = 'Peridot', count = 5, stackable = true, nodrop = false } end
        w.spawns.Taker = { id = 77, dist = 3 }
        w.onDelay = function()
            local last = w.cmds[#w.cmds] or ''
            if last:find('/itemnotify', 1, true) then w.cursorId = 1001
            elseif last:find('/target id 77', 1, true) then w.targetId = 77
            elseif last == '/click left target' then w.tradeOpen = true
            elseif last:find('TRDW_Cancel_Button', 1, true) then w.tradeOpen = false
            elseif last == '/autoinventory' then w.cursorId = 0 end
        end
        inv.net.enqueueGive({ itemId = 1001, notifyCmd = 'in pack1 1', name = 'Peridot', to = 'Taker', count = 2, requestedBy = 'Boss' })
        inv.net.processGives()
        local joined = table.concat(w.cmds, '\n')
        assert_true(joined:find('/nomodkey /itemnotify in pack1 1 leftmouseup', 1, true) ~= nil, 'Suite 108: a partial quantity uses the quantity dialog')
        assert_true(joined:find('TRDW_Cancel_Button', 1, true) ~= nil, 'Suite 108: an unaccepted trade is cancelled')
        assert_true(joined:find('/autoinventory', 1, true) ~= nil, 'Suite 108: the item goes back to the bags')
        assert_true(inv.state.net.log[1].text:find('did not accept', 1, true) ~= nil, 'Suite 108: failure reason logged')
        local res = nil
        for _, m in ipairs(bn.sent) do if m.kind == 'inv:give_result' then res = m end end
        assert_true(res ~= nil and res.to == 'Boss' and res.data.ok == false, 'Suite 108: the remote requester gets the failure')
        -- Single item uses ctrl
        w.tradeOpen = false
        w.onDelay = function()
            local last = w.cmds[#w.cmds] or ''
            if last:find('/itemnotify', 1, true) then w.cursorId = 1001
            elseif last:find('/target id 77', 1, true) then w.targetId = 77
            elseif last == '/click left target' then w.tradeOpen = true
            elseif last:find('TRDW_Trade_Button', 1, true) then w.tradeOpen = false w.cursorId = 0 end
        end
        w.cmds = {}
        inv.net.enqueueGive({ itemId = 1001, notifyCmd = 'in pack1 1', name = 'Peridot', to = 'Taker', count = 1 })
        inv.net.processGives()
        assert_true(table.concat(w.cmds, '\n'):find('/ctrlkey /itemnotify in pack1 1 leftmouseup', 1, true) ~= nil, 'Suite 108: one item picked up with ctrl')
        -- NO TRADE seen on the live item
        inv.probe.locate = function(id, cmd) return { cmd = cmd, name = 'Soulbound', count = 1, stackable = false, nodrop = true } end
        inv.net.enqueueGive({ itemId = 1002, notifyCmd = 'in pack1 2', name = 'Soulbound', to = 'Taker' })
        inv.net.processGives()
        assert_true(inv.state.net.log[1].text:find('NO TRADE', 1, true) ~= nil, 'Suite 108: the live NO TRADE flag stops the give')
        assert_eq(#bn.broadcasts, 0, 'Suite 108: no change hint before anyone asked for our snapshot')
    end

    -- 6. Message handlers: request -> pages, give (trusted / untrusted), trade accept, result, changed
    do
        local core, w, ctrl = makeWorld()
        local inv = loadInv()
        local bn = makeBoxnet('Giver', { { name = 'Taker', hb = { zone = 'poknowledge' } }, { name = 'Boss', hb = { zone = 'poknowledge' } } })
        rawset(core, 'boxnet', bn)
        inv.onInit(core)
        inv.scanner.scanAll = function()
            inv.state.lastScanTime = os.time()
            inv.state.items = {}
            for i = 1, 170 do inv.state.items[i] = { id = i, name = 'Item ' .. i, location = 'INVENTORY', slotIndex = 1, subSlot = i, count = 1 } end
            inv.state.contentGen = 3
        end
        inv.net.ensureSubscriptions()
        assert_true(bn.subs['inv:request'] ~= nil and bn.subs['inv:give'] ~= nil and bn.subs['inv:page'] ~= nil, 'Suite 108: handlers subscribed')
        bn.subs['inv:request']({ want = 'all' }, { character = 'Boss' })
        bn.subs['inv:request']({ want = 'all' }, { character = 'Boss' })
        assert_eq(#inv.state.net.pendingRequests, 2, 'Suite 108: requests queue for the tick')
        inv.net.serveRequests()
        local pages = {}
        for _, m in ipairs(bn.sent) do if m.kind == 'inv:page' then pages[#pages + 1] = m end end
        assert_eq(#pages, 3, 'Suite 108: 170 items -> 3 pages (duplicate request served once)')
        assert_true(pages[1].data.meta ~= nil and pages[2].data.meta == nil, 'Suite 108: only the first page carries meta')
        assert_eq(pages[1].data.pages, 3, 'Suite 108: pages announce the total')
        assert_eq(pages[3].to, 'Boss', 'Suite 108: pages go to the asker')
        assert_eq(#pages[3].data.items, 10, 'Suite 108: the last page holds the remainder')
        assert_true(inv.state.net.served.boss == true, 'Suite 108: the asker is remembered for change hints')
        inv.state.contentGen = 4
        inv.net.announceChanged()
        assert_eq(#bn.broadcasts, 1, 'Suite 108: a content change is announced once someone asked')
        inv.net.announceChanged()
        assert_eq(#bn.broadcasts, 1, 'Suite 108: the same generation is not announced twice')
        -- Sharing off refuses
        inv.cfg.share = false
        bn.sent = {}
        bn.subs['inv:request']({}, { character = 'Boss' })
        inv.net.serveRequests()
        assert_true(bn.sent[1].kind == 'inv:page' and bn.sent[1].data.refused == true, 'Suite 108: sharing off answers with a refusal')
        inv.cfg.share = true
        -- Pages arriving from a peer assemble into its record
        local snapItems = {}
        for i = 1, 5 do snapItems[i] = inv.invLogic.packItem({ id = 100 + i, name = 'Gem ' .. i, location = 'INVENTORY', slotIndex = 1, subSlot = i, count = 1 }) end
        bn.subs['inv:page']({ gen = 1, page = 1, pages = 1, meta = { counts = { freeInvSlots = 3 }, inventory = { { slot = 1, name = 'Bag', capacity = 8, used = 5 } } }, items = snapItems }, { character = 'Taker' })
        local rec = inv.state.net.peers.taker
        assert_true(rec ~= nil and #rec.items == 5, 'Suite 108: a peer page lands in its record')
        assert_eq(rec.containers.inventory[1].slots[2].name, 'Gem 2', 'Suite 108: peer bag grid rebuilt')
        assert_eq(#inv.net.allBoxItems(), 175, 'Suite 108: All boxes lists mine plus the peer snapshot')
        assert_eq(inv.net.allBoxItems()[1].owner, 'Giver', 'Suite 108: my rows are tagged with my name')
        -- Refused page
        bn.subs['inv:page']({ refused = true, reason = 'sharing is off on Boss' }, { character = 'Boss' })
        assert_eq(inv.state.net.peers.boss.refused, 'sharing is off on Boss', 'Suite 108: a refusal is recorded on the peer')
        -- Changed hint marks the snapshot stale
        bn.subs['inv:changed']({ gen = 2 }, { character = 'Taker' })
        assert_true(rec.stale == true, 'Suite 108: a change hint marks the snapshot stale')
        -- Remote give request: trusted -> queued; untrusted -> refused with a result
        bn.subs['inv:give']({ itemId = 101, notifyCmd = 'in pack1 1', name = 'Gem 1', to = 'Taker' }, { character = 'Boss' })
        assert_eq(#inv.state.net.gives, 1, 'Suite 108: a trusted give request is queued')
        assert_eq(inv.state.net.gives[1].requestedBy, 'Boss', 'Suite 108: the requester is remembered')
        bn.trust = false
        bn.sent = {}
        bn.subs['inv:give']({ itemId = 101, notifyCmd = 'in pack1 1', name = 'Gem 1', to = 'Taker' }, { character = 'Boss' })
        assert_eq(#inv.state.net.gives, 1, 'Suite 108: an untrusted give request is not queued')
        assert_true(bn.sent[1].kind == 'inv:give_result' and bn.sent[1].data.ok == false and bn.sent[1].data.reason == 'not trusted', 'Suite 108: untrusted requester gets a refusal')
        bn.trust = true
        inv.cfg.acceptGives = false
        bn.sent = {}
        bn.subs['inv:give']({ itemId = 101, notifyCmd = 'in pack1 1', name = 'Gem 1', to = 'Taker' }, { character = 'Boss' })
        assert_true(bn.sent[1].data.reason:find('gives are off', 1, true) ~= nil, 'Suite 108: the Accept Gives switch refuses')
        inv.cfg.acceptGives = true
        -- Asking a remote owner to give sends inv:give to that box
        bn.sent = {}
        local okR, whyR = inv.net.requestGive({ id = 101, name = 'Gem 1', location = 'INVENTORY', notifyCmd = 'in pack1 1', owner = 'Taker' }, 'Boss')
        assert_true(okR, 'Suite 108: a remote give is sent (' .. tostring(whyR) .. ')')
        assert_true(bn.sent[1].kind == 'inv:give' and bn.sent[1].to == 'Taker' and bn.sent[1].data.to == 'Boss', 'Suite 108: the owner box is asked to give to the receiver')
        assert_true(inv.net.requestGive({ id = 101, name = 'Gem 1', location = 'INVENTORY', notifyCmd = 'in pack1 1', owner = 'Taker' }, 'Taker') == false, 'Suite 108: giving a box its own item is refused')
        -- Give result from a remote giver
        bn.subs['inv:give_result']({ ok = true, name = 'Gem 1', to = 'Boss' }, { character = 'Taker' })
        assert_true(inv.state.net.log[1].text:find('Taker gave Gem 1 to Boss', 1, true) ~= nil, 'Suite 108: a remote result is logged')
        -- Trade accept: click Trade once the giver's window shows their name, then log the receipt
        bn.subs['inv:trade_accept']({ name = 'Gem 1' }, { character = 'Taker' })
        w.cmds = {}
        inv.net.processTradeAccepts()
        assert_eq(#w.cmds, 0, 'Suite 108: no Trade click while no trade window is open')
        w.tradeOpen = true
        w.hisName = 'Someone'
        inv.net.processTradeAccepts()
        assert_eq(#w.cmds, 0, 'Suite 108: a trade from someone else is left alone')
        w.hisName = 'Taker'
        inv.net.processTradeAccepts()
        assert_eq(w.cmds[1], '/notify TradeWnd TRDW_Trade_Button leftmouseup', 'Suite 108: the expected giver\'s trade is accepted')
        inv.net.processTradeAccepts()
        assert_eq(#w.cmds, 1, 'Suite 108: Trade is not clicked again within a second')
        w.tradeOpen = false
        inv.net.processTradeAccepts()
        assert_true(inv.state.net.acceptTrades.taker == nil, 'Suite 108: the accept entry clears when the window closes')
        assert_true(inv.state.net.log[1].text:find('Received Gem 1 from Taker', 1, true) ~= nil, 'Suite 108: receipt logged')
        -- Expiry
        bn.subs['inv:trade_accept']({ name = 'Gem 2' }, { character = 'Taker' })
        w.nowMs = w.nowMs + 60000
        inv.net.processTradeAccepts()
        assert_true(inv.state.net.acceptTrades.taker == nil, 'Suite 108: an accept that never saw a trade expires')
        -- Re-subscribe on a boxnet reload; destroy unsubscribes
        bn.gen = 2
        inv.net.ensureSubscriptions()
        assert_true(bn.subs['inv:request'] ~= nil, 'Suite 108: subscriptions renewed after a boxnet reload')
        inv.onDestroy()
        assert_true(bn.subs['inv:request'] == nil, 'Suite 108: destroy drops the subscriptions')
    end

    -- 7. Settings round-trip, commands, and no plugin / no network degrade
    do
        local core, w, ctrl = makeWorld()
        local inv = loadInv()
        inv.onInit(core)
        inv.state.autoScan = true
        inv.state.autoScanInterval = 20
        inv.cfg.share = false
        inv.cfg.tradeRange = 12
        inv.cfg.autoRefreshSec = 45
        local saved = inv.onSaveSettings()
        assert_true(saved.autoScan == true and saved.autoScanInterval == 20 and saved.share == false and saved.tradeRange == 12 and saved.autoRefreshSec == 45 and saved.acceptGives == true,
            'Suite 108: settings save')
        inv.onLoadSettings({ autoScan = false, autoScanInterval = 999, share = true, acceptGives = false, tradeRange = 1, autoRefreshSec = -5, announce = false })
        assert_true(inv.state.autoScan == false and inv.state.autoScanInterval == 60 and inv.cfg.share == true and inv.cfg.acceptGives == false
            and inv.cfg.tradeRange == 5 and inv.cfg.autoRefreshSec == 0 and inv.cfg.announce == false, 'Suite 108: settings load and clamp')
        inv.cfg.acceptGives = true
        -- Without boxnet: tick runs, gives refuse cleanly, tab degrades
        inv.scanner.scanAll = function() inv.state.lastScanTime = os.time() end
        inv.onTick()
        local ok, why = inv.net.requestGive({ id = 1, name = 'X', location = 'INVENTORY', notifyCmd = 'in pack1 1', owner = 'Other' }, 'Me')
        assert_true(ok == false and why == 'Box Network not connected', 'Suite 108: remote give without boxnet is refused')
        -- Commands
        local bn = makeBoxnet('Tester', { { name = 'Taker', hb = { zone = 'z' } } })
        rawset(core, 'boxnet', bn)
        inv.state.items = { { id = 55, name = 'Peridot', location = 'INVENTORY', notifyCmd = 'in pack1 1', displayLocation = 'Bag 1 [Slot 1]', count = 3, stackable = true },
                            { id = 56, name = 'Pearl', location = 'INVENTORY', notifyCmd = 'in pack1 2', displayLocation = 'Bag 1 [Slot 2]', count = 1 },
                            { id = 57, name = 'Peridot Ring', location = 'BANK', notifyCmd = 'in bank1 1', displayLocation = 'Bank 1 [Slot 1]', count = 1 } }
        inv.state.lastScanTime = os.time()
        assert_true(inv.onCommand('inv', { 'inv', 'give', 'Taker', 'pearl' }), 'Suite 108: /ac inv give handled')
        assert_eq(#inv.state.net.gives, 1, 'Suite 108: /ac inv give queues the item by name')
        assert_eq(inv.state.net.gives[1].itemId, 56, 'Suite 108: name match picks the right item')
        inv.onCommand('inv', { 'inv', 'give', 'Taker', 'peridot', '2' })
        assert_eq(#inv.state.net.gives, 2, 'Suite 108: exact name wins over a longer partial match')
        assert_eq(inv.state.net.gives[2].count, 2, 'Suite 108: trailing number is the quantity')
        printed = {}
        inv.onCommand('inv', { 'inv', 'give', 'Taker', 'pe' })
        assert_eq(#inv.state.net.gives, 2, 'Suite 108: an ambiguous name queues nothing')
        assert_true(printed[#printed]:find('items match', 1, true) ~= nil, 'Suite 108: ambiguity is explained')
        inv.onCommand('inv', { 'inv', 'give', 'Taker', '55' })
        assert_eq(inv.state.net.gives[3].itemId, 55, 'Suite 108: give by item id')
        assert_true(inv.onCommand('inv', { 'inv', 'refresh' }), 'Suite 108: /ac inv refresh handled')
        assert_true(bn.sent[1] ~= nil and bn.sent[1].kind == 'inv:request', 'Suite 108: refresh asks the boxes')
        printed = {}
        assert_true(inv.onCommand('inv', { 'inv', 'find', 'peridot' }), 'Suite 108: /ac inv find handled')
        assert_true(printed[1]:find('2 match', 1, true) ~= nil, 'Suite 108: find counts matches across boxes')
        local shown = ctrl.show_inv
        assert_true(inv.onCommand('inv', { 'inv' }), 'Suite 108: bare /ac inv still toggles the window')
        assert_eq(ctrl.show_inv, not shown, 'Suite 108: window toggled')
        assert_true(inv.onCommand('dps', { 'dps' }) == false, 'Suite 108: other commands ignored')
        -- Boxnet exposes the trust check the give handler relies on
        local bsrc = readFile('TAC/lua/tac/boxnet.lua')
        assert_true(bsrc:find('function api.trusted(sender, payload)', 1, true) ~= nil, 'Suite 108: boxnet publishes api.trusted')
        local isrc = readFile('TAC/lua/tac/inventory.lua')
        assert_true(isrc:find('mq.delay(', 1, true) == nil, 'Suite 108: the give workflow never blocks the core with mq.delay')
        assert_true(select(2, isrc:gsub('UI%.drawBagGrid%(', '')) >= 5, 'Suite 108: one bag grid renderer serves bags, bank, shared bank and peers')
        assert_true(isrc:find("BeginTabItem(\"Box Inventories##tabBoxes\")", 1, true) ~= nil, 'Suite 108: the Box Inventories tab is registered')
    end

    print = origPrint
end


-- ============================================================================
-- Suite 109: NMS Loot plugin (tac/nmsloot.lua) -- reply parsing, #nms line
-- building, /ac nms argument parsing, reply capture window, Box Network
-- state sharing / remote requests / trust, settings round-trip.
-- ============================================================================
print('--- Suite 109: NMS Loot plugin ---')
do
    local printed = {}
    local quietPrint = function(...) printed[#printed + 1] = table.concat({ ... }, ' ') end
    local noop = function() end
    local passthrough = function(_, v) return v end
    local mockImGui = setmetatable({
        Checkbox = passthrough, Button = function() return false end, SmallButton = function() return false end,
        IsItemHovered = function() return false end, BeginTable = function() return false end,
        Begin = function() return false, false end, BeginPopupContextWindow = function() return false end,
        SliderInt = function(_, v) return v, false end, InputTextWithHint = function(_, _, v) return v, false end,
        BeginCombo = function() return false end, CollapsingHeader = function() return false end,
    }, { __index = function() return function() end end })

    local function makeWorld(me)
        local w = { cmds = {}, events = {}, saves = 0, nowMs = 100000, wall = 1000 }
        local mq = {
            event = function(name, pattern, fn) w.events[name] = fn end,
            unevent = function(name) w.events[name] = nil end,
            cmd = function(c) w.cmds[#w.cmds + 1] = c end,
            cmdf = function(f, ...) w.cmds[#w.cmds + 1] = string.format(f, ...) end,
            gettime = function() return w.nowMs end,
            TLO = { Me = { CleanName = function() return me end } },
        }
        local ctrl = { plugins = {} }
        local core = {
            VERSION = '3.1', ctrl = ctrl, mq = mq, ImGui = mockImGui, runtime = {}, DATA = {},
            colors = { GOLD = { 1, 1, 1, 1 }, ARC = { 1, 1, 1, 1 }, MUTED = { 1, 1, 1, 1 }, GOOD = { 1, 1, 1, 1 }, WARN = { 1, 1, 1, 1 }, ERR = { 1, 1, 1, 1 } },
            px = function(n) return n end, pushTheme = noop, popTheme = noop, accent = noop, setTooltip = noop,
            preBeginWindow = noop, postBeginWindow = noop,
            saveLoadout = function() w.saves = w.saves + 1 end,
        }
        return core, w, ctrl
    end

    local function makeBoxnet(me, peers)
        local bn = { sent = {}, broadcasts = {}, subs = {}, gen = 1, trust = true, peersList = peers or {} }
        function bn.available() return true end
        function bn.myName() return me end
        function bn.peers() return bn.peersList end
        function bn.peer(name) for _, p in ipairs(bn.peersList) do if p.name:lower() == tostring(name):lower() then return p end end return nil end
        function bn.generation() return bn.gen end
        function bn.trusted() return bn.trust end
        function bn.send(name, kind, data) bn.sent[#bn.sent + 1] = { to = name, kind = kind, data = data } return true end
        function bn.broadcast(kind, data) bn.broadcasts[#bn.broadcasts + 1] = { kind = kind, data = data } return true end
        function bn.subscribe(kind, fn) bn.subs[kind] = fn return function() bn.subs[kind] = nil end end
        return bn
    end

    local function loadNms()
        local fn = assert(loadfile('TAC/lua/tac/nmsloot.lua'))
        local origPrint = print
        print = quietPrint
        local ok, inst = pcall(fn)
        print = origPrint
        assert_true(ok and type(inst) == 'table', 'Suite 109: nmsloot.lua loads')
        return inst
    end

    local LINK = string.char(18)
    local function itemLink(name) return LINK .. string.rep('0', 77) .. name .. LINK end

    local origPrint = print
    print = quietPrint

    -- 1. Pure parsing: looter lines
    do
        local nms = loadNms()
        local L = nms.logic
        assert_eq(L.parseLooter('The active looter is Bob.'), 'Bob', 'Suite 109: "looter is Name"')
        assert_eq(L.parseLooter('Active looter: Bob'), 'Bob', 'Suite 109: "looter: Name"')
        assert_eq(L.parseLooter('Bob is now the active looter.'), 'Bob', 'Suite 109: "Name is now the active looter"')
        assert_eq(L.parseLooter('Bob has claimed the active looter slot.'), 'Bob', 'Suite 109: "Name has claimed"')
        assert_eq(L.parseLooter('Bob already has the active looter slot.'), 'Bob', 'Suite 109: claim refused names the holder')
        assert_eq(L.parseLooter('The active looter slot is now held by Bob.'), 'Bob', 'Suite 109: "held by Name"')
        assert_eq(L.parseLooter('You are now the active looter.'), 'You', 'Suite 109: "You are now" is this character')
        assert_eq(L.parseLooter('You claimed the active looter slot.'), 'You', 'Suite 109: "You claimed" is this character')
        assert_eq(L.parseLooter('The active looter slot is now yours.'), 'You', 'Suite 109: "yours" is this character')
        assert_eq(L.parseLooter('No one is the active looter.'), '', 'Suite 109: "No one" is nobody')
        assert_eq(L.parseLooter('There is no active looter.'), '', 'Suite 109: "no active looter" is nobody')
        assert_eq(L.parseLooter('Bob is no longer the active looter.'), '', 'Suite 109: "no longer" empties the slot')
        assert_nil(L.parseLooter('Bob is not the active looter.'), 'Suite 109: a negated name-first line says nothing')
        assert_nil(L.parseLooter('You are not the active looter.'), 'Suite 109: a negated You line says nothing')
        assert_eq(L.parseLooter('You are not the active looter, the active looter is Bob.'), 'Bob', 'Suite 109: a negated line still trusts "looter is Name"')
        assert_nil(L.parseLooter('Only the active looter can loot that.'), 'Suite 109: a hint line says nothing')
        assert_nil(L.parseLooter('Bob tells you, hello'), 'Suite 109: no "looter" no event')
        assert_eq(L.parseLooter('Active looter: you.'), 'You', 'Suite 109: the real status reply (lowercase you)')
        assert_eq(L.parseLooter('Active looter: none.'), '', 'Suite 109: "looter: none"')
        assert_eq(L.parseLooter('Active looter: Bob.'), 'Bob', 'Suite 109: "looter: Name."')
        -- echo
        assert_eq(L.parseEcho('Loot echo is now on.'), true, 'Suite 109: echo on')
        assert_eq(L.parseEcho('Loot echo is now off.'), false, 'Suite 109: echo off')
        assert_eq(L.parseEcho('Loot offers will be echoed to chat: enabled'), true, 'Suite 109: echo enabled')
        assert_nil(L.parseEcho('The echo of your footsteps'), 'Suite 109: echo without loot is ignored')
        assert_eq(L.parseEcho('Loot echo on. Each offer prints one line per item.'), true, 'Suite 109: the real echo-on reply')
        assert_eq(L.parseEcho('Loot echo off.'), false, 'Suite 109: the real echo-off reply')
        assert_nil(L.parseEcho('#nms echo on|off - print each loot offer to chat'), 'Suite 109: the usage line is not a state')
        -- offers
        local n, q = L.parseOffer('Offered: [Rusty Sword] x3')
        assert_eq(n, 'Rusty Sword', 'Suite 109: bracketed item name')
        assert_eq(q, 3, 'Suite 109: quantity from xN')
        n, q = L.parseOffer('1. Peridot (x5)')
        assert_eq(n, 'Peridot', 'Suite 109: numbered list name without the quantity')
        assert_eq(q, 5, 'Suite 109: quantity from (xN)')
        n = L.parseOffer('Fine Steel Dagger', { 'Fine Steel Dagger' })
        assert_eq(n, 'Fine Steel Dagger', 'Suite 109: link name wins')
        assert_nil(L.parseOffer('Nothing here'), 'Suite 109: no name no offer')
        -- parseLine
        local ev = L.parseLine('Loot offered to you: ' .. itemLink('Rusty Sword') .. ' x2')
        assert_nil(ev, 'Suite 109: a loose line with a link is no longer an offer (the server has an exact format)')
        ev = L.parseLine('Bob tells the group, \'loot [Guild] rules?\'')
        assert_nil(ev, 'Suite 109: player chat with brackets is not an offer')
        ev = L.parseLine('2. Peridot x1', 'list')
        assert_true(ev and ev.kind == 'offer' and ev.name == 'Peridot', 'Suite 109: numbered lines are offers while a list reply is open')
        ev = L.parseLine('2. Peridot x1', nil)
        assert_nil(ev, 'Suite 109: numbered lines outside a list reply are ignored')
        assert_nil(L.parseLine('[MQ2Nav] Navigating to loot at 12, 34'), 'Suite 109: another script\'s [Tag] line is not an offer')
        assert_nil(L.parseLine('Offered: [Guild] loot rules'), 'Suite 109: a bracketed word is not an offer')
        assert_nil(L.parseLine('[NMS] Offered: [Rusty Sword] x2'), 'Suite 109: a server line that is not the offer format is not an offer')
        -- the auto-loot rules acting on an item
        ev = L.parseLine('[NMS Loot] sold "Rusty Sword" x1 for 12 gold')
        assert_true(ev and ev.kind == 'resolved' and ev.name == 'Rusty Sword', 'Suite 109: an auto-sold line resolves the item, never offers it')
        ev = L.parseLine('[NMS Loot] offer 1748 kept ' .. itemLink('Peridot'))
        assert_true(ev and ev.kind == 'resolved' and ev.handle == '1748' and ev.name == 'Peridot', 'Suite 109: a handled line with a handle')
        ev = L.parseLine('[NMS Loot] banked ' .. itemLink('Peridot'))
        assert_true(ev and ev.kind == 'resolved' and ev.name == 'Peridot', 'Suite 109: a banked line resolves the item')
        ev = L.parseLine('[NMS] Ruby Crown sold for 200 platinum.')
        assert_true(ev and ev.kind == 'resolved' and ev.name == 'Ruby Crown', 'Suite 109: the real auto-sell line')
        ev = L.parseLine("[NMS] Part of Yaeth's Compendium Pg. 63 sold for 3 platinum, 7 gold.")
        assert_true(ev and ev.kind == 'resolved' and ev.name == "Part of Yaeth's Compendium Pg. 63", 'Suite 109: a punctuated name before "sold for"')
        ev = L.parseLine('[NMS] Ethereal Mist Vambraces (Enchanted) sold for 1 platinum, 7 gold.')
        assert_true(ev and ev.kind == 'resolved' and ev.name == 'Ethereal Mist Vambraces (Enchanted)', 'Suite 109: a tiered name before "sold for"')
        assert_nil(L.parseLine('Luck is with you! ' .. itemLink('Ethereal Mist Vambraces') .. ' has become ' .. itemLink('Ethereal Mist Vambraces (Enchanted)') .. '.'), 'Suite 109: the enchant line is neither an offer nor a resolution')
        assert_nil(L.parseLine('You receive 2 gold, 1 silver, 1 copper.'), 'Suite 109: coin lines are ignored')
        ev = L.parseLine('You keep ' .. itemLink('Rusty Sword') .. '.')
        assert_true(ev and ev.kind == 'resolved' and ev.name == 'Rusty Sword', 'Suite 109: linked resolution line')
        ev = L.parseLine('You sold Rusty Sword.')
        assert_true(ev and ev.kind == 'resolved' and ev.name == 'Rusty Sword', 'Suite 109: plain resolution line takes the rest of the sentence')
        ev = L.parseLine('Nothing is offered to you.')
        assert_true(ev and ev.kind == 'empty', 'Suite 109: empty list line')
        ev = L.parseLine('The active looter is Bob.')
        assert_true(ev and ev.kind == 'looter' and ev.name == 'Bob', 'Suite 109: looter line event')
        ev = L.parseLine('Loot echo is now on.')
        assert_true(ev and ev.kind == 'echo' and ev.on == true, 'Suite 109: echo line event')
        -- the [NMS] prefix and the usage text
        ev = L.parseLine('[NMS] Active looter: you.')
        assert_true(ev and ev.kind == 'looter' and ev.name == 'You' and ev.server == true, 'Suite 109: prefixed status reply is a server looter event')
        ev = L.parseLine('[NMS] Offers waiting: 2 (5 items).')
        assert_true(ev and ev.kind == 'count' and ev.offers == 2 and ev.items == 5, 'Suite 109: offers-waiting count')
        ev = L.parseLine('[NMS] Offers waiting: 0 (0 items).')
        assert_true(ev and ev.kind == 'count' and ev.offers == 0, 'Suite 109: zero offers waiting')
        ev = L.parseLine('[NMS] Loot echo on. Each offer prints one line per item.')
        assert_true(ev and ev.kind == 'echo' and ev.on == true, 'Suite 109: prefixed echo on')
        ev = L.parseLine('[NMS Loot] offer 1748 slot 65535 id 12428 qty 1 "Iksar Bandit Mask"')
        assert_true(ev and ev.kind == 'offer' and ev.name == 'Iksar Bandit Mask' and ev.handle == '1748' and ev.itemId == 12428 and ev.qty == 1 and ev.slot == 65535 and ev.server == true,
            'Suite 109: the real list line: handle, item id, qty, quoted name')
        assert_eq(L.nmsLine({ sub = 'loot', action = 'keep', item = ev.name, handle = ev.handle }), 'loot keep "Iksar Bandit Mask" 1748', 'Suite 109: the row\'s handle goes on the loot line')
        for _, u in ipairs({ 'Usage:', '#nms claim - claim the active looter slot', '#nms status - who holds it, and what you may loot',
            '#nms echo on|off - print each loot offer to chat', '#nms list [handle] - list what is offered to you',
            '#nms loot <action> "item name" [handle]', '#nms loot coin [handle] - take the coin',
            'actions: keep, sell, tribute, bank, vault, destroy, pass <player>' }) do
            assert_nil(L.parseLine(u), 'Suite 109: usage text yields no event: ' .. u)
        end
    end

    -- 2. #nms line building and /ac nms argument parsing
    do
        local nms = loadNms()
        local L = nms.logic
        assert_eq(L.nmsLine({ sub = 'claim' }), 'claim', 'Suite 109: claim line')
        assert_eq(L.nmsLine({ sub = 'STATUS' }), 'status', 'Suite 109: sub-commands are case-insensitive')
        assert_eq(L.nmsLine({ sub = 'echo', on = true }), 'echo on', 'Suite 109: echo on line')
        assert_eq(L.nmsLine({ sub = 'echo', on = false }), 'echo off', 'Suite 109: echo off line')
        assert_nil(L.nmsLine({ sub = 'echo' }), 'Suite 109: echo without on/off is refused')
        assert_eq(L.nmsLine({ sub = 'loot', action = 'keep', item = 'Rusty Sword' }), 'loot keep "Rusty Sword"', 'Suite 109: loot line quotes the item')
        assert_eq(L.nmsLine({ sub = 'loot', action = 'sell', item = '"Peri"dot"' }), 'loot sell "Peridot"', 'Suite 109: quotes inside the item name are stripped')
        assert_nil(L.nmsLine({ sub = 'loot', action = 'steal', item = 'X' }), 'Suite 109: unknown loot action refused')
        assert_nil(L.nmsLine({ sub = 'loot', action = 'keep', item = '' }), 'Suite 109: empty item refused')
        assert_nil(L.nmsLine({ sub = 'zone', item = 'x' }), 'Suite 109: unknown sub-command refused')
        assert_nil(L.nmsLine({ sub = 'claim; #zone x' }), 'Suite 109: no smuggling through the sub-command')
        assert_eq(L.nmsLine({ sub = 'list', handle = 'c12' }), 'list c12', 'Suite 109: list with a handle')
        assert_eq(L.nmsLine({ sub = 'loot', action = 'keep', item = 'Peridot', handle = 'c12' }), 'loot keep "Peridot" c12', 'Suite 109: loot with a handle')
        assert_nil(L.nmsLine({ sub = 'loot', action = 'keep', item = 'Peridot', handle = 'x; #zone' }), 'Suite 109: a handle is one word')
        assert_eq(L.nmsLine({ sub = 'loot', action = 'coin' }), 'loot coin', 'Suite 109: take the coin')
        assert_eq(L.nmsLine({ sub = 'loot', action = 'coin', handle = 'c12' }), 'loot coin c12', 'Suite 109: take the coin of one offer')
        assert_eq(L.nmsLine({ sub = 'loot', action = 'pass', item = 'Peridot', player = 'Bob' }), 'loot pass Bob "Peridot"', 'Suite 109: pass names the player')
        assert_nil(L.nmsLine({ sub = 'loot', action = 'pass', item = 'Peridot' }), 'Suite 109: pass without a player is refused')

        local function isPeer(n) return n == 'Bob' end
        local spec = L.parseArgs({ 'nms' }, isPeer)
        assert_eq(spec.sub, 'window', 'Suite 109: bare /ac nms is the window toggle')
        spec = L.parseArgs({ 'nms', 'claim' }, isPeer)
        assert_true(spec.sub == 'claim' and spec.target == nil, 'Suite 109: /ac nms claim is local')
        spec = L.parseArgs({ 'nms', 'claim', 'Bob' }, isPeer)
        assert_true(spec.sub == 'claim' and spec.target == nil, 'Suite 109: a trailing word after claim is ignored (target goes first)')
        spec = L.parseArgs({ 'nms', 'Bob', 'claim' }, isPeer)
        assert_true(spec.sub == 'claim' and spec.target == 'Bob', 'Suite 109: /ac nms Bob claim targets the box')
        spec = L.parseArgs({ 'nms', 'Bob' }, isPeer)
        assert_true(spec.sub == 'status' and spec.target == 'Bob', 'Suite 109: /ac nms Bob asks that box for status')
        spec = L.parseArgs({ 'nms', 'loot', 'keep', 'Rusty', 'Sword' }, isPeer)
        assert_true(spec.sub == 'loot' and spec.action == 'keep' and spec.item == 'Rusty Sword', 'Suite 109: item name rejoined from words')
        spec = L.parseArgs({ 'nms', 'loot', 'keep', '"Rusty Sword"' }, isPeer)
        assert_eq(spec.item, 'Rusty Sword', 'Suite 109: quotes stripped from the item')
        spec = L.parseArgs({ 'nms', 'keep', 'Peridot' }, isPeer)
        assert_true(spec.sub == 'loot' and spec.action == 'keep' and spec.item == 'Peridot', 'Suite 109: /ac nms keep X shorthand')
        spec = L.parseArgs({ 'nms', 'Bob', 'loot', 'sell', 'Peridot' }, isPeer)
        assert_true(spec.target == 'Bob' and spec.action == 'sell', 'Suite 109: remote loot action')
        spec = L.parseArgs({ 'nms', 'echo', 'on' }, isPeer)
        assert_true(spec.sub == 'echo' and spec.on == true, 'Suite 109: echo on parsed')
        spec = L.parseArgs({ 'nms', 'echo', 'off' }, isPeer)
        assert_true(spec.sub == 'echo' and spec.on == false, 'Suite 109: echo off parsed')
        local bad, why = L.parseArgs({ 'nms', 'echo' }, isPeer)
        assert_true(bad == nil and why:find('usage', 1, true) ~= nil, 'Suite 109: echo without on/off gives usage')
        bad, why = L.parseArgs({ 'nms', 'Sam', 'claim' }, isPeer)
        assert_true(bad == nil and why:find('not a box', 1, true) ~= nil, 'Suite 109: unknown box is explained')
        bad = L.parseArgs({ 'nms', 'loot', 'keep' }, isPeer)
        assert_nil(bad, 'Suite 109: loot without an item is refused')
        spec = L.parseArgs({ 'nms', 'me', 'claim' }, isPeer)
        assert_true(spec.sub == 'claim' and spec.target == nil, 'Suite 109: "me" is this box')
        spec = L.parseArgs({ 'nms', 'list', 'Bob' }, isPeer)
        assert_true(spec.sub == 'list' and spec.target == 'Bob', 'Suite 109: /ac nms list Bob targets the box')
        spec = L.parseArgs({ 'nms', 'list', 'c12' }, isPeer)
        assert_true(spec.sub == 'list' and spec.handle == 'c12', 'Suite 109: /ac nms list <handle>')
        spec = L.parseArgs({ 'nms', 'loot', 'keep', '"Rusty Sword"', 'c12' }, isPeer)
        assert_true(spec.item == 'Rusty Sword' and spec.handle == 'c12', 'Suite 109: a handle after the quoted item')
        spec = L.parseArgs({ 'nms', 'loot', 'pass', 'Bob', 'Rusty', 'Sword' }, isPeer)
        assert_true(spec.action == 'pass' and spec.player == 'Bob' and spec.item == 'Rusty Sword', 'Suite 109: pass takes the player first')
        assert_nil(L.parseArgs({ 'nms', 'loot', 'pass', '"Rusty Sword"' }, isPeer), 'Suite 109: pass without a player is refused')
        spec = L.parseArgs({ 'nms', 'loot', 'coin' }, isPeer)
        assert_true(spec.action == 'coin' and spec.handle == nil, 'Suite 109: loot coin')
        spec = L.parseArgs({ 'nms', 'coin', 'c12' }, isPeer)
        assert_true(spec.action == 'coin' and spec.handle == 'c12', 'Suite 109: coin shorthand with a handle')
        assert_eq(L.parseArgs({ 'nms', 'compact' }, isPeer).sub, 'compact', 'Suite 109: /ac nms compact')
        assert_eq(L.parseArgs({ 'nms', 'mini' }, isPeer).sub, 'compact', 'Suite 109: mini is compact')
        assert_eq(L.parseArgs({ 'nms', 'full' }, isPeer).sub, 'full', 'Suite 109: /ac nms full')
    end

    -- 3. Live flow: send, capture window, belief, boxnet sharing
    do
        local core, w, ctrl = makeWorld('Tank')
        local bn = makeBoxnet('Tank', { { name = 'Bob' }, { name = 'Sam' } })
        core.boxnet = bn
        local nms = loadNms()
        nms.clock = function() return w.nowMs / 1000 end
        nms.wallClock = function() return w.wall end
        nms.onInit(core)
        assert_eq(ctrl.show_nmsloot, false, 'Suite 109: window flag seeded')
        assert_true(w.events.TacNmsLootAll ~= nil, 'Suite 109: catch-all chat event registered')
        assert_true(bn.subs['nmsloot:state'] and bn.subs['nmsloot:who'] and bn.subs['nmsloot:run'], 'Suite 109: boxnet subscriptions in place')

        -- first tick: status query (statusOnInit) and a who broadcast
        nms.tick()
        assert_eq(w.cmds[1], '/say #nms status', 'Suite 109: one #nms status on the first tick')
        assert_true(bn.broadcasts[1] and bn.broadcasts[1].kind == 'nmsloot:who', 'Suite 109: asks the boxes what they know')
        assert_true(nms.state.pending ~= nil and nms.state.pending.spec.sub == 'status', 'Suite 109: a reply window is open')

        -- server replies: we are the looter (the real reply wording)
        w.events.TacNmsLootAll('[NMS] Active looter: you.')
        assert_eq(nms.state.looter, 'Tank', 'Suite 109: "You" resolves to this character')
        w.events.TacNmsLootAll('[NMS] Offers waiting: 0 (0 items).')
        assert_eq(nms.state.offerCount, 0, 'Suite 109: offer count from the status reply')
        assert_eq(nms.state.wantList, false, 'Suite 109: nothing waiting, no list')
        assert_eq(nms.state.looterFrom, 'server', 'Suite 109: source is the server')
        assert_true(nms.state.net.dirty, 'Suite 109: a change marks the state dirty')
        -- our own announce line must not be re-parsed
        w.events.TacNmsLootAll('[Triune NMS] Active looter is now Bob.')
        assert_eq(nms.state.looter, 'Tank', 'Suite 109: own tagged prints are skipped')
        w.events.TacNmsLootAll("You say, '#nms status'")
        assert_eq(nms.state.looter, 'Tank', 'Suite 109: the echoed say line is skipped')
        w.events.TacNmsLootAll('[MQ2Nav] Navigating to loot ' .. itemLink('Rusty Sword'))
        assert_eq(#nms.state.offers, 0, 'Suite 109: MQ2Nav output is skipped even with a link in it')
        w.events.TacNmsLootAll('[MQ2Nav] The active looter is Bob')
        assert_eq(nms.state.looter, 'Tank', 'Suite 109: MQ2Nav output never sets the looter')

        -- reply window closes after CAPTURE_SEC and the state is broadcast
        w.nowMs = w.nowMs + 2500
        bn.broadcasts = {}
        nms.tick()
        assert_nil(nms.state.pending, 'Suite 109: reply window closed')
        assert_true(bn.broadcasts[1] and bn.broadcasts[1].kind == 'nmsloot:state', 'Suite 109: state broadcast after the reply window')
        assert_eq(bn.broadcasts[1].data.looter, 'Tank', 'Suite 109: broadcast names the holder')
        assert_eq(bn.broadcasts[1].data.known, true, 'Suite 109: broadcast says the holder is known')
        assert_eq(bn.broadcasts[1].data.asOf, 1000, 'Suite 109: broadcast carries the server-confirmed time')

        -- a peer reports a newer claim: adopt it
        w.wall = 1010
        bn.subs['nmsloot:state']({ looter = 'Bob', known = true, asOf = 1010, echo = true, offers = { { n = 'Peridot', q = 2 } }, at = 1010 }, { character = 'Bob' })
        assert_eq(nms.state.looter, 'Bob', 'Suite 109: a newer peer report is adopted')
        assert_eq(nms.state.looterFrom, 'Bob', 'Suite 109: source is the peer')
        assert_eq(nms.state.peers.bob.offers[1].name, 'Peridot', 'Suite 109: the peer\'s offers are kept')
        assert_eq(nms.state.peers.bob.echo, true, 'Suite 109: the peer\'s echo state is kept')
        -- an older peer report does not override
        bn.subs['nmsloot:state']({ looter = 'Sam', known = true, asOf = 900, offers = {}, at = 900 }, { character = 'Sam' })
        assert_eq(nms.state.looter, 'Bob', 'Suite 109: an older report is ignored')
        assert_eq(nms.state.peers.sam.looter, 'Sam', 'Suite 109: ...but the peer row remembers what Sam thinks')
        -- a server line always wins
        w.wall = 1020
        w.events.TacNmsLootAll('The active looter is Sam.')
        assert_eq(nms.state.looter, 'Sam', 'Suite 109: server line adopted')
        assert_eq(nms.state.looterAsOf, 1020, 'Suite 109: server line stamps the time')
        w.events.TacNmsLootAll('No one holds the active looter slot.')
        assert_eq(nms.state.looter, '', 'Suite 109: nobody')

        -- who request from a peer answers with our state (rate limited)
        bn.broadcasts = {}
        bn.subs['nmsloot:who']({}, { character = 'Bob' })
        assert_true(bn.broadcasts[1] and bn.broadcasts[1].kind == 'nmsloot:state', 'Suite 109: who is answered with a state broadcast')
        bn.subs['nmsloot:who']({}, { character = 'Sam' })
        assert_eq(#bn.broadcasts, 1, 'Suite 109: a second who inside the window is not answered again')

        -- a status that reports offers waiting fetches the list by itself
        w.cmds = {}
        nms.runOn(nil, { sub = 'status' })
        w.events.TacNmsLootAll('[NMS] Active looter: you.')
        w.events.TacNmsLootAll('[NMS] Offers waiting: 1 (2 items).')
        assert_eq(nms.state.offerCount, 1, 'Suite 109: offers waiting counted')
        assert_eq(nms.state.itemCount, 2, 'Suite 109: items counted')
        assert_true(nms.state.wantList, 'Suite 109: a list is wanted')
        w.nowMs = w.nowMs + 2500
        nms.tick()
        assert_eq(w.cmds[2], '/say #nms list', 'Suite 109: the list is sent once the status reply window closes')
        assert_eq(nms.state.wantList, false, 'Suite 109: list wanted only once')
        w.nowMs = w.nowMs + 2500
        nms.tick()
        -- list: numbered lines inside the window become the offers
        w.cmds = {}
        assert_true(nms.runOn(nil, { sub = 'list' }), 'Suite 109: local list sent')
        assert_eq(w.cmds[1], '/say #nms list', 'Suite 109: list line')
        w.events.TacNmsLootAll('[NMS] Offers waiting: 1 (3 items).')
        w.events.TacNmsLootAll('[NMS Loot] offer 1748 slot 65535 id 12428 qty 1 "Rusty Sword"')
        w.events.TacNmsLootAll('[NMS Loot] offer 1748 slot 65534 id 1001 qty 3 "Peridot"')
        w.events.TacNmsLootAll('2. Fine Steel Dagger x1')
        assert_eq(#nms.state.offers, 0, 'Suite 109: offers replace the list only when the reply window closes')
        w.nowMs = w.nowMs + 2500
        nms.tick()
        assert_eq(#nms.state.offers, 3, 'Suite 109: three offers listed')
        assert_eq(nms.state.offers[1].name, 'Rusty Sword', 'Suite 109: quoted item name')
        assert_eq(nms.state.offers[1].handle, '1748', 'Suite 109: offer handle kept')
        assert_eq(nms.state.offers[1].itemId, 12428, 'Suite 109: item id kept')
        assert_eq(nms.state.offers[2].qty, 3, 'Suite 109: quantity kept')
        assert_eq(nms.state.offers[3].name, 'Fine Steel Dagger', 'Suite 109: a numbered line inside the list reply still counts')
        assert_eq(nms.state.wantList, false, 'Suite 109: the count inside a list reply does not queue another list')
        nms.state.offers[3] = nil
        -- echo offer outside a window adds; resolution removes
        w.events.TacNmsLootAll('[NMS Loot] offer 1750 slot 65535 id 5 qty 1 "Fine Steel Dagger"')
        assert_eq(#nms.state.offers, 3, 'Suite 109: an echoed offer is added')
        assert_eq(nms.state.offers[3].handle, '1750', 'Suite 109: echoed offer keeps its handle')
        w.events.TacNmsLootAll('[NMS Loot] sold "Rusty Sword" x1 for 3 platinum')
        assert_eq(#nms.state.offers, 2, 'Suite 109: an auto-sold item leaves the list')
        w.events.TacNmsLootAll('[NMS Loot] sold "Something Else" x1 for 3 platinum')
        assert_eq(#nms.state.offers, 2, 'Suite 109: ...and adds nothing')
        w.events.TacNmsLootAll('[NMS Loot] offer 1749 slot 65535 id 7 qty 1 "Rusty Sword"')
        assert_eq(#nms.state.offers, 3, 'Suite 109: a fresh offer of the same item is its own row')
        w.events.TacNmsLootAll('[NMS Loot] offer 1749 kept')
        assert_eq(#nms.state.offers, 2, 'Suite 109: a handled line with only the handle removes that row')
        w.events.TacNmsLootAll('[NMS Loot] offer 1750 slot 65535 id 5 qty 1 "Fine Steel Dagger"')
        assert_eq(#nms.state.offers, 2, 'Suite 109: the same offer twice is one row')
        assert_true(bn.broadcasts ~= nil, 'Suite 109: (state sharing continues)')
        local payload = nms.statePayload()
        assert_eq(payload.offers[2].h, '1750', 'Suite 109: handles travel to the other boxes')
        w.events.TacNmsLootAll('Loot echo is now on.')
        assert_eq(nms.state.echo, true, 'Suite 109: echo state from the server')

        -- loot action locally and remotely
        w.cmds = {}
        nms.runOn(nil, { sub = 'loot', action = 'keep', item = 'Peridot' })
        assert_eq(w.cmds[1], '/say #nms loot keep "Peridot"', 'Suite 109: local loot action')
        bn.sent = {}
        local ok = nms.runOn('bob', { sub = 'claim' })
        assert_true(ok, 'Suite 109: remote claim sent')
        assert_true(bn.sent[1].to == 'Bob' and bn.sent[1].kind == 'nmsloot:run' and bn.sent[1].data.sub == 'claim', 'Suite 109: remote claim addressed by the roster name')
        local okX, whyX = nms.runOn('Nobody', { sub = 'claim' })
        assert_true(okX == false and whyX:find('not on the Box Network', 1, true) ~= nil, 'Suite 109: unknown box refused')
        okX, whyX = nms.runOn('Bob', { sub = 'loot', action = 'eat', item = 'x' })
        assert_true(okX == false, 'Suite 109: a bad spec is refused before sending')

        -- incoming run request: trusted -> typed; untrusted / off -> refused with a reason
        w.cmds = {}
        nms.state.pending = nil
        bn.subs['nmsloot:run']({ sub = 'claim' }, { character = 'Bob' })
        assert_eq(w.cmds[1], '/say #nms claim', 'Suite 109: a trusted peer\'s claim request is typed')
        assert_eq(nms.state.pending.from, 'Bob', 'Suite 109: the reply window remembers who asked')
        w.cmds = {}
        bn.subs['nmsloot:run']({ sub = 'loot', action = 'keep', item = 'Peridot' }, { character = 'Bob' })
        assert_eq(w.cmds[1], '/say #nms loot keep "Peridot"', 'Suite 109: a remote loot request is typed')
        w.cmds = {}
        bn.subs['nmsloot:run']({ sub = 'zone', item = 'x' }, { character = 'Bob' })
        assert_eq(#w.cmds, 0, 'Suite 109: an unknown sub-command from a peer types nothing')
        bn.sent = {}
        bn.trust = false
        bn.subs['nmsloot:run']({ sub = 'claim' }, { character = 'Bob' })
        assert_eq(#w.cmds, 0, 'Suite 109: an untrusted peer types nothing')
        assert_true(bn.sent[1] and bn.sent[1].kind == 'nmsloot:state' and bn.sent[1].data.refused == 'not trusted', 'Suite 109: the refusal reason goes back')
        bn.trust = true
        nms.cfg.acceptRemote = false
        bn.subs['nmsloot:run']({ sub = 'claim' }, { character = 'Bob' })
        assert_eq(#w.cmds, 0, 'Suite 109: remote requests off types nothing')
        nms.cfg.acceptRemote = true
        -- a refusal from a peer is logged here
        bn.subs['nmsloot:state']({ looter = '', known = false, offers = {}, refused = 'not trusted', at = 1 }, { character = 'Sam' })
        assert_true(nms.state.log[1].text:find('Sam refused', 1, true) ~= nil, 'Suite 109: a peer refusal is logged')

        -- holder re-broadcast
        w.wall = 2000
        w.events.TacNmsLootAll('You are the active looter.')
        w.nowMs = w.nowMs + 3000
        nms.state.pending = nil
        nms.tick()
        bn.broadcasts = {}
        w.nowMs = w.nowMs + 21000
        nms.tick()
        assert_true(bn.broadcasts[1] and bn.broadcasts[1].data.looter == 'Tank', 'Suite 109: the holder re-announces itself')

        -- boxnet reload re-subscribes
        bn.gen = 2
        bn.subs = {}
        nms.tick()
        assert_true(bn.subs['nmsloot:state'] ~= nil, 'Suite 109: re-subscribed after a boxnet reload')

        -- settings
        local saved = nms.onSaveSettings()
        assert_true(saved.announce == true and saved.statusOnInit == true and saved.acceptRemote == true and saved.pollSec == 0, 'Suite 109: settings saved')
        nms.onLoadSettings({ announce = false, pollSec = 30, statusOnInit = false })
        assert_true(nms.cfg.announce == false and nms.cfg.pollSec == 30 and nms.cfg.statusOnInit == false, 'Suite 109: settings loaded')
        nms.onLoadSettings({ pollSec = 9999 })
        assert_eq(nms.cfg.pollSec, 300, 'Suite 109: poll interval clamped')
        -- poll sends status on schedule
        w.cmds = {}
        nms.state.pending = nil
        nms.cfg.pollSec = 10
        w.nowMs = w.nowMs + 11000
        nms.tick()
        assert_eq(w.cmds[1], '/say #nms status', 'Suite 109: periodic status poll')

        -- commands
        w.cmds = {}
        bn.sent = {}
        assert_true(nms.onCommand('nms', { 'nms', 'claim' }), 'Suite 109: /ac nms claim handled')
        assert_eq(w.cmds[#w.cmds], '/say #nms claim', 'Suite 109: /ac nms claim types the claim')
        assert_true(nms.onCommand('nms', { 'nms', 'Bob', 'claim' }), 'Suite 109: /ac nms Bob claim handled')
        assert_true(bn.sent[#bn.sent].to == 'Bob' and bn.sent[#bn.sent].data.sub == 'claim', 'Suite 109: remote claim over boxnet')
        nms.onCommand('nms', { 'nms', 'loot', 'sell', 'Rusty', 'Sword' })
        assert_eq(w.cmds[#w.cmds], '/say #nms loot sell "Rusty Sword"', 'Suite 109: /ac nms loot sell types the line')
        nms.onCommand('nms', { 'nms', 'echo', 'off' })
        assert_eq(w.cmds[#w.cmds], '/say #nms echo off', 'Suite 109: /ac nms echo off')
        local shown = ctrl.show_nmsloot
        nms.onCommand('nms', { 'nms' })
        assert_eq(ctrl.show_nmsloot, not shown, 'Suite 109: bare /ac nms toggles the window')
        nms.onCommand('nms', { 'nms', 'compact' })
        assert_true(nms.cfg.compact == true and ctrl.show_nmsloot == true, 'Suite 109: /ac nms compact shows the compact window')
        assert_true(nms.isCompactOpen(), 'Suite 109: the compact layout row reads open')
        nms.setCompactOpen(false)
        assert_eq(ctrl.show_nmsloot, false, 'Suite 109: closing the compact row hides the window')
        nms.onCommand('nms', { 'nms', 'full' })
        assert_true(nms.cfg.compact == false and ctrl.show_nmsloot == true, 'Suite 109: /ac nms full shows the full window')
        assert_eq(nms.onSaveSettings().compact, false, 'Suite 109: compact preference is saved')
        nms.onLoadSettings({ compact = true, compactRows = 99 })
        assert_true(nms.cfg.compact == true and nms.cfg.compactRows == 10, 'Suite 109: compact preference loaded, rows clamped')
        nms.cfg.compact = false
        printed = {}
        nms.onCommand('nms', { 'nms', 'who' })
        assert_true(printed[1] and printed[1]:find('Active looter', 1, true) ~= nil, 'Suite 109: /ac nms who prints the roster')
        assert_true(nms.onCommand('parcels', { 'parcels' }) == false, 'Suite 109: other commands ignored')

        nms.onDestroy()
        assert_nil(w.events.TacNmsLootAll, 'Suite 109: chat event released on destroy')
        assert_nil(bn.subs['nmsloot:state'], 'Suite 109: boxnet subscriptions released on destroy')
    end

    -- 4. Works without boxnet (feature off, nothing crashes)
    do
        local core, w = makeWorld('Solo')
        local nms = loadNms()
        nms.clock = function() return w.nowMs / 1000 end
        nms.onInit(core)
        nms.tick()
        assert_eq(w.cmds[1], '/say #nms status', 'Suite 109: status query without boxnet')
        local ok, why = nms.runOn('Bob', { sub = 'claim' })
        assert_true(ok == false and why:find('Box Network', 1, true) ~= nil, 'Suite 109: remote request without boxnet is explained')
        w.events.TacNmsLootAll('The active looter is Solo.')
        assert_eq(nms.state.looter, 'Solo', 'Suite 109: local parsing still works')
        w.nowMs = w.nowMs + 3000
        nms.tick()
        nms.onDestroy()
    end

    -- 5. Core wiring
    do
        local t = readFile('TAC/lua/triune.lua')
        assert_true(t:find("'nmsloot.lua',", 1, true) ~= nil, 'Suite 109: discover() known-plugin probe lists nmsloot.lua')
        assert_true(t:find('if c.show_nmsloot == nil then c.show_nmsloot = false end', 1, true) ~= nil, 'Suite 109: sanitize seeds show_nmsloot')
        local psrc = readFile('TAC/lua/tac/nmsloot.lua')
        assert_true(psrc:find('mq.delay(', 1, true) == nil, 'Suite 109: the plugin never blocks the core')
        assert_true(psrc:find("mq.cmdf('/say #nms %s', line)", 1, true) ~= nil, 'Suite 109: #nms goes out through /say like every other server command')
        assert_true(select(2, psrc:gsub("mq%.cmdf?%(", '')) == 1, 'Suite 109: nmsLine() is the only way a #nms line is typed')
    end

    print = origPrint
end


-- ============================================================================
-- Suite 110: Mesh isolation recovery -- last-good trail sampling, the
-- no-path / unreachable-burst signals, the island vs unmeshed decision, the
-- recovery ladder (references -> NPC -> maneuvers -> give up), success and
-- interruption bookkeeping, hazard promotion, and the core wiring.
-- ============================================================================
print('--- Suite 110: Mesh isolation recovery ---')
do
    local MESH_ISO = loadstring('return ' .. src:match('pursuit%.MESH_ISO = (%b{})'))()
    local isoInitSrc = src:match('\n    meshIso = (%b{})')
    assert_true(isoInitSrc ~= nil and MESH_ISO.CONFIRM_SECS ~= nil, 'Suite 110: constants and initial state found in source')

    local function makeWorld()
        local w = { cmds = {}, printed = {}, now = 1000, x = 0, y = 0, z = 0, paths = {}, spawns = {},
            combat = false, xtar = false, navActive = false, moveToMoving = false, stickActive = false,
            zone = 'poknowledge', stops = 0, saves = 0, hazards = {} }
        local me = setmetatable({
            X = function() return w.x end, Y = function() return w.y end, Z = function() return w.z end,
            Combat = function() return w.combat end, Sitting = function() return false end,
            Moving = function() return false end,
        }, { __call = function() return true end })
        w.mq = {
            TLO = {
                Me = me,
                Navigation = {
                    PathExists = function(spec) return function() return w.paths[spec] == true end end,
                    Active = function() return w.navActive end,
                    MeshLoaded = function() return true end,
                },
                MoveTo = { Moving = function() return w.moveToMoving end },
                Stick = { Active = function() return w.stickActive end, Status = function() return w.stickActive and 'ON' or 'OFF' end },
                Spawn = function(id) return { Distance = function() local sp = w.spawns[id]; return sp and sp.dist or 9999 end } end,
            },
            cmd = function(c) w.cmds[#w.cmds + 1] = c end,
            cmdf = function(f, ...) w.cmds[#w.cmds + 1] = string.format(f, ...) end,
        }
        w.ctrl = { running = true, mode = 'Puller', submode = 'Hunt', nav_mesh_isolation = true,
            nav_hazard_avoidance = true, nav_hazard_min_hits = 2, nav_hazard_max_hits = 6, nav_hazard_radius = 15 }
        w.pursuit = { meshIso = loadstring('return ' .. isoInitSrc)(), MESH_ISO = MESH_ISO, unreachableIds = {} }
        w.pursuit.meshIso.trailZone = w.zone -- a zone change clears the trail; the tests seed one
        w.rt = {
            getCurrentZoneShortName = function() return w.zone end,
            anyXtarAlive = function() return w.xtar end,
            medBreakActive = false,
            pathExistsCache = { stale = true },
            roamScanEmpty = { at = 1 },
            getZoneHazards = function() return w.hazards end,
            recordStuckHazard = function(x, y, z)
                w.hazards[#w.hazards + 1] = { x = x, y = y, z = z, hits = 1 }
            end,
            saveLoadout = function() w.saves = w.saves + 1 end,
        }
        w.isoH = {}
        w.env = {
            mq = w.mq, ctrl = w.ctrl, pursuit = w.pursuit, runtime = w.rt, isoH = w.isoH,
            navLoaded = function() return true end, navMeshLoaded = function() return true end,
            stickLoaded = function() return true end,
            stopMoving = function() w.stops = w.stops + 1; w.moveToMoving = false; w.stickActive = false end,
            isMoveActive = function() return w.moveToMoving or w.stickActive end,
            isCasting = function() return false end,
            isSpawnAlive = function(id) return w.spawns[id] ~= nil end,
            distToLoc = function(x, y, z) return math.sqrt((w.x - x) ^ 2 + (w.y - y) ^ 2 + (z and (w.z - z) or 0) ^ 2) end,
            distToId = function(id) local sp = w.spawns[id]; return sp and sp.dist or 9999 end,
            os = { clock = function() return w.now end, time = function() return w.now end },
            print = function(...) w.printed[#w.printed + 1] = table.concat({ ... }, ' ') end,
            pcall = pcall,
        }
        w.isoH.MANEUVERS = loadstring('local mq = ...; return ' .. src:match('isoH%.MANEUVERS = (%b{})'))(w.mq)
        for _, n in ipairs({ 'pathExists', 'locSpec', 'dist2D', 'referencePoints', 'refsReachable', 'hasPath',
            'driveToLoc', 'driveToId', 'legStart', 'finish', 'advance', 'run' }) do
            w.isoH[n] = loadFunc(src, n, w.env)
        end
        for _, n in ipairs({ 'sampleGoodMeshPos', 'noteMeshNoPath', 'noteMeshPathOk', 'noteUnreachableBurst',
            'recordMeshHoleHazard', 'checkMeshIsolation' }) do
            w.rt[n] = loadFunc(src, n, w.env)
        end
        w.tick = function(n)
            local r
            for _ = 1, (n or 1) do w.now = w.now + 1; r = w.rt.checkMeshIsolation() end
            return r
        end
        w.sawCmd = function(frag)
            for _, c in ipairs(w.cmds) do if c:find(frag, 1, true) then return true end end
            return false
        end
        w.sawPrint = function(frag)
            for _, p in ipairs(w.printed) do if p:find(frag, 1, true) then return true end end
            return false
        end
        return w
    end

    -- 1. Last-good trail: sampled only while /nav is displacing us, spaced, capped, per zone
    do
        local w = makeWorld()
        local iso = w.pursuit.meshIso
        w.rt.sampleGoodMeshPos()
        assert_eq(#iso.trail, 0, 'Suite 110: nav idle samples nothing')
        w.navActive = true
        w.now = w.now + 3; w.rt.sampleGoodMeshPos()
        assert_eq(#iso.trail, 0, 'Suite 110: first active sample only seeds the displacement check')
        w.x = 10; w.now = w.now + 3; w.rt.sampleGoodMeshPos()
        assert_eq(#iso.trail, 1, 'Suite 110: displacing under active nav records a good point')
        w.x = 15; w.now = w.now + 3; w.rt.sampleGoodMeshPos()
        assert_eq(#iso.trail, 1, 'Suite 110: a point inside TRAIL_SPACING of the head is not added')
        w.x = 40; w.now = w.now + 3; w.rt.sampleGoodMeshPos()
        assert_eq(#iso.trail, 2, 'Suite 110: a point past TRAIL_SPACING is added')
        assert_eq(iso.trail[1].x, 40, 'Suite 110: newest point is first')
        for i = 1, 8 do w.x = 40 + i * 25; w.now = w.now + 3; w.rt.sampleGoodMeshPos() end
        assert_eq(#iso.trail, MESH_ISO.TRAIL_MAX, 'Suite 110: trail is capped at TRAIL_MAX')
        w.now = w.now + 3; w.rt.sampleGoodMeshPos()
        assert_eq(#iso.trail, MESH_ISO.TRAIL_MAX, 'Suite 110: no displacement, no new point')
        w.zone = 'pofire'; w.now = w.now + 3; w.rt.sampleGoodMeshPos()
        assert_eq(#iso.trail, 0, 'Suite 110: zone change clears the trail')
    end

    -- 2. The no-path scan signal and the reference check
    do
        local w = makeWorld()
        local iso = w.pursuit.meshIso
        assert_eq(w.rt.noteMeshNoPath({ count = 2, id = 99, dist = 40, los = true }), false, 'Suite 110: no references -> not on connected mesh')
        assert_eq(iso.noPathSince, w.now, 'Suite 110: first no-path scan starts the clock')
        assert_eq(iso.noPathId, 99, 'Suite 110: nearest no-path NPC remembered')
        local t0 = iso.noPathSince
        w.now = w.now + 1; w.rt.noteMeshNoPath({ count = 2, id = 99, dist = 40, los = true })
        assert_eq(iso.noPathSince, t0, 'Suite 110: a fresh follow-up keeps the clock running')
        w.now = w.now + MESH_ISO.SCAN_STALE + 1; w.rt.noteMeshNoPath({ count = 1, id = 99, dist = 40, los = true })
        assert_eq(iso.noPathSince, w.now, 'Suite 110: a stale gap restarts the clock')
        w.rt.noteMeshPathOk()
        assert_eq(iso.noPathSince, 0, 'Suite 110: a pathable scan clears the signal')

        iso.trail = { { x = 50, y = 0, z = 0, at = 1 } }
        w.paths['loc 0.00 50.00 0.00'] = true
        w.now = w.now + 3
        assert_eq(w.rt.noteMeshNoPath({ count = 1, id = 99, dist = 40, los = true }), true, 'Suite 110: reachable trail point -> we are on the connected mesh')
        assert_eq(iso.refOk, true, 'Suite 110: refOk recorded')
        w.paths['loc 0.00 50.00 0.00'] = nil
        w.now = w.now + 1; w.rt.noteMeshNoPath({ count = 1, id = 99, dist = 40, los = true })
        assert_eq(iso.refOk, true, 'Suite 110: reference check is cached for 2 s')
        w.now = w.now + 2; w.rt.noteMeshNoPath({ count = 1, id = 99, dist = 40, los = true })
        assert_eq(iso.refOk, false, 'Suite 110: unreachable trail point -> island suspicion')
        iso.trail = {}
        w.x = 100; w.y = 100
        w.ctrl.submode = 'Camp'; w.ctrl.camp_loc = { x = 60, y = 100, z = 0 }
        w.paths['loc 100.00 60.00 0.00'] = true
        w.now = w.now + 3; w.rt.noteMeshNoPath({ count = 1, id = 99, dist = 40, los = true })
        assert_eq(iso.refOk, true, 'Suite 110: the camp anchor is a reference too')

        w.ctrl.nav_mesh_isolation = false
        assert_eq(w.rt.noteMeshNoPath({ count = 1, id = 99, dist = 40, los = true }), false, 'Suite 110: disabled: never claims connected mesh')
    end

    -- 3. Unreachable bursts
    do
        local w = makeWorld()
        local iso = w.pursuit.meshIso
        w.spawns[5] = { dist = 30 }
        w.rt.noteUnreachableBurst(5); w.rt.noteUnreachableBurst(5); w.rt.noteUnreachableBurst(5)
        assert_eq(iso.burstPending, false, 'Suite 110: the same spawn repeated is not a burst')
        w.rt.noteUnreachableBurst(6)
        assert_eq(iso.burstPending, false, 'Suite 110: two distinct spawns is not a burst')
        w.rt.noteUnreachableBurst(7)
        assert_eq(iso.burstPending, true, 'Suite 110: three distinct spawns inside the window is a burst')
        assert_eq(iso.noPathId, 5, 'Suite 110: burst supplies a live NPC to test against')
        iso.burstPending = false; iso.recentUnreachable = {}
        w.rt.noteUnreachableBurst(8)
        w.now = w.now + MESH_ISO.BURST_WINDOW + 1
        w.rt.noteUnreachableBurst(9); w.rt.noteUnreachableBurst(10)
        assert_eq(iso.burstPending, false, 'Suite 110: entries older than the window do not count')
    end

    -- 4. Island: detected, walks back to the last good ground, recovers
    do
        local w = makeWorld()
        local iso = w.pursuit.meshIso
        iso.trail = { { x = 50, y = 0, z = 0, at = 1 } }
        w.spawns[99] = { dist = 40 }
        w.pursuit.unreachableIds = { [77] = 5 }
        w.rt.noteMeshNoPath({ count = 2, id = 99, dist = 40, los = false })
        iso.noPathSince = w.now - MESH_ISO.CONFIRM_SECS - 1
        assert_eq(w.tick(), true, 'Suite 110: island confirmed -> recovery running')
        assert_eq(iso.kind, 'island', 'Suite 110: kind is island')
        assert_eq(iso.stage, 1, 'Suite 110: stage 1 walks the references')
        assert_true(w.sawCmd('/moveto loc 0.00 50.00 0.00 mdist 5'), 'Suite 110: /moveto straight at the last good point (Y X Z)')
        assert_true(w.sawPrint('Mesh isolation detected'), 'Suite 110: detection is announced')
        local before = #w.cmds
        w.moveToMoving = true
        w.tick()
        assert_eq(#w.cmds, before, 'Suite 110: /moveto not re-issued while still moving')
        w.x = 20; w.paths['loc 0.00 50.00 0.00'] = true
        assert_eq(w.tick(), false, 'Suite 110: path to known ground again -> recovery done')
        assert_eq(iso.active, false, 'Suite 110: recovery inactive after success')
        assert_eq(next(w.pursuit.unreachableIds), nil, 'Suite 110: unreachable list wiped on success')
        assert_nil(w.rt.pathExistsCache.stale, 'Suite 110: PathExists cache wiped on success')
        assert_nil(w.rt.roamScanEmpty, 'Suite 110: empty-scan cache wiped on success')
        assert_eq(#w.hazards, 1, 'Suite 110: the hole is logged as a hazard')
        assert_eq(w.hazards[1].x, 0, 'Suite 110: hazard sits where the island was entered, not where we ended up')
        assert_eq(w.hazards[1].hits, 2, 'Suite 110: hazard promoted straight to active')
        assert_eq(iso.trail[1].x, 20, 'Suite 110: the recovered spot joins the trail')
        assert_true(iso.lastResult:find('recovered', 1, true) ~= nil, 'Suite 110: result recorded')
        assert_eq(iso.cooldownUntil, w.now + MESH_ISO.OK_COOLDOWN, 'Suite 110: short cooldown after success')
        assert_true(w.stops >= 1, 'Suite 110: movement stopped on finish')
    end

    -- 5. Island suspicion refuted by a reachable reference at confirm time
    do
        local w = makeWorld()
        local iso = w.pursuit.meshIso
        iso.trail = { { x = 50, y = 0, z = 0, at = 1 } }
        w.spawns[99] = { dist = 40 }
        w.rt.noteMeshNoPath({ count = 1, id = 99, dist = 40, los = false })
        iso.noPathSince = w.now - MESH_ISO.CONFIRM_SECS - 1
        w.paths['loc 0.00 50.00 0.00'] = true
        iso.refCheckAt = nil; iso.refOk = false -- pretend the cached check was stale
        assert_eq(w.tick(), false, 'Suite 110: reachable reference -> not isolated')
        assert_eq(iso.active, false, 'Suite 110: no recovery started')
        assert_eq(iso.noPathSince, 0, 'Suite 110: signal reset')
        -- burst with reachable references: it really is the mobs
        iso.burstPending = true; w.now = w.now + 10
        assert_eq(w.tick(), false, 'Suite 110: burst with reachable ground does not start a recovery')
        assert_eq(iso.burstPending, false, 'Suite 110: burst consumed')
    end

    -- 6. The full ladder: stalled leg -> NPC leg -> maneuvers -> give up
    do
        local w = makeWorld()
        local iso = w.pursuit.meshIso
        iso.trail = { { x = 50, y = 0, z = 0, at = 1 } }
        w.spawns[99] = { dist = 40 }
        w.rt.noteMeshNoPath({ count = 1, id = 99, dist = 40, los = false })
        iso.noPathSince = w.now - MESH_ISO.CONFIRM_SECS - 1
        w.tick()
        assert_eq(iso.stage, 1, 'Suite 110: ladder starts at the references')
        w.tick(MESH_ISO.STALL_SECS + 1) -- never displaced
        assert_eq(iso.stage, 2, 'Suite 110: a leg that does not move us is abandoned early')
        assert_true(w.sawCmd('/stick id 99 8'), 'Suite 110: stage 2 sticks at the nearest no-path NPC')
        w.spawns[99] = nil
        w.tick()
        assert_eq(iso.stage, 3, 'Suite 110: NPC gone -> maneuvers')
        assert_eq(iso.maneuverIdx, 1, 'Suite 110: first maneuver')
        assert_true(w.sawCmd('/keypress back hold'), 'Suite 110: first maneuver backs up')
        assert_true(w.sawCmd('/face fast loc 0.00,50.00'), 'Suite 110: faces the best reference before the maneuvers')
        local manCount = #w.isoH.MANEUVERS
        local ticks = 0
        while iso.active and ticks < 3 * manCount + 3 do w.tick(); ticks = ticks + 1 end
        assert_eq(iso.active, false, 'Suite 110: all maneuvers exhausted -> gave up')
        assert_eq(iso.maneuverIdx, manCount + 1, 'Suite 110: every maneuver was tried')
        assert_true(iso.lastResult:find('FAILED', 1, true) ~= nil, 'Suite 110: failure recorded')
        assert_eq(iso.cooldownUntil, w.now + MESH_ISO.FAIL_COOLDOWN, 'Suite 110: long cooldown after failure')
        assert_eq(#w.hazards, 1, 'Suite 110: failed island still logs the hole')
        assert_true(w.sawPrint('recovery FAILED'), 'Suite 110: failure is announced')
        w.rt.noteMeshNoPath({ count = 1, id = 98, dist = 40, los = false })
        iso.noPathSince = w.now - MESH_ISO.CONFIRM_SECS - 1
        assert_eq(w.tick(), false, 'Suite 110: nothing restarts during the cooldown')
    end

    -- 7. Combat interrupts; disabled / Manual never runs
    do
        local w = makeWorld()
        local iso = w.pursuit.meshIso
        iso.trail = { { x = 50, y = 0, z = 0, at = 1 } }
        w.spawns[99] = { dist = 40 }
        w.rt.noteMeshNoPath({ count = 1, id = 99, dist = 40, los = false })
        iso.noPathSince = w.now - MESH_ISO.CONFIRM_SECS - 1
        w.tick()
        assert_eq(iso.active, true, 'Suite 110: recovery running')
        w.xtar = true
        assert_eq(w.tick(), false, 'Suite 110: an XTarget hostile interrupts the recovery')
        assert_eq(iso.lastResult, 'interrupted by combat', 'Suite 110: interruption recorded')
        assert_eq(#w.hazards, 0, 'Suite 110: an interrupted recovery logs no hazard')
        w.xtar = false; w.now = w.now + 10
        w.rt.noteMeshNoPath({ count = 1, id = 99, dist = 40, los = false })
        iso.noPathSince = w.now - MESH_ISO.CONFIRM_SECS - 1
        w.combat = true
        assert_eq(w.tick(), false, 'Suite 110: recovery does not start while in combat')
        w.combat = false
        w.ctrl.mode = 'Manual'
        assert_eq(w.tick(), false, 'Suite 110: Manual mode never recovers')
        w.ctrl.mode = 'Puller'; w.ctrl.nav_mesh_isolation = false
        assert_eq(w.tick(), false, 'Suite 110: disabled never recovers')
        assert_eq(iso.noPathSince, 0, 'Suite 110: disabled clears the signal')
    end

    -- 8. Unmeshed mobs: references reachable for a long while, no maneuvers, no hazard
    do
        local w = makeWorld()
        local iso = w.pursuit.meshIso
        iso.trail = { { x = 50, y = 0, z = 0, at = 1 } }
        w.paths['loc 0.00 50.00 0.00'] = true
        w.spawns[99] = { dist = 70 }
        w.rt.noteMeshNoPath({ count = 1, id = 99, dist = 70, los = false })
        assert_eq(iso.refOk, true, 'Suite 110: unmeshed: references reachable')
        iso.noPathSince = w.now - MESH_ISO.CONFIRM_SECS - 1
        assert_eq(w.tick(), false, 'Suite 110: the short confirm window is only for islands')
        iso.noPathSince = w.now - MESH_ISO.CONFIRM_SECS_SOFT - 1
        assert_eq(w.tick(), true, 'Suite 110: the long window starts an unmeshed recovery')
        assert_eq(iso.kind, 'unmeshed', 'Suite 110: kind is unmeshed')
        assert_eq(iso.stage, 2, 'Suite 110: unmeshed skips the reference legs')
        assert_true(w.sawCmd('/stick id 99 8'), 'Suite 110: unmeshed walks at the NPC')
        w.paths['id 99'] = true
        assert_eq(w.tick(), false, 'Suite 110: NPC pathable again -> done')
        assert_eq(#w.hazards, 0, 'Suite 110: unmeshed success logs no hazard (our ground was fine)')
        -- and its failure
        w.paths['id 99'] = nil; w.now = w.now + MESH_ISO.OK_COOLDOWN + 1
        w.rt.noteMeshNoPath({ count = 1, id = 99, dist = 70, los = false })
        iso.noPathSince = w.now - MESH_ISO.CONFIRM_SECS_SOFT - 1
        w.tick()
        assert_eq(iso.stage, 2, 'Suite 110: unmeshed again')
        w.spawns[99] = nil
        assert_eq(w.tick(), false, 'Suite 110: NPC gone -> unmeshed gives up without maneuvers')
        assert_eq(#w.hazards, 0, 'Suite 110: unmeshed failure logs no hazard')
        assert_true(not w.sawCmd('/keypress back hold'), 'Suite 110: no key maneuvers for unmeshed')
    end

    -- 9. Hazard promotion
    do
        local w = makeWorld()
        w.rt.recordMeshHoleHazard(10, 20, 5)
        assert_eq(w.hazards[1].hits, 2, 'Suite 110: fresh hotspot promoted to min hits')
        assert_eq(w.saves, 1, 'Suite 110: promotion saved')
        w.hazards[1].hits = 5
        w.rt.recordMeshHoleHazard(12, 21, 6)
        assert_eq(w.hazards[1].hits, 5, 'Suite 110: an already-active hotspot is left alone')
        w.ctrl.nav_hazard_avoidance = false
        w.rt.recordMeshHoleHazard(90, 90, 0)
        assert_eq(#w.hazards, 2, 'Suite 110: hazard avoidance off -> nothing logged')
    end

    -- 10. Core wiring
    do
        assert_true(src:find('if runtime.checkMeshIsolation() then return end', 1, true) ~= nil, 'Suite 110: main loop yields to a running recovery')
        assert_true(src:find('if pursuit.meshIso.active then return end', 1, true) ~= nil, 'Suite 110: checkStuck defers to the recovery')
        assert_true(src:find('runtime.noteUnreachableBurst(id)', 1, true) ~= nil, 'Suite 110: markUnreachable feeds the burst signal')
        assert_true(src:find('runtime.noteMeshNoPath(noPath)', 1, true) ~= nil, 'Suite 110: findRoamTarget reports all-no-path scans')
        assert_true(src:find('if c.nav_mesh_isolation == nil then c.nav_mesh_isolation = true end', 1, true) ~= nil, 'Suite 110: sanitize seeds the setting on')
        assert_true(src:find("ImGui.Checkbox('Mesh Isolation Recovery'", 1, true) ~= nil, 'Suite 110: Settings checkbox')
        local roam = src:match('function runtime%.findRoamTarget.-\nend\n')
        assert_true(roam:find('noPath.los and noPath.dist <= pursuit.MESH_ISO.DIRECT_LOS_DIST', 1, true) ~= nil, 'Suite 110: direct approach needs LoS and range')
        assert_true(roam:find('runtime.noteMeshPathOk(); return targetId', 1, true) ~= nil, 'Suite 110: a found target clears the signal')
    end
end

-- ============================================================================
-- Suite 111: Auto AA priorities vs. the cap spender -- live-first cost
-- resolution, the reserve that keeps fireworks from starving a waiting
-- priority, and the AA-window row check before a Train click.
-- ============================================================================
do
    print('--- Suite 111: Auto AA priority purchasing ---')
    local printed = {}
    local quietPrint = function(...) printed[#printed + 1] = table.concat({ ... }, ' ') end

    -- A client with one owned AA line ("Combat Agility" 2/5, next rank costs
    -- 30 via NextIndex) and a fireworks cap spender.
    local function makeWorld(opts)
        opts = opts or {}
        local W = { points = opts.points or 27, cmds = {} }
        local function tlo(members, truthy)
            return setmetatable(members, { __call = function() return truthy ~= false end })
        end
        local nextRank = tlo({ Cost = function() return opts.nextCost or 30 end })
        local owned = {
            ['Combat Agility'] = tlo({
                ID = function() return 101 end, Rank = function() return opts.rank or 2 end,
                MaxRank = function() return 5 end, MinLevel = function() return 51 end,
                Cost = function() return 5 end,           -- the OWNED rank's price
                NextIndex = function() return 102 end,
                CanTrain = function() return opts.canTrain ~= false end,
                Type = function() return 1 end,
            }),
        }
        W.mq = {
            cmdf = function(fmt, ...) W.cmds[#W.cmds + 1] = string.format(fmt, ...) end,
            cmd = function(c) W.cmds[#W.cmds + 1] = c end,
            TLO = {
                Me = {
                    AAPoints = function() return W.points end,
                    AAPointsSpent = function() return 0 end,
                    Level = function() return 60 end,
                    Moving = function() return false end,
                    Combat = function() return false end,
                    CombatState = function() return 'ACTIVE' end,
                    AutoFire = function() return false end,
                    XTHaterCount = function() return 0 end,
                    AltAbility = function(key) return owned[key] or tlo({}, false) end,
                },
                AltAbility = function(key)
                    if key == 102 then return nextRank end
                    return tlo({}, false)
                end,
                Window = function() return tlo({}, false) end,
            },
        }
        W.ctrl = {
            auto_spend_aa = true, auto_spend_aa_threshold = 25, auto_spend_aa_cost = 25,
            auto_spend_aa_name = 'Alternately Advanced Fireworks', auto_spend_aa_id = 17788,
            auto_aa_priorities = opts.priorities or { ['Combat Agility'] = true },
        }
        W.rt = { cachedAAData = opts.cache or {}, isCasting = function() return false end }
        W.core = { ctrl = W.ctrl, runtime = W.rt, mq = W.mq, ImGui = {}, DATA = {}, myClasses = { 'War' },
            saveLoadout = function() end, colors = {} }
        local origPrint = print
        print = quietPrint
        local P = assert(loadfile('TAC/lua/tac/auto_aa.lua'))()
        P.onInit(W.core)
        print = origPrint
        W.P, W.AA = P, P.AA
        return W
    end

    local function run(W)
        local origPrint = print
        print = quietPrint
        W.AA.lastAutoSpendAAAt = -10   -- os.clock() is tiny in the test process
        W.AA.lastPrioEvalAt = nil
        local ok, res = pcall(W.AA.checkAutoSpendAA)
        print = origPrint
        assert_true(ok, 'Suite 111: checkAutoSpendAA runs: ' .. tostring(res))
        return res
    end

    -- 1. Live-first cost: the next rank's price comes from NextIndex, not the
    --    owned rank's Cost, and not a stale cache recorded at the old rank.
    do
        local W = makeWorld({ cache = { ['Combat Agility'] = { rank = 1, maxRank = 5, cost = 5, costRank = 1 } } })
        local info = W.AA.purchaseInfo('Combat Agility')
        assert_eq(info.rank, 2, 'Suite 111: rank read live from the client')
        assert_eq(info.cost, 30, 'Suite 111: next-rank cost probed through NextIndex, stale cache ignored')
        assert_eq(info.fullyTrained, false, 'Suite 111: 2/5 is not fully trained')
        assert_eq(W.AA.cachedCostFor({ cost = 9, costRank = 2 }, 2), 9, 'Suite 111: cached cost recorded at this rank counts')
        assert_eq(W.AA.cachedCostFor({ cost = 9, costRank = 1 }, 2), 0, 'Suite 111: cached cost from the previous rank is stale')
        assert_eq(W.AA.cachedCostFor({ cost = 9, rank = 2 }, 2), 9, 'Suite 111: legacy entry without costRank trusted when its rank matches')
        assert_eq(W.AA.cachedCostFor({ cost = 9, rank = 1 }, 2), 0, 'Suite 111: legacy entry from another rank is stale')
    end

    -- 2. Starvation: 27 unspent, priority needs 30, threshold 25. The old
    --    code let fireworks eat the pool every time it crossed 25.
    do
        local W = makeWorld({ points = 27 })
        assert_eq(run(W), false, 'Suite 111: nothing bought while the priority is short of points')
        assert_eq(W.AA.pendingAATrain, nil, 'Suite 111: cap spender held for the waiting priority')
        assert_eq(W.AA.prioStatus['Combat Agility'].why, 'points', 'Suite 111: priority classified as waiting for points')
        local held = false
        for _, l in ipairs(printed) do if l:find('Cap spender on hold', 1, true) then held = true end end
        assert_true(held, 'Suite 111: the hold is announced once')
        W.points = 30
        assert_eq(run(W), true, 'Suite 111: priority bought once affordable')
        assert_eq(W.AA.pendingAATrain and W.AA.pendingAATrain.name, 'Combat Agility', 'Suite 111: the window trainer targets the priority, not fireworks')
    end

    -- 3. Only checked priorities are bought: a priority that was just
    --    attempted (30 s spacing) keeps the cap spender off even with a
    --    large surplus.
    do
        local W = makeWorld({ points = 60 })
        W.AA.lastObservedAutoSpendPts = 60          -- a changed pool would clear the attempt spacing
        W.AA.lastAATrainAttempt['Combat Agility'] = os.clock()
        assert_eq(run(W), false, 'Suite 111: fireworks held during the priority spacing despite the surplus')
        assert_eq(W.AA.pendingAATrain, nil, 'Suite 111: no cap-spender purchase while a priority is outstanding')
    end

    -- 4. No pending priority: the cap spender behaves as before.
    do
        local W = makeWorld({ points = 27, rank = 5 })
        assert_eq(run(W), true, 'Suite 111: maxed priority does not hold the cap spender')
        assert_eq(W.AA.pendingAATrain and W.AA.pendingAATrain.name, 'Alternately Advanced Fireworks', 'Suite 111: fireworks bought with no priority waiting')
        assert_eq(W.AA.prioStatus['Combat Agility'].why, 'trained', 'Suite 111: maxed priority reported as trained')
    end

    -- 5. Blocked priorities are still outstanding: the cap spender stays off
    --    until they are maxed (or unchecked).
    do
        local W = makeWorld({ points = 40, canTrain = false })
        assert_eq(run(W), false, 'Suite 111: CanTrain=false priority still holds the cap spender')
        assert_eq(W.AA.prioStatus['Combat Agility'].why, 'cantrain', 'Suite 111: CanTrain=false reported')
        local W2 = makeWorld({ points = 27 })
        W2.AA.trainBackoff['Combat Agility'] = os.clock() + 300
        assert_eq(run(W2), false, 'Suite 111: a priority in failure backoff still holds the cap spender')
        local W3 = makeWorld({ points = 27, priorities = {} })
        assert_eq(run(W3), true, 'Suite 111: with nothing checked the cap spender runs')
        assert_eq(W3.AA.pendingAATrain and W3.AA.pendingAATrain.name, 'Alternately Advanced Fireworks', 'Suite 111: fireworks bought with no priorities checked')
    end

    -- 6. The AA-window row is the authority before a Train click.
    do
        local W = makeWorld({ points = 27 })
        local rows = { { 'Combat Agility', '2/5', '30', 'General' } }
        local list = { Items = function() return #rows end, List = function(row, col) return rows[row] and rows[row][col or 1] end }
        local info = W.AA.readRowInfo(list, 1)
        assert_eq(info.name, 'Combat Agility', 'Suite 111: row name read')
        assert_eq(info.rank, 2, 'Suite 111: row rank parsed from cur/max')
        assert_eq(info.maxRank, 5, 'Suite 111: row max rank parsed')
        assert_eq(info.cost, 30, 'Suite 111: row cost parsed')
        W.rt.cachedAAData['Combat Agility'] = { rank = 1, maxRank = 5, cost = 5, costRank = 1 }
        W.AA.applyRowInfo('Combat Agility', info)
        assert_eq(W.rt.cachedAAData['Combat Agility'].cost, 30, 'Suite 111: cache cost refreshed from the row')
        assert_eq(W.rt.cachedAAData['Combat Agility'].costRank, 2, 'Suite 111: cache cost tagged with the row rank')
        assert_eq(W.AA.rowCost['Combat Agility'].cost, 30, 'Suite 111: row price remembered per rank')
        -- A world whose client cannot report the next-rank cost falls back
        -- to the remembered row price rather than the rank+1 guess.
        local W3 = makeWorld({ points = 27 })
        W3.mq.TLO.AltAbility = function() return setmetatable({}, { __call = function() return false end }) end
        assert_eq(W3.AA.purchaseInfo('Combat Agility').cost, 3, 'Suite 111: without a probe or row the rank+1 guess applies')
        W3.AA.rowCost['Combat Agility'] = { rank = 2, cost = 30 }
        assert_eq(W3.AA.purchaseInfo('Combat Agility').cost, 30, 'Suite 111: the remembered row price beats the guess')
    end

    -- 7. Source contract
    assert_true(AA_CONTENT:find("task.skipped = 'points'", 1, true) ~= nil, 'Suite 111: select_item skips the click when the row costs more than the pool')
    assert_true(AA_CONTENT:find("elseif task.skipped then", 1, true) ~= nil, 'Suite 111: a skipped row is not a failure (no 5 minute backoff)')
    assert_true(AA_CONTENT:find("cmd == 'aastatus'", 1, true) ~= nil, 'Suite 111: /ac aastatus command')
end

-- ============================================================================
-- Suite 112: Puller (Hunt) combat anchor -- the circle the puller may not
-- leave. huntAnchor gating, the roam-scan filter, the XTarget pick, the
-- movement leash in moveToward, dropping a target that left the circle, and
-- the idle walk back inside.
-- ============================================================================
print('--- Suite 112: Puller (Hunt) combat anchor ---')
do
    local function makeCtrl(over)
        local c = { mode = 'Puller', submode = 'Hunt', hunter_combat_loc = { x = 0, y = 0, z = 0 },
            hunter_combat_radius = 500, use_waypoints = false, waypoints = {}, combat_style = 'Melee' }
        for k, v in pairs(over or {}) do c[k] = v end
        if c.no_anchor then c.hunter_combat_loc = nil end
        return c
    end

    -- 1. huntAnchor: only Puller / Hunt with an anchor, a radius and no patrol
    local huntAnchor = loadFunc(src, 'huntAnchor', { ctrl = makeCtrl() })
    local a, r = huntAnchor()
    assert_true(a ~= nil and r == 500, 'Suite 112: Puller / Hunt with an anchor and radius is in force')
    assert_nil(loadFunc(src, 'huntAnchor', { ctrl = makeCtrl({ submode = 'Camp' }) })(), 'Suite 112: Camp submode has no hunt anchor')
    assert_nil(loadFunc(src, 'huntAnchor', { ctrl = makeCtrl({ mode = 'Manual' }) })(), 'Suite 112: Manual mode has no hunt anchor')
    assert_nil(loadFunc(src, 'huntAnchor', { ctrl = makeCtrl({ no_anchor = true }) })(), 'Suite 112: no anchor set -> none')
    assert_nil(loadFunc(src, 'huntAnchor', { ctrl = makeCtrl({ hunter_combat_radius = 0 }) })(), 'Suite 112: zero radius -> none')
    assert_nil(loadFunc(src, 'huntAnchor', { ctrl = makeCtrl({ use_waypoints = true, waypoints = { { x = 1, y = 1, z = 0 } } }) })(),
        'Suite 112: Waypoint Patrol overrides the anchor')
    local wpOff = loadFunc(src, 'huntAnchor', { ctrl = makeCtrl({ use_waypoints = false, waypoints = { { x = 1, y = 1, z = 0 } } }) })
    assert_true(wpOff() ~= nil, 'Suite 112: a saved but disabled route leaves the anchor in force')

    -- A small world: me + spawns, wired into the anchor helpers.
    local function makeWorld(over)
        local w = { x = 0, y = 0, spawns = {}, cmds = {}, printed = {}, stops = 0, locMoves = {}, aggro = {},
            navActive = false, paths = nil, sitting = false, now = 1000 }
        w.ctrl = makeCtrl(over)
        w.mq = {
            TLO = {
                Me = { X = function() return w.x end, Y = function() return w.y end, Z = function() return 0 end,
                    Sitting = function() return w.sitting end },
                Navigation = {
                    Active = function() return w.navActive end,
                    PathExists = function(q)
                        return function()
                            if w.paths == nil then return true end
                            return w.paths(q)
                        end
                    end,
                },
                Zone = { ShortName = function() return w.zone or 'gfaydark' end },
                Spawn = function(id)
                    local sp = w.spawns[id]
                    return setmetatable({
                        X = function() return sp and sp.x end, Y = function() return sp and sp.y end,
                        Distance = function()
                            if not sp then return 9999 end
                            return math.sqrt((sp.x - w.x) ^ 2 + (sp.y - w.y) ^ 2)
                        end,
                    }, { __call = function() return sp ~= nil end })
                end,
            },
            cmd = function(c) w.cmds[#w.cmds + 1] = c end,
        }
        local env = {
            ctrl = w.ctrl, mq = w.mq, pcall = pcall, math = math, string = string,
            os = { clock = function() return w.now end, time = os.time },
            print = function(m) w.printed[#w.printed + 1] = m end,
            navLoaded = function() return true end,
            pursuit = { wanderLoc = nil },
            currentZoneShort = function() return w.zone or 'gfaydark' end,
            desiredRange = function() return 14 end,
            distToId = function(id) return w.mq.TLO.Spawn(id).Distance() end,
            stopMoving = function() w.stops = w.stops + 1 end,
            moveTowardLoc = function(x, y, z, d)
                w.locMoves[#w.locMoves + 1] = { x = x, y = y, z = z, d = d }
                return math.sqrt((x - w.x) ^ 2 + (y - w.y) ^ 2) <= d
            end,
        }
        local rt = {}
        env.runtime = rt
        rt.playerHasAggro = function(id) return w.aggro[id] == true end
        rt.ANCHOR_ROAM = loadstring('return ' .. src:match('runtime%.ANCHOR_ROAM = (%b{})'))()
        rt.saveLoadout = function() w.saves = (w.saves or 0) + 1 end
        rt.huntAnchor = loadFunc(src, 'huntAnchor', env)
        rt.anchorAggroException = loadFunc(src, 'anchorAggroException', env)
        rt.anchorRoamTick = loadFunc(src, 'anchorRoamTick', env)
        rt.saveZoneAnchor = loadFunc(src, 'saveZoneAnchor', env)
        rt.loadZoneAnchor = loadFunc(src, 'loadZoneAnchor', env)
        w.pursuit = env.pursuit
        rt.anchorDist = loadFunc(src, 'anchorDist', env)
        rt.anchorRejects = loadFunc(src, 'anchorRejects', env)
        rt.anchorLeashed = loadFunc(src, 'anchorLeashed', env)
        rt.anchorReturnTick = loadFunc(src, 'anchorReturnTick', env)
        rt.moveTowardLoc = env.moveTowardLoc
        w.rt = rt
        return w
    end

    -- 2. anchorDist
    local W = makeWorld()
    assert_eq(W.rt.anchorDist(300, 400), 500, 'Suite 112: anchorDist is the 2D distance to the anchor')
    assert_nil(makeWorld({ no_anchor = true }).rt.anchorDist(1, 1), 'Suite 112: anchorDist is nil without an anchor')

    -- 3. anchorRejects: outside AND beyond reach
    W = makeWorld()
    W.spawns[1] = { x = 200, y = 0 }   -- inside
    W.spawns[2] = { x = 900, y = 0 }   -- outside, far
    W.spawns[3] = { x = 505, y = 0 }   -- just outside, in reach from the edge
    assert_eq(W.rt.anchorRejects(1), false, 'Suite 112: a mob inside the circle is never rejected')
    assert_eq(W.rt.anchorRejects(2), true, 'Suite 112: a mob outside and out of reach is rejected')
    W.x = 498
    assert_eq(W.rt.anchorRejects(3), false, 'Suite 112: a mob just past the edge we can already hit is fair game')
    assert_eq(W.rt.anchorRejects(999), false, 'Suite 112: an unknown spawn is not rejected')
    assert_eq(makeWorld({ no_anchor = true }).rt.anchorRejects(2), false, 'Suite 112: nothing is rejected without an anchor')

    -- 4. anchorLeashed: outside target, stop at the edge
    W = makeWorld()
    W.spawns[2] = { x = 900, y = 0 }
    W.spawns[1] = { x = 200, y = 0 }
    W.x = 100
    assert_eq(W.rt.anchorLeashed(2), false, 'Suite 112: from inside, the approach toward an outside mob is allowed')
    W.x = 492
    assert_eq(W.rt.anchorLeashed(2), true, 'Suite 112: at the edge (inside the margin) the leash holds')
    W.x = 700
    assert_eq(W.rt.anchorLeashed(2), true, 'Suite 112: past the edge the leash holds')
    assert_eq(W.rt.anchorLeashed(1), false, 'Suite 112: a mob inside the circle is never leashed, even from outside')
    local small = makeWorld({ hunter_combat_radius = 20 })
    small.spawns[2] = { x = 60, y = 0 }
    small.x = 17
    assert_eq(small.rt.anchorLeashed(2), false, 'Suite 112: the inner margin scales down with a small radius')
    small.x = 18.5
    assert_eq(small.rt.anchorLeashed(2), true, 'Suite 112: small radius still leashes at its edge')

    -- 5. anchorReturnTick: walk back until half the radius, with hysteresis
    W = makeWorld()
    W.x = 100
    assert_eq(W.rt.anchorReturnTick(), false, 'Suite 112: inside the circle there is nothing to return from')
    assert_eq(#W.locMoves, 0, 'Suite 112: ... and no walk is issued')
    W.x = 650
    assert_eq(W.rt.anchorReturnTick(), true, 'Suite 112: outside the circle the return starts')
    assert_eq(W.rt.anchorReturning, true, 'Suite 112: return flagged in progress')
    assert_eq(W.locMoves[1].d, 250, 'Suite 112: the walk ends half a radius from the anchor')
    assert_true(W.printed[1]:find('150 units outside', 1, true) ~= nil, 'Suite 112: the return announces how far out we were')
    W.x = 400
    assert_eq(W.rt.anchorReturnTick(), true, 'Suite 112: back inside the circle but not yet at half radius -> keep walking')
    assert_eq(#W.printed, 1, 'Suite 112: announced once per trip')
    W.x = 240
    assert_eq(W.rt.anchorReturnTick(), false, 'Suite 112: arrived -> done')
    assert_eq(W.rt.anchorReturning, false, 'Suite 112: return flag cleared on arrival')
    W.ctrl.hunter_combat_loc = nil
    W.rt.anchorReturning = true
    assert_eq(W.rt.anchorReturnTick(), false, 'Suite 112: clearing the anchor cancels a return')
    assert_eq(W.rt.anchorReturning, false, 'Suite 112: ... and drops the flag')

    -- 6. The aggro exception: a mob outside with aggro on us is killed, not leashed
    W = makeWorld()
    W.spawns[2] = { x = 900, y = 0 }
    W.x = 495
    assert_eq(W.rt.anchorRejects(2), true, 'Suite 112: without aggro an outside mob is rejected')
    assert_eq(W.rt.anchorLeashed(2), true, 'Suite 112: ... and the leash holds at the edge')
    W.aggro[2] = true
    assert_eq(W.rt.anchorRejects(2), false, 'Suite 112: a mob with aggro on us is not rejected outside the circle')
    assert_eq(W.rt.anchorLeashed(2), false, 'Suite 112: ... and the leash lets us go and kill it')
    W.spawns[1] = { x = 200, y = 0 }
    W.aggro[1] = true
    assert_eq(W.rt.anchorRejects(1), false, 'Suite 112: aggro inside the circle changes nothing')

    -- 7. Idle roam inside the circle
    W = makeWorld()
    W.x, W.y = 100, 0
    assert_eq(W.rt.anchorRoamTick(), true, 'Suite 112: idle inside the circle starts a roam leg')
    local leg = W.pursuit.wanderLoc
    assert_true(leg ~= nil and #W.locMoves == 1, 'Suite 112: the leg is the wander destination and a walk was issued')
    local legDist = math.sqrt(leg.x ^ 2 + leg.y ^ 2)
    assert_true(legDist >= 125 and legDist <= 450, 'Suite 112: the point lies between 25% and 90% of the radius from the anchor')
    W.navActive = true
    W.now = W.now + 1
    assert_eq(W.rt.anchorRoamTick(), true, 'Suite 112: the leg continues while nav runs')
    assert_eq(#W.locMoves, 2, 'Suite 112: ... re-driving the walk')
    W.x, W.y = leg.x + 3, leg.y
    W.now = W.now + 1
    assert_eq(W.rt.anchorRoamTick(), false, 'Suite 112: within 10 units (2D) the leg is over')
    assert_nil(W.pursuit.wanderLoc, 'Suite 112: leg cleared on arrival')
    assert_eq(W.rt.anchorRoamNextAt, W.now + W.rt.ANCHOR_ROAM.PAUSE_SECS, 'Suite 112: a pause follows each arrival')
    assert_eq(W.rt.anchorRoamTick(), false, 'Suite 112: no new leg during the pause')
    W.now = W.now + W.rt.ANCHOR_ROAM.PAUSE_SECS + 0.1
    W.navActive = false
    assert_eq(W.rt.anchorRoamTick(), true, 'Suite 112: after the pause the next leg starts')
    W.now = W.now + 3
    assert_eq(W.rt.anchorRoamTick(), false, 'Suite 112: nav finishing short of the point (a Z guess) still ends the leg')
    assert_true(W.stops >= 1, 'Suite 112: ... with the walk stopped')
    W.now = W.now + W.rt.ANCHOR_ROAM.PAUSE_SECS + 0.1
    W.paths = function() return false end
    assert_eq(W.rt.anchorRoamTick(), false, 'Suite 112: no pathable point this round -> no leg')
    assert_nil(W.pursuit.wanderLoc, 'Suite 112: ... nothing set')
    W.paths = nil
    W.now = W.now + W.rt.ANCHOR_ROAM.PAUSE_SECS + 0.1
    W.sitting = true
    assert_eq(W.rt.anchorRoamTick(), false, 'Suite 112: a sitting character is not walked off')
    W.sitting = false
    W.ctrl.hunter_anchor_roam = false
    assert_eq(W.rt.anchorRoamTick(), false, 'Suite 112: roam off -> wait in place')
    W.ctrl.hunter_anchor_roam = true
    assert_eq(W.rt.anchorRoamTick(), true, 'Suite 112: roam on again -> a leg')
    W.ctrl.hunter_combat_loc = nil
    local stopsBefore = W.stops
    assert_eq(W.rt.anchorRoamTick(), false, 'Suite 112: clearing the anchor ends the roam')
    assert_true(W.pursuit.wanderLoc == nil and W.stops == stopsBefore + 1, 'Suite 112: ... leg cleared and the walk stopped')

    -- 8. Per-zone persistence
    W = makeWorld()
    W.ctrl.zone_anchors = {}
    W.ctrl.hunter_combat_loc = { x = 10, y = 20, z = 30 }
    W.ctrl.hunter_combat_radius = 400
    assert_eq(W.rt.saveZoneAnchor(), true, 'Suite 112: the anchor is saved for the zone')
    assert_tbl_eq(W.ctrl.zone_anchors.gfaydark, { x = 10, y = 20, z = 30, radius = 400 }, 'Suite 112: ... with its radius')
    assert_eq(W.saves, 1, 'Suite 112: ... and the loadout written')
    W.ctrl.hunter_combat_loc = nil
    W.ctrl.hunter_combat_radius = 250
    W.zone = 'crushbone'
    assert_eq(W.rt.loadZoneAnchor(), false, 'Suite 112: a zone without a saved anchor loads nothing')
    assert_nil(W.ctrl.hunter_combat_loc, 'Suite 112: ... and leaves the live anchor alone')
    W.zone = 'gfaydark'
    W.rt.anchorReturning = true
    assert_eq(W.rt.loadZoneAnchor(), true, 'Suite 112: zoning back restores the anchor')
    assert_tbl_eq(W.ctrl.hunter_combat_loc, { x = 10, y = 20, z = 30 }, 'Suite 112: ... position')
    assert_eq(W.ctrl.hunter_combat_radius, 400, 'Suite 112: ... and radius')
    assert_eq(W.rt.anchorReturning, false, 'Suite 112: ... with any return in progress cancelled')
    W.ctrl.hunter_combat_loc = nil
    W.rt.saveZoneAnchor()
    assert_nil(W.ctrl.zone_anchors.gfaydark, 'Suite 112: clearing the anchor forgets the zone entry')
    assert_eq(W.rt.loadZoneAnchor(), false, 'Suite 112: ... so nothing comes back')

    -- 9. Wiring
    local roam = src:match('function runtime%.findRoamTarget.-\nend\n')
    assert_true(roam:find('local huntAnchor, huntRadius = runtime.huntAnchor()', 1, true) ~= nil,
        'Suite 112: the roam scan takes its anchor from huntAnchor')
    assert_true(roam:find('radius = math.min(radius, math.ceil(md + huntRadius))', 1, true) ~= nil,
        'Suite 112: the roam scan query is tightened to the anchor circle')
    local mover = src:match('function runtime%.moveToward%(id, dist, followOnly%).-\nend\n')
    assert_true(mover:find('if not followOnly and runtime.anchorLeashed(id) then', 1, true) ~= nil,
        'Suite 112: moveToward is leashed to the anchor')
    local leashAt = mover:find('runtime.anchorLeashed(id)', 1, true)
    local arriveAt = mover:find('if d <= effectiveArrivalDist and', 1, true)
    local stallAt = mover:find('PURSUIT_STALL_TIMEOUT or pursuit.navStalls >= 3', 1, true)
    assert_true(arriveAt < leashAt and leashAt < stallAt, 'Suite 112: leash sits between the arrival check and the stall watchdog')
    assert_true(src:find('local function huntNPCXtarget(maxZ, maxDist)', 1, true) ~= nil, 'Suite 112: Hunt has its own XTarget pick')
    assert_true(src:find('return isUnreachable(id) or runtime.anchorRejects(id)', 1, true) ~= nil,
        'Suite 112: the Hunt XTarget pick skips adds outside the circle')
    local _, huntPicks = src:gsub('huntNPCXtarget%(maxHuntXtarZ, maxHuntXtarDist%)', '')
    assert_eq(huntPicks, 2, 'Suite 112: both Hunt XTarget picks go through it')
    assert_true(src:find("or tooFarAnchor and 'outside the combat anchor radius'", 1, true) ~= nil,
        'Suite 112: a roam target that left the circle is dropped')
    assert_true(src:find('if runtime.anchorReturnTick() then return end', 1, true) ~= nil,
        'Suite 112: the idle branch walks back to the anchor')
    assert_true(src:find('if runtime.anchorRoamTick() then return end', 1, true) ~= nil,
        'Suite 112: the idle branch roams inside the circle')
    assert_true(src:find("zone_anchors         = {},", 1, true) ~= nil and src:find("hunter_anchor_roam   = true,", 1, true) ~= nil,
        'Suite 112: defaults for the zone anchors and the roam switch')
    assert_true(src:find("if type(c.zone_anchors) ~= 'table' then c.zone_anchors = {} end", 1, true) ~= nil,
        'Suite 112: sanitizer covers zone_anchors')
    local apply = src:match('function runtime%.applyEntry%(e%).-\nend\n')
    assert_true(apply:find('ctrl.hunter_combat_loc = nil\n        runtime.loadZoneAnchor()', 1, true) ~= nil,
        'Suite 112: loading the loadout restores this zone\'s anchor')
    assert_true(src:find('if runtime.loadZoneAnchor() then\n        print(string.format(\'\\ag[Triune]\\ax Loaded saved combat anchor for %s', 1, true) ~= nil,
        'Suite 112: zoning in restores the zone\'s anchor')
    local _, zoneSaves = src:gsub('runtime%.saveZoneAnchor%(%)', '')
    assert_true(zoneSaves >= 3, 'Suite 112: Set / Clear / radius all update the zone entry')
end

print(string.format('\n=== Results: %d passed, %d failed ===', pass, fail))
if fail > 0 then
    print('\nFailures:')
    for _, e in ipairs(errors) do print(e) end
    os.exit(1)
else
    print('All tests passed.')
    os.exit(0)
end
